def _domain_weaver_worker_start_context_gate(root: Path, *, lane_id: str | None = None) -> dict[str, Any]:
    """Gate Domain Weaver worker starts on a fresh active context resolver mount."""

    try:
        resolver = resolve_domain_active_context(
            root,
            domain_id=DOMAIN_WEAVER_WORKER_START_CONTEXT_RESOLVER_DOMAIN_ID,
            lane=str(lane_id or "").strip() or None,
            max_age_seconds=DOMAIN_WEAVER_WORKER_START_CONTEXT_MAX_AGE_SECONDS,
        )
    except Exception as exc:  # pragma: no cover - defensive gate failure.
        resolver = {
            "ok": False,
            "resolver_id": DOMAIN_WEAVER_WORKER_START_CONTEXT_RESOLVER_DOMAIN_ID,
            "lane": str(lane_id or "").strip(),
            "selected": None,
            "blockers": ["context_active_resolver_exception"],
            "next_action": "repair_or_reissue_active_context_package",
            "error": type(exc).__name__,
            "detail": str(exc),
            "authority": {
                "accepted_state": False,
                "production_authority": False,
                "live_execution_authority": False,
                "secrets_authority": False,
                "materialization_write_authority": False,
            },
        }
    gate = dict(resolver)
    gate["schema_id"] = "ion.domain_weaver.worker_start_context_gate.v0_1_candidate"
    gate["resolver_schema_id"] = resolver.get("schema_id")
    gate["worker_start_allowed"] = bool(resolver.get("ok"))
    gate["finding"] = (
        "context_active_resolver_ready"
        if gate["worker_start_allowed"]
        else "context_active_resolver_blocked"
    )
    gate["required_domain_id"] = DOMAIN_WEAVER_WORKER_START_CONTEXT_RESOLVER_DOMAIN_ID
    gate["required_lane_id"] = str(lane_id or "").strip()
    gate["max_context_age_seconds"] = DOMAIN_WEAVER_WORKER_START_CONTEXT_MAX_AGE_SECONDS
    gate["authority"] = {
        "accepted_state": False,
        "accepted_state_authority": False,
        "production_authority": False,
        "live_execution_authority": False,
        "secrets_authority": False,
        "materialization_write_authority": False,
    }
    return gate


def _domain_weaver_worker_start_context_block_result(
    gate: Mapping[str, Any],
    *,
    request_path: str = "",
) -> dict[str, Any]:
    return {
        "schema_id": "ion.domain_weaver.worker_start_context_block.v0_1_candidate",
        "request_path": request_path,
        "ok": False,
        "result": "WORKER_START_BLOCKED_CONTEXT_INACTIVE",
        "finding": "context_active_resolver_blocked",
        "worker_start_status": "worker_start_blocked_context_inactive",
        "worker_started": False,
        "worker_start_allowed": False,
        "resolver_id": gate.get("resolver_id"),
        "selected": gate.get("selected"),
        "blockers": list(gate.get("blockers") or []),
        "next_action": gate.get("next_action"),
        "context_active_resolver": dict(gate),
        "authority": {
            "accepted_state": False,
            "accepted_state_authority": False,
            "production_authority": False,
            "live_execution_authority": False,
            "secrets_authority": False,
            "materialization_write_authority": False,
        },
    }


