def build_domain_weaver_codex_work_request_template(
    *,
    request_id: str,
    objective: str,
    requested_by: str,
    work_class: str,
    lane_id: str,
    route_family: str,
    request_kind: str,
    agent_role: str,
    required_context_reads: Sequence[Any],
    supporting_roles: Sequence[Any] = (),
    return_contract_sections: Sequence[Any] = DEFAULT_RETURN_CONTRACT_SECTIONS,
    dedupe_key: str | None = None,
    idempotency_key: str | None = None,
    risk_level: str = "critical",
    requested_model: str = "gpt-5.5",
    requested_reasoning_effort: str = "xhigh",
    requested_service_tier: str = "fast",
    model_override_reason: str | None = None,
    payload_key: str | None = None,
    payload: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Compatibility wrapper preserving the Codex work request template payload."""

    return _build_domain_weaver_codex_work_request_template(
        request_id=request_id,
        objective=objective,
        requested_by=requested_by,
        work_class=work_class,
        lane_id=lane_id,
        route_family=route_family,
        request_kind=request_kind,
        agent_role=agent_role,
        required_context_reads=required_context_reads,
        supporting_roles=supporting_roles,
        return_contract_sections=return_contract_sections,
        dedupe_key=dedupe_key,
        idempotency_key=idempotency_key,
        risk_level=risk_level,
        requested_model=requested_model,
        requested_reasoning_effort=requested_reasoning_effort,
        requested_service_tier=requested_service_tier,
        model_override_reason=model_override_reason,
        payload_key=payload_key,
        payload=payload,
    )


