def _domain_weaver_materialize_latest_with_snapshot(
    root: Path,
    *,
    latest_path: Path,
    payload: dict[str, Any],
    artifact_role: str,
    source_action_id: str = "",
    source_packet_id: str = "",
) -> dict[str, Any]:
    latest_rel = latest_path.as_posix()
    family = latest_path.name.replace(".latest.json", "").replace(".json", "")
    existing_latest_path = root / latest_path
    materialized_at = _now()
    existing_latest: dict[str, Any] = {}
    if existing_latest_path.is_file():
        try:
            existing_payload = json.loads(existing_latest_path.read_text(encoding="utf-8"))
            if isinstance(existing_payload, dict):
                existing_latest = existing_payload
        except Exception:
            existing_latest = {}
    def _payload_action_source(data: Mapping[str, Any]) -> tuple[str, str]:
        lineage_data = data.get("latest_pointer_lineage")
        lineage_map = lineage_data if isinstance(lineage_data, Mapping) else {}
        return (
            str(data.get("latest_pointer_source_action_id") or lineage_map.get("source_action_id") or "").strip(),
            str(data.get("latest_pointer_source_packet_id") or lineage_map.get("source_packet_id") or "").strip(),
        )
    def _lineage_payload_sha256(data: Mapping[str, Any]) -> str:
        payload_copy = dict(data)
        payload_copy.pop("latest_pointer_lineage", None)
        payload_copy.pop("latest_write_suppressed", None)
        payload_copy.pop("latest_write_suppressed_reason", None)
        return _stable_json_sha256(payload_copy)
    if str(source_action_id or "").strip() or str(source_packet_id or "").strip():
        payload["latest_pointer_source_action_id"] = source_action_id
        payload["latest_pointer_source_packet_id"] = source_packet_id
    snapshot_rel = (
        latest_path.parent
        / "snapshots"
        / family
        / f"{_stamp_micro()}_{artifact_role}.json"
    )
    payload_sha256 = _stable_json_sha256(payload)
    snapshot = {
        "schema_id": "ion.domain_weaver.latest_pointer_snapshot.v1",
        "created_at": materialized_at,
        "artifact_role": artifact_role,
        "latest_path": latest_rel,
        "payload_sha256": payload_sha256,
        "payload": payload,
        "source_action_id": source_action_id,
        "source_packet_id": source_packet_id,
    }
    snapshot_sha256 = _write_stable_json_and_hash(root / snapshot_rel, snapshot)
    existing_lineage = (
        existing_latest.get("latest_pointer_lineage")
        if isinstance(existing_latest.get("latest_pointer_lineage"), Mapping)
        else {}
    )
    existing_source_action_id, existing_source_packet_id = _payload_action_source(existing_latest)
    existing_action_sourced = bool(existing_source_action_id or existing_source_packet_id)
    volatile_recompute = not (
        str(source_action_id or "").strip()
        or str(source_packet_id or "").strip()
    )
    action_snapshot_payload: dict[str, Any] = {}
    action_snapshot_path = ""
    action_snapshot_source_action_id = ""
    action_snapshot_source_packet_id = ""
    if volatile_recompute and not existing_action_sourced:
        snapshots_dir = root / latest_path.parent / "snapshots" / family
        for candidate in sorted(snapshots_dir.glob("*.json"), reverse=True):
            if candidate == root / snapshot_rel:
                continue
            candidate_snapshot = _read_json_file(candidate)
            candidate_payload = candidate_snapshot.get("payload")
            if not isinstance(candidate_payload, dict):
                continue
            payload_source_action_id, payload_source_packet_id = _payload_action_source(candidate_payload)
            snapshot_source_action_id = str(
                candidate_snapshot.get("source_action_id") or payload_source_action_id or ""
            ).strip()
            snapshot_source_packet_id = str(
                candidate_snapshot.get("source_packet_id") or payload_source_packet_id or ""
            ).strip()
            if not (snapshot_source_action_id or snapshot_source_packet_id):
                continue
            action_snapshot_payload = dict(candidate_payload)
            action_snapshot_payload["latest_pointer_source_action_id"] = snapshot_source_action_id
            action_snapshot_payload["latest_pointer_source_packet_id"] = snapshot_source_packet_id
            action_snapshot_path = _rel(root, candidate)
            action_snapshot_source_action_id = snapshot_source_action_id
            action_snapshot_source_packet_id = snapshot_source_packet_id
            break
    if volatile_recompute and action_snapshot_payload:
        restored_payload_sha256 = _stable_json_sha256(action_snapshot_payload)
        restored_latest_sha256 = _write_stable_json_and_hash(root / latest_path, action_snapshot_payload)
        lineage = {
            "schema_id": "ion.domain_weaver.latest_pointer_lineage.v1",
            "lineage_status": "snapshot_only_restored_action_sourced_latest",
            "lineage_blockers": [],
            "materialized_at": materialized_at,
            "artifact_role": artifact_role,
            "latest_path": latest_rel,
            "latest_payload_sha256": restored_payload_sha256,
            "latest_payload_sha256_at_action": restored_payload_sha256,
            "latest_full_sha256_at_action": restored_latest_sha256,
            "current_latest_full_sha256": restored_latest_sha256,
            "current_latest_payload_sha256": _lineage_payload_sha256(action_snapshot_payload),
            "volatile_payload_sha256": payload_sha256,
            "volatile_recompute_snapshot_path": snapshot_rel.as_posix(),
            "volatile_recompute_snapshot_sha256": snapshot_sha256,
            "volatile_recompute_snapshot_payload_sha256": payload_sha256,
            "snapshot_path": snapshot_rel.as_posix(),
            "snapshot_sha256": snapshot_sha256,
            "snapshot_payload_sha256": payload_sha256,
            "restored_action_snapshot_path": action_snapshot_path,
            "restored_latest_sha256": restored_latest_sha256,
            "source_action_id": action_snapshot_source_action_id,
            "source_packet_id": action_snapshot_source_packet_id,
            "volatile_source_action_id": source_action_id,
            "volatile_source_packet_id": source_packet_id,
            "latest_write_decision": "suppressed_restored_action_sourced_latest",
            "latest_write_suppressed": True,
            "latest_write_suppressed_reason": (
                "volatile_recompute_restored_latest_from_action_sourced_snapshot"
            ),
            "operator_action_latest_pointer_unreconciled": False,
        }
        payload["latest_pointer_lineage"] = dict(lineage)
        payload["latest_write_suppressed"] = True
        payload["latest_write_suppressed_reason"] = lineage["latest_write_suppressed_reason"]
        return lineage
    if volatile_recompute and existing_action_sourced:
        preserved_latest_sha256 = _stable_json_sha256(existing_latest)
        preserved_latest_payload_sha256 = _lineage_payload_sha256(existing_latest)
        lineage = {
            "schema_id": "ion.domain_weaver.latest_pointer_lineage.v1",
            "lineage_status": "snapshot_only_preserved_action_sourced_latest",
            "lineage_blockers": [],
            "materialized_at": materialized_at,
            "artifact_role": artifact_role,
            "latest_path": latest_rel,
            "latest_payload_sha256": existing_lineage.get("latest_payload_sha256")
            or preserved_latest_payload_sha256,
            "latest_payload_sha256_at_action": existing_lineage.get("latest_payload_sha256")
            or preserved_latest_payload_sha256,
            "latest_full_sha256_at_action": preserved_latest_sha256,
            "current_latest_full_sha256": preserved_latest_sha256,
            "current_latest_payload_sha256": preserved_latest_payload_sha256,
            "volatile_payload_sha256": payload_sha256,
            "volatile_recompute_snapshot_path": snapshot_rel.as_posix(),
            "volatile_recompute_snapshot_sha256": snapshot_sha256,
            "volatile_recompute_snapshot_payload_sha256": payload_sha256,
            "snapshot_path": snapshot_rel.as_posix(),
            "snapshot_sha256": snapshot_sha256,
            "snapshot_payload_sha256": payload_sha256,
            "source_action_id": existing_lineage.get("source_action_id") or existing_source_action_id,
            "source_packet_id": existing_lineage.get("source_packet_id") or existing_source_packet_id,
            "volatile_source_action_id": source_action_id,
            "volatile_source_packet_id": source_packet_id,
            "latest_write_decision": "suppressed_preserved_action_sourced_latest",
            "latest_write_suppressed": True,
            "latest_write_suppressed_reason": (
                "volatile_recompute_cannot_overwrite_action_sourced_latest"
            ),
            "preserved_latest_sha256": preserved_latest_sha256,
            "operator_action_latest_pointer_unreconciled": False,
        }
        payload["latest_pointer_lineage"] = dict(lineage)
        payload["latest_write_suppressed"] = True
        payload["latest_write_suppressed_reason"] = lineage["latest_write_suppressed_reason"]
        return lineage
    lineage = {
        "schema_id": "ion.domain_weaver.latest_pointer_lineage.v1",
        "lineage_status": "reconciled",
        "lineage_blockers": [],
        "materialized_at": materialized_at,
        "artifact_role": artifact_role,
        "latest_path": latest_rel,
        "latest_payload_sha256": payload_sha256,
        "latest_payload_sha256_at_action": payload_sha256,
        "snapshot_path": snapshot_rel.as_posix(),
        "snapshot_sha256": snapshot_sha256,
        "snapshot_payload_sha256": payload_sha256,
        "source_action_id": source_action_id,
        "source_packet_id": source_packet_id,
        "latest_write_decision": "written",
        "operator_action_latest_pointer_unreconciled": False,
    }
    payload["latest_pointer_lineage"] = dict(lineage)
    latest_sha256 = _write_stable_json_and_hash(root / latest_path, payload)
    lineage["latest_sha256"] = latest_sha256
    lineage["latest_full_sha256_at_action"] = latest_sha256
    lineage["current_latest_full_sha256"] = latest_sha256
    lineage["current_latest_payload_sha256"] = payload_sha256
    payload["latest_pointer_lineage"]["latest_sha256"] = latest_sha256
    return lineage


def _domain_weaver_latest_pointer_lineage_summary(
    refs: Mapping[str, Mapping[str, Any]],
    *,
    operator_action_created_at: str = "",
    root: Path | None = None,
    expected_source_action_id: str = "",
    expected_source_packet_id: str = "",
    require_current_action_lineage: bool = False,
) -> dict[str, Any]:
    blockers: list[str] = []
    normalized: dict[str, dict[str, Any]] = {}
    source_action_ids: set[str] = set()
    source_packet_ids: set[str] = set()
    root_path = Path(root).resolve(strict=False) if root is not None else None
    expected_action = str(expected_source_action_id or "").strip()
    expected_packet = str(expected_source_packet_id or "").strip()

    def _payload_content_sha256(data: Mapping[str, Any]) -> str:
        payload_copy = dict(data)
        payload_copy.pop("latest_pointer_lineage", None)
        payload_copy.pop("latest_write_suppressed", None)
        payload_copy.pop("latest_write_suppressed_reason", None)
        return _stable_json_sha256(payload_copy)

    def _resolve_lineage_path(rel_path: str, *, ref_name: str, field_name: str) -> Path | None:
        if root_path is None:
            return None
        candidate_path = Path(rel_path)
        if candidate_path.is_absolute():
            blockers.append(f"{ref_name}_{field_name}_absolute")
            return None
        resolved = (root_path / candidate_path).resolve(strict=False)
        try:
            resolved.relative_to(root_path)
        except ValueError:
            blockers.append(f"{ref_name}_{field_name}_outside_root")
            return None
        return resolved

    for name, ref in refs.items():
        row = dict(_as_mapping(ref))
        ref_name = str(name)
        source_action_id = str(row.get("source_action_id") or "").strip()
        source_packet_id = str(row.get("source_packet_id") or "").strip()
        if source_action_id:
            source_action_ids.add(source_action_id)
        elif require_current_action_lineage:
            blockers.append(f"{ref_name}_source_action_id_missing")
        if source_packet_id:
            source_packet_ids.add(source_packet_id)
        elif require_current_action_lineage:
            blockers.append(f"{ref_name}_source_packet_id_missing")
        if expected_action and source_action_id and source_action_id != expected_action:
            blockers.append(f"{ref_name}_source_action_id_mismatch")
        if expected_packet and source_packet_id and source_packet_id != expected_packet:
            blockers.append(f"{ref_name}_source_packet_id_mismatch")
        if require_current_action_lineage and str(row.get("lineage_status") or "") != "reconciled":
            blockers.append(f"{ref_name}_lineage_status_not_reconciled")
        if require_current_action_lineage and bool(row.get("latest_write_suppressed")):
            blockers.append(f"{ref_name}_latest_write_suppressed")
        if require_current_action_lineage and str(row.get("latest_write_decision") or "") not in {"", "written"}:
            blockers.append(f"{ref_name}_latest_write_decision_not_written")
        if not row.get("snapshot_path") or not row.get("snapshot_sha256"):
            blockers.append(f"{ref_name}_snapshot_missing")
        if not row.get("latest_path"):
            blockers.append(f"{ref_name}_latest_path_missing")
        if row.get("operator_action_latest_pointer_unreconciled"):
            blockers.append(f"{ref_name}_operator_action_latest_pointer_unreconciled")
        if root_path is not None:
            latest_rel = str(row.get("latest_path") or "").strip()
            snapshot_rel = str(row.get("snapshot_path") or "").strip()
            if latest_rel:
                latest_file = _resolve_lineage_path(latest_rel, ref_name=ref_name, field_name="latest_path")
                if latest_file is None:
                    normalized[ref_name] = row
                    continue
                if latest_file.is_file():
                    current_latest_full_sha256 = _sha256_file(latest_file)
                    latest_payload = _read_json_file(latest_file)
                    current_latest_payload_sha256 = (
                        _payload_content_sha256(latest_payload)
                        if isinstance(latest_payload, Mapping)
                        else ""
                    )
                    row["current_latest_full_sha256"] = current_latest_full_sha256
                    row["current_latest_payload_sha256"] = current_latest_payload_sha256
                    expected_latest_full_sha256 = str(
                        row.get("latest_full_sha256_at_action")
                        or row.get("current_latest_full_sha256_at_action")
                        or row.get("latest_sha256")
                        or row.get("restored_latest_sha256")
                        or row.get("preserved_latest_sha256")
                        or ""
                    ).strip()
                    expected_latest_payload_sha256 = str(
                        row.get("latest_payload_sha256_at_action")
                        or row.get("latest_payload_sha256")
                        or ""
                    ).strip()
                    if require_current_action_lineage and not expected_latest_full_sha256:
                        blockers.append(f"{ref_name}_latest_full_sha256_expected_missing")
                    if require_current_action_lineage and not expected_latest_payload_sha256:
                        blockers.append(f"{ref_name}_latest_payload_sha256_expected_missing")
                    if expected_latest_full_sha256 and expected_latest_full_sha256 != current_latest_full_sha256:
                        blockers.append(f"{ref_name}_current_latest_full_sha256_mismatch")
                    if (
                        expected_latest_payload_sha256
                        and current_latest_payload_sha256
                        and expected_latest_payload_sha256 != current_latest_payload_sha256
                    ):
                        blockers.append(f"{ref_name}_current_latest_payload_sha256_mismatch")
                else:
                    blockers.append(f"{ref_name}_latest_file_missing")
            if snapshot_rel:
                snapshot_file = _resolve_lineage_path(snapshot_rel, ref_name=ref_name, field_name="snapshot_path")
                if snapshot_file is None:
                    normalized[ref_name] = row
                    continue
                if snapshot_file.is_file():
                    current_snapshot_sha256 = _sha256_file(snapshot_file)
                    snapshot_payload = _read_json_file(snapshot_file)
                    current_snapshot_payload_sha256 = str(
                        snapshot_payload.get("payload_sha256") if isinstance(snapshot_payload, Mapping) else ""
                    )
                    row["current_snapshot_sha256"] = current_snapshot_sha256
                    row["current_snapshot_payload_sha256"] = current_snapshot_payload_sha256
                    expected_snapshot_sha256 = str(row.get("snapshot_sha256") or "").strip()
                    expected_snapshot_payload_sha256 = str(row.get("snapshot_payload_sha256") or "").strip()
                    if require_current_action_lineage and not expected_snapshot_payload_sha256:
                        blockers.append(f"{ref_name}_snapshot_payload_sha256_expected_missing")
                    if expected_snapshot_sha256 and expected_snapshot_sha256 != current_snapshot_sha256:
                        blockers.append(f"{ref_name}_snapshot_sha256_mismatch")
                    if (
                        expected_snapshot_payload_sha256
                        and current_snapshot_payload_sha256
                        and expected_snapshot_payload_sha256 != current_snapshot_payload_sha256
                    ):
                        blockers.append(f"{ref_name}_snapshot_payload_sha256_mismatch")
                else:
                    blockers.append(f"{ref_name}_snapshot_file_missing")
        normalized[ref_name] = row
    if len(source_action_ids) > 1:
        blockers.append("mixed_source_action_ids")
    if len(source_packet_ids) > 1:
        blockers.append("mixed_source_packet_ids")
    return {
        "schema_id": "ion.domain_weaver.operator_action_latest_pointer_lineage_summary.v1",
        "lineage_status": "reconciled" if not blockers else "unreconciled",
        "lineage_blockers": sorted(set(blockers)),
        "operator_action_created_at": operator_action_created_at,
        "operator_action_latest_pointer_unreconciled": bool(blockers),
        "strict_latest_pointer_lineage_gate_clean": not bool(blockers),
        "expected_source_action_id": expected_action,
        "expected_source_packet_id": expected_packet,
        "source_action_ids": sorted(source_action_ids),
        "source_packet_ids": sorted(source_packet_ids),
        "refs": normalized,
    }


def _domain_weaver_latest_pointer_self_lineage_payload(
    payload: Mapping[str, Any],
) -> dict[str, Any]:
    payload_copy = dict(payload)
    payload_copy.pop("latest_pointer_self_lineage", None)
    payload_copy.pop("latest_pointer_self_lineage_receipt_sha256", None)
    return payload_copy


def _domain_weaver_latest_pointer_self_lineage_path(
    root: Path,
    rel_path: str,
    *,
    blockers: list[str],
    field_name: str,
) -> Path | None:
    raw_path = str(rel_path or "").strip()
    if not raw_path:
        blockers.append(f"{field_name}_missing")
        return None
    candidate = Path(raw_path)
    if candidate.is_absolute():
        blockers.append(f"{field_name}_absolute")
        return None
    root_path = root.resolve(strict=False)
    resolved = (root / candidate).resolve(strict=False)
    try:
        resolved.relative_to(root_path)
    except ValueError:
        blockers.append(f"{field_name}_outside_root")
        return None
    return resolved


def _domain_weaver_bind_latest_pointer_self_lineage(
    root: Path,
    *,
    latest_path: Path,
    artifact_role: str,
    source_action_id: str = "",
    source_packet_id: str = "",
) -> dict[str, Any]:
    latest_rel = latest_path.as_posix()
    latest_file = root / latest_path
    if not latest_file.is_file():
        return {
            "schema_id": "ion.domain_weaver.latest_pointer_self_lineage_bind.v0_1_candidate",
            "ok": False,
            "lineage_status": "blocked",
            "lineage_blockers": ["latest_file_missing"],
            "latest_path": latest_rel,
            "accepted_state_claimed": False,
            "production_authority": False,
            "live_execution_authority": False,
        }
    latest_payload = _read_json_file(latest_file)
    if not isinstance(latest_payload, Mapping) or not latest_payload:
        return {
            "schema_id": "ion.domain_weaver.latest_pointer_self_lineage_bind.v0_1_candidate",
            "ok": False,
            "lineage_status": "blocked",
            "lineage_blockers": ["latest_json_missing_or_invalid"],
            "latest_path": latest_rel,
            "accepted_state_claimed": False,
            "production_authority": False,
            "live_execution_authority": False,
        }

    payload = _domain_weaver_latest_pointer_self_lineage_payload(latest_payload)
    receipt_integrity = dict(_as_mapping(payload.get("receipt_integrity_readback")))
    readback_blockers = [
        str(blocker)
        for blocker in list(receipt_integrity.get("readback_blockers") or [])
        if str(blocker) != "final_fanin_latest_not_latest_pointer_self_lineaged"
    ]
    receipt_integrity["strict_self_lineage_bound"] = True
    receipt_integrity["advance_to_limited_swarm_allowed_by_this_readback"] = False
    receipt_integrity["readback_blockers"] = readback_blockers
    receipt_integrity["status"] = "candidate_current_sha_fields_reconciled_self_lineage_bound"
    receipt_integrity["self_lineage_bind_status"] = "candidate_bound_external_sidecar"
    payload["receipt_integrity_readback"] = receipt_integrity
    payload["ready_for_limited_exact_path_swarm"] = False
    payload["ready_for_broader_swarm"] = False
    payload["ready_for_production"] = False
    payload["verdict"] = "NOT_READY_BLOCKED_BY_BROAD_VALIDATION_AND_ACCEPTED_STATE_GATES"
    payload["status"] = "exact_reissue_request_dispatch_fanin_self_lineage_bound_candidate"

    bound_at = _now()
    family = latest_path.name.replace(".latest.json", "").replace(".json", "")
    snapshot_rel = (
        latest_path.parent
        / "snapshots"
        / family
        / f"{_stamp_micro()}_{_safe_id(artifact_role)}_self_lineage_payload.json"
    )
    canonical_payload_sha256 = _stable_json_sha256(payload)
    snapshot = {
        "schema_id": "ion.domain_weaver.latest_pointer_self_lineage_payload_snapshot.v0_1_candidate",
        "created_at": bound_at,
        "artifact_role": artifact_role,
        "latest_path": latest_rel,
        "canonical_payload_sha256": canonical_payload_sha256,
        "payload": payload,
        "source_action_id": source_action_id,
        "source_packet_id": source_packet_id,
        "accepted_state_claimed": False,
        "production_authority": False,
        "live_execution_authority": False,
    }
    snapshot_sha256 = _write_stable_json_and_hash(root / snapshot_rel, snapshot)
    sidecar_rel = (
        latest_path.parent
        / "snapshots"
        / family
        / f"{_stamp_micro()}_{_safe_id(artifact_role)}_latest_pointer_self_lineage_receipt.json"
    )
    lineage = {
        "schema_id": "ion.domain_weaver.latest_pointer_self_lineage.v0_1_candidate",
        "lineage_status": "bound_external_sidecar",
        "lineage_blockers": [],
        "bound_at": bound_at,
        "artifact_role": artifact_role,
        "latest_path": latest_rel,
        "canonical_payload_sha256": canonical_payload_sha256,
        "snapshot_path": snapshot_rel.as_posix(),
        "snapshot_sha256": snapshot_sha256,
        "snapshot_payload_sha256": canonical_payload_sha256,
        "sidecar_receipt_path": sidecar_rel.as_posix(),
        "full_latest_sha256_location": "external_sidecar_receipt",
        "source_action_id": source_action_id,
        "source_packet_id": source_packet_id,
        "accepted_state_claimed": False,
        "production_authority": False,
        "live_execution_authority": False,
    }
    payload["latest_pointer_self_lineage"] = lineage
    latest_sha256 = _write_stable_json_and_hash(latest_file, payload)
    sidecar = {
        "schema_id": "ion.domain_weaver.latest_pointer_self_lineage_sidecar_receipt.v0_1_candidate",
        "created_at": bound_at,
        "artifact_role": artifact_role,
        "latest_path": latest_rel,
        "latest_full_sha256": latest_sha256,
        "canonical_payload_sha256": canonical_payload_sha256,
        "snapshot_path": snapshot_rel.as_posix(),
        "snapshot_sha256": snapshot_sha256,
        "snapshot_payload_sha256": canonical_payload_sha256,
        "source_action_id": source_action_id,
        "source_packet_id": source_packet_id,
        "accepted_state_claimed": False,
        "production_authority": False,
        "live_execution_authority": False,
        "non_claims": [
            "The sidecar binds the latest file full SHA outside the self-referential latest JSON.",
            "This is candidate receipt integrity only; it does not grant production, live execution, materialization, or accepted-state authority.",
        ],
    }
    sidecar_sha256 = _write_stable_json_and_hash(root / sidecar_rel, sidecar)
    summary = _domain_weaver_latest_pointer_self_lineage_summary(
        root,
        latest_path=latest_path,
        expected_source_action_id=source_action_id,
        expected_source_packet_id=source_packet_id,
    )
    return {
        "schema_id": "ion.domain_weaver.latest_pointer_self_lineage_bind.v0_1_candidate",
        "ok": bool(summary.get("strict_self_lineage_gate_clean")),
        "lineage_status": summary.get("lineage_status"),
        "lineage_blockers": summary.get("lineage_blockers") or [],
        "latest_path": latest_rel,
        "latest_full_sha256": latest_sha256,
        "canonical_payload_sha256": canonical_payload_sha256,
        "snapshot_path": snapshot_rel.as_posix(),
        "snapshot_sha256": snapshot_sha256,
        "sidecar_receipt_path": sidecar_rel.as_posix(),
        "sidecar_receipt_sha256": sidecar_sha256,
        "summary": summary,
        "accepted_state_claimed": False,
        "production_authority": False,
        "live_execution_authority": False,
    }


def _domain_weaver_latest_pointer_self_lineage_summary(
    root: Path,
    *,
    latest_path: Path,
    expected_source_action_id: str = "",
    expected_source_packet_id: str = "",
) -> dict[str, Any]:
    blockers: list[str] = []
    latest_rel = latest_path.as_posix()
    latest_file = _domain_weaver_latest_pointer_self_lineage_path(
        root,
        latest_rel,
        blockers=blockers,
        field_name="latest_path",
    )
    latest_payload: dict[str, Any] = {}
    current_latest_full_sha256 = ""
    current_latest_payload_sha256 = ""
    lineage: dict[str, Any] = {}
    sidecar: dict[str, Any] = {}
    sidecar_rel = ""
    snapshot_rel = ""
    snapshot_sha256 = ""
    if latest_file and latest_file.is_file():
        current_latest_full_sha256 = _sha256_file(latest_file)
        latest_payload = _read_json_file(latest_file)
        if not isinstance(latest_payload, dict) or not latest_payload:
            blockers.append("latest_json_missing_or_invalid")
            latest_payload = {}
        else:
            lineage = dict(_as_mapping(latest_payload.get("latest_pointer_self_lineage")))
            if not lineage:
                blockers.append("latest_pointer_self_lineage_missing")
            if "latest_full_sha256" in lineage:
                blockers.append("latest_pointer_self_lineage_embeds_full_latest_sha256")
            if str(lineage.get("lineage_status") or "") != "bound_external_sidecar":
                blockers.append("latest_pointer_self_lineage_status_not_bound_external_sidecar")
            source_action_id = str(lineage.get("source_action_id") or "").strip()
            source_packet_id = str(lineage.get("source_packet_id") or "").strip()
            expected_action = str(expected_source_action_id or "").strip()
            expected_packet = str(expected_source_packet_id or "").strip()
            if expected_action and source_action_id != expected_action:
                blockers.append("source_action_id_mismatch")
            if expected_packet and source_packet_id != expected_packet:
                blockers.append("source_packet_id_mismatch")
            payload_copy = _domain_weaver_latest_pointer_self_lineage_payload(latest_payload)
            current_latest_payload_sha256 = _stable_json_sha256(payload_copy)
            expected_payload_sha = str(lineage.get("canonical_payload_sha256") or "").strip()
            if not expected_payload_sha:
                blockers.append("canonical_payload_sha256_missing")
            elif expected_payload_sha != current_latest_payload_sha256:
                blockers.append("canonical_payload_sha256_mismatch")
            sidecar_rel = str(lineage.get("sidecar_receipt_path") or "").strip()
            snapshot_rel = str(lineage.get("snapshot_path") or "").strip()
            snapshot_sha256 = str(lineage.get("snapshot_sha256") or "").strip()
    else:
        blockers.append("latest_file_missing")

    sidecar_file = _domain_weaver_latest_pointer_self_lineage_path(
        root,
        sidecar_rel,
        blockers=blockers,
        field_name="sidecar_receipt_path",
    ) if sidecar_rel else None
    if sidecar_file:
        if sidecar_file.is_file():
            sidecar = _read_json_file(sidecar_file)
            if not isinstance(sidecar, dict) or not sidecar:
                blockers.append("sidecar_receipt_json_missing_or_invalid")
                sidecar = {}
            else:
                if str(sidecar.get("latest_full_sha256") or "") != current_latest_full_sha256:
                    blockers.append("sidecar_latest_full_sha256_mismatch")
                if str(sidecar.get("canonical_payload_sha256") or "") != current_latest_payload_sha256:
                    blockers.append("sidecar_canonical_payload_sha256_mismatch")
                if str(sidecar.get("latest_path") or "") != latest_rel:
                    blockers.append("sidecar_latest_path_mismatch")
                if expected_source_action_id and str(sidecar.get("source_action_id") or "") != expected_source_action_id:
                    blockers.append("sidecar_source_action_id_mismatch")
                if expected_source_packet_id and str(sidecar.get("source_packet_id") or "") != expected_source_packet_id:
                    blockers.append("sidecar_source_packet_id_mismatch")
        else:
            blockers.append("sidecar_receipt_file_missing")

    snapshot_file = _domain_weaver_latest_pointer_self_lineage_path(
        root,
        snapshot_rel,
        blockers=blockers,
        field_name="snapshot_path",
    ) if snapshot_rel else None
    if snapshot_file:
        if snapshot_file.is_file():
            current_snapshot_sha256 = _sha256_file(snapshot_file)
            snapshot_payload = _read_json_file(snapshot_file)
            if snapshot_sha256 and snapshot_sha256 != current_snapshot_sha256:
                blockers.append("snapshot_sha256_mismatch")
            snapshot_payload_sha256 = str(
                snapshot_payload.get("canonical_payload_sha256")
                if isinstance(snapshot_payload, Mapping)
                else ""
            )
            expected_snapshot_payload_sha256 = str(
                lineage.get("snapshot_payload_sha256")
                or lineage.get("canonical_payload_sha256")
                or ""
            )
            if not snapshot_payload_sha256:
                blockers.append("snapshot_payload_sha256_missing")
            elif expected_snapshot_payload_sha256 and snapshot_payload_sha256 != expected_snapshot_payload_sha256:
                blockers.append("snapshot_payload_sha256_mismatch")
        else:
            blockers.append("snapshot_file_missing")

    blockers = sorted(set(blockers))
    return {
        "schema_id": "ion.domain_weaver.latest_pointer_self_lineage_summary.v0_1_candidate",
        "lineage_status": "reconciled" if not blockers else "unreconciled",
        "lineage_blockers": blockers,
        "strict_self_lineage_gate_clean": not bool(blockers),
        "latest_path": latest_rel,
        "current_latest_full_sha256": current_latest_full_sha256,
        "current_latest_payload_sha256": current_latest_payload_sha256,
        "sidecar_receipt_path": sidecar_rel,
        "snapshot_path": snapshot_rel,
        "source_action_id": str(lineage.get("source_action_id") or ""),
        "source_packet_id": str(lineage.get("source_packet_id") or ""),
        "accepted_state_claimed": False,
        "production_authority": False,
        "live_execution_authority": False,
    }


def _domain_weaver_first_int_after_label(text: str, label: str, *, default: int = 0) -> int:
    match = re.search(rf"{re.escape(label)}\s*[:=]\s*(-?\d+)", text)
    if not match:
        return default
    try:
        return int(match.group(1))
    except ValueError:
        return default


def _domain_weaver_ui_canon_context_reads(root: Path | None = None, *, existing_only: bool = False) -> list[str]:
    paths = [path.as_posix() for path in DOMAIN_WEAVER_UI_CANON_CONTEXT_PATHS]
    if existing_only and root is not None:
        paths = [path for path in paths if (root / path).exists()]
    return _clean_list(paths)


def _latest_package(root: Path, mount: Mapping[str, Any]) -> dict[str, Any]:
    mount_id = str(mount.get("mount_id") or "").strip()
    if not mount_id:
        return {"exists": False, "drop_in_ready": False, "latest_path": ""}
    latest_path = root / PORTABLE_PACKAGE_ROOT / mount_id / "LATEST.json"
    payload: dict[str, Any] = {}
    if latest_path.is_file():
        try:
            loaded = json.loads(latest_path.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                payload = loaded
        except json.JSONDecodeError:
            payload = {}
    return {
        "exists": latest_path.is_file(),
        "latest_path": _rel(root, latest_path),
        "package_id": payload.get("package_id"),
        "drop_in_ready": bool(payload.get("drop_in_ready")),
        "drop_in_path": payload.get("drop_in_path"),
        "zip_path": payload.get("zip_path"),
        "zip_sha256": payload.get("zip_sha256"),
    }


def _agent_record(
    root: Path,
    agent: Mapping[str, Any],
    mount: Mapping[str, Any],
    communication_profile: Mapping[str, Any],
) -> dict[str, Any]:
    return _projection_agent_record(
        agent,
        mount,
        communication_profile,
        portable_package=_latest_package(root, mount),
    )


def _communication_profiles(roster: Mapping[str, Any] | None) -> dict[str, Mapping[str, Any]]:
    directory = _as_mapping(_as_mapping(roster or {}).get("communication_directory"))
    by_role = _as_mapping(directory.get("agents_by_role"))
    if by_role:
        return {str(role): _as_mapping(profile) for role, profile in by_role.items()}
    profiles: dict[str, Mapping[str, Any]] = {}
    for row in directory.get("agents") or []:
        if isinstance(row, Mapping):
            role_id = str(row.get("role_id") or "").strip()
            if role_id:
                profiles[role_id] = row
    return profiles


def _edge(edge_type: str, source: str, target: str, **extra: Any) -> dict[str, Any]:
    return {
        "edge_id": f"{edge_type}:{source}->{target}",
        "edge_type": edge_type,
        "from": source,
        "to": target,
        **extra,
    }


def _display_from_domain_id(domain_id: str) -> str:
    clean = domain_id.removeprefix("ion_").removeprefix("domain.").replace("_", " ").replace(".", " ")
    return " ".join(part[:1].upper() + part[1:] for part in clean.split() if part)


def _proposed_active_domain_id(candidate_domain_id: str) -> str:
    if candidate_domain_id.startswith("ion_vnext_"):
        return f"domain.{candidate_domain_id.removeprefix('ion_')}"
    if candidate_domain_id.startswith("domain."):
        return candidate_domain_id
    return f"domain.{candidate_domain_id.replace('ion_', '')}"


def _promotion_review_for_domain(domain: Mapping[str, Any]) -> dict[str, Any]:
    domain_id = str(domain.get("domain_id") or "")
    coverage_roles = [row for row in domain.get("candidate_coverage_roles") or [] if isinstance(row, Mapping)]
    blockers: list[str] = []
    if not coverage_roles:
        blockers.append("candidate_coverage_missing")
    if not domain.get("source_registry"):
        blockers.append("candidate_source_registry_missing")
    if not domain.get("paths"):
        blockers.append("candidate_paths_missing")
    if not domain.get("read_first"):
        blockers.append("candidate_read_first_missing")
    proposed_domain_id = _proposed_active_domain_id(domain_id)
    return {
        "candidate_domain_id": domain_id,
        "proposed_active_domain_id": proposed_domain_id,
        "proposed_active_registry_target": f"ION/03_registry/domains/{proposed_domain_id}.domain.yaml",
        "candidate_draft_path": (DOMAIN_WEAVER_PROMOTION_DRAFT_DIR / f"{proposed_domain_id}.domain.candidate.yaml").as_posix(),
        "display_name": _display_from_domain_id(proposed_domain_id),
        "decision_class": "draft_registry_record_candidate" if not blockers else "hold_for_evidence",
        "ready_for_registry_draft": not blockers,
        "active_registry_write_performed": False,
        "accepted_ion_state": False,
        "blockers": blockers,
        "purpose": domain.get("purpose") or f"Candidate vNext domain surface for {domain_id}.",
        "paths": list(domain.get("paths") or []),
        "read_first": list(domain.get("read_first") or []),
        "source_registry": domain.get("source_registry"),
        "coverage_roles": [
            {
                "role_id": row.get("role_id"),
                "display_name": row.get("display_name"),
                "coverage_class": row.get("coverage_class"),
                "mount_id": row.get("mount_id"),
                "mount_domain": row.get("mount_domain"),
                "capsule_ready": bool(row.get("capsule_ready")),
                "comms_ready": bool(row.get("comms_ready")),
            }
            for row in coverage_roles
        ],
        "required_promotion_steps": [
            "Review candidate purpose and currentness against active vNext files.",
            "Choose whether to promote, merge into an existing active domain, or keep candidate-only.",
            "If promoted, create the active registry record through an explicit bounded packet.",
            "Bind primary and secondary roles only after the active registry decision is accepted.",
        ],
        "non_claims": [
            "This is not an accepted active domain registry record.",
            "This does not write ION/03_registry/domains.",
            "This does not grant production, live execution, accepted-state, or secrets authority.",
        ],
    }


def build_domain_weaver_promotion_review(
    root: str | Path | None = None,
    projection: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    shell_root = _resolve_root(root)
    source_projection = dict(projection or {})
    if not source_projection:
        projection_path = shell_root / DOMAIN_WEAVER_PROJECTION_PATH
        if projection_path.is_file():
            try:
                loaded = json.loads(projection_path.read_text(encoding="utf-8"))
                if isinstance(loaded, dict):
                    source_projection = loaded
            except json.JSONDecodeError:
                source_projection = {}
    candidate_domains = [
        domain
        for domain in source_projection.get("domains") or []
        if isinstance(domain, Mapping) and domain.get("candidate_domain")
    ]
    decisions = [_promotion_review_for_domain(domain) for domain in candidate_domains]
    ready_count = sum(1 for decision in decisions if decision.get("ready_for_registry_draft"))
    projection_path = shell_root / str(source_projection.get("projection_path") or DOMAIN_WEAVER_PROJECTION_PATH.as_posix())
    projection_sha256 = _sha256_file(projection_path) if projection_path.is_file() else ""
    return {
        "schema_id": PROMOTION_REVIEW_SCHEMA_ID,
        "generated_at": _now(),
        "review_path": DOMAIN_WEAVER_PROMOTION_REVIEW_PATH.as_posix(),
        "review_markdown_path": DOMAIN_WEAVER_PROMOTION_REVIEW_MD_PATH.as_posix(),
        "draft_dir": DOMAIN_WEAVER_PROMOTION_DRAFT_DIR.as_posix(),
        "source_projection_path": str(source_projection.get("projection_path") or DOMAIN_WEAVER_PROJECTION_PATH.as_posix()),
        "source_projection_sha256": projection_sha256,
        "promotion_status": "promotion_review_ready" if decisions and ready_count == len(decisions) else "promotion_review_needs_evidence",
        "summary": {
            "candidate_domain_count": len(decisions),
            "ready_for_registry_draft_count": ready_count,
            "hold_for_evidence_count": len(decisions) - ready_count,
            "active_registry_write_count": 0,
            "accepted_state_count": 0,
        },
        "decisions": decisions,
        "policy": "Promotion review produces draftable candidate records only. It does not mutate active registry files or claim accepted ION state.",
        "authority": {
            "candidate_review_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }


def _load_promotion_review(root: Path) -> dict[str, Any]:
    review_path = root / DOMAIN_WEAVER_PROMOTION_REVIEW_PATH
    if review_path.is_file():
        try:
            loaded = json.loads(review_path.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                return loaded
        except json.JSONDecodeError:
            return {}
    return {}


def _promotion_gate_for_decision(root: Path, decision: Mapping[str, Any]) -> dict[str, Any]:
    candidate_domain_id = str(decision.get("candidate_domain_id") or "")
    proposed_active_domain_id = str(decision.get("proposed_active_domain_id") or "")
    active_target = str(decision.get("proposed_active_registry_target") or "")
    draft_path = str(decision.get("candidate_draft_path") or "")
    active_target_path = root / active_target
    draft_abs = root / draft_path
    checks = [
        {
            "check_id": "decision_ready_for_registry_draft",
            "ok": bool(decision.get("ready_for_registry_draft")),
            "evidence": decision.get("decision_class"),
        },
        {
            "check_id": "candidate_draft_exists",
            "ok": draft_abs.is_file(),
            "evidence": draft_path,
        },
        {
            "check_id": "candidate_draft_outside_active_registry",
            "ok": draft_path.startswith(DOMAIN_WEAVER_PROMOTION_DRAFT_DIR.as_posix()),
            "evidence": draft_path,
        },
        {
            "check_id": "active_registry_target_declared",
            "ok": active_target.startswith("ION/03_registry/domains/") and active_target.endswith(".domain.yaml"),
            "evidence": active_target,
        },
        {
            "check_id": "active_registry_target_not_existing",
            "ok": not active_target_path.exists(),
            "evidence": active_target,
        },
        {
            "check_id": "coverage_roles_declared",
            "ok": bool([row for row in decision.get("coverage_roles") or [] if isinstance(row, Mapping)]),
            "evidence": len([row for row in decision.get("coverage_roles") or [] if isinstance(row, Mapping)]),
        },
        {
            "check_id": "no_active_registry_write_claim",
            "ok": decision.get("active_registry_write_performed") is False,
            "evidence": decision.get("active_registry_write_performed"),
        },
        {
            "check_id": "no_accepted_state_claim",
            "ok": decision.get("accepted_ion_state") is False,
            "evidence": decision.get("accepted_ion_state"),
        },
    ]
    review_blockers = [str(item) for item in decision.get("blockers") or [] if str(item)]
    blockers = [*review_blockers]
    blockers.extend(str(check.get("check_id")) for check in checks if not check.get("ok"))
    if review_blockers:
        gate_state = "blocked"
    elif "candidate_draft_exists" in blockers:
        gate_state = "needs_materialization"
    elif blockers:
        gate_state = "blocked"
    else:
        gate_state = "ready_for_operator_review"
    return {
        "candidate_domain_id": candidate_domain_id,
        "proposed_active_domain_id": proposed_active_domain_id,
        "proposed_active_registry_target": active_target,
        "candidate_draft_path": draft_path,
        "gate_state": gate_state,
        "clean": gate_state == "ready_for_operator_review",
        "target_exists": active_target_path.exists(),
        "candidate_draft_exists": draft_abs.is_file(),
        "checks": checks,
        "blockers": blockers,
        "required_next_action": (
            "review_candidate_draft"
            if gate_state == "ready_for_operator_review"
            else "materialize_promotion_review"
            if gate_state == "needs_materialization"
            else "resolve_gate_blockers"
        ),
        "active_registry_write_performed": False,
        "accepted_ion_state": False,
        "production_authority": False,
        "live_execution_authority": False,
        "secrets_authority": False,
    }


