def _select_dogfood_next_packet(projection: Mapping[str, Any]) -> dict[str, Any]:
    operating_loop = _as_mapping(projection.get("operating_loop"))
    blockers = [row for row in operating_loop.get("blockers") or [] if isinstance(row, Mapping)]
    packets = [row for row in operating_loop.get("next_packets") or [] if isinstance(row, Mapping)]
    selected: Mapping[str, Any] = {}
    if blockers:
        selected = next((row for row in packets if "BLOCKER" in str(row.get("packet_id") or "")), {})
    if not selected:
        selected = next(
            (
                row
                for row in packets
                if str(row.get("packet_id") or "") != "PCKT-DOMAIN-WEAVE-DOGFOOD-LOOP-MVP-20260530"
            ),
            {},
        )
    if not selected:
        selected = {
            "packet_id": "PCKT-DOMAIN-WEAVE-STEWARD-READY-REVIEW-20260531",
            "lane_id": "settlement_lane",
            "work_class": "settlement",
            "objective": "Review the Domain Weaver dogfood capsule and ready projection receipts, then decide whether another bounded packet is needed.",
        }
    lane_id = str(selected.get("lane_id") or "maintenance_lane")
    selected_context_refs = _clean_list(selected.get("context_refs"))
    packet = {
        "schema_id": DOGFOOD_NEXT_PACKET_SCHEMA_ID,
        "packet_id": str(selected.get("packet_id") or "PCKT-DOMAIN-WEAVE-FOLLOWUP-20260531"),
        "lane_id": lane_id,
        "work_class": str(selected.get("work_class") or "maintenance"),
        "objective": str(selected.get("objective") or "Continue the bounded Domain Weaver operating loop from the dogfood capsule."),
        "recommended_worker": str(selected.get("recommended_worker") or _recommended_worker_for_lane(lane_id)),
        "selection_reason": (
            "Selected from the current Domain Weaver operating loop after the context capsule read "
            "projection, promotion, comms, queue, lane, and receipt surfaces."
        ),
        "context_refs": _clean_list(
            [
                DOMAIN_WEAVER_DOGFOOD_CONTEXT_CAPSULE_PATH.as_posix(),
                DOMAIN_WEAVER_PROJECTION_PATH.as_posix(),
                DOMAIN_WEAVER_PROMOTION_GATE_PATH.as_posix(),
                CODEX_WORK_QUEUE_PATH.as_posix(),
                CODEX_WORK_LANE_INDEX_PATH.as_posix(),
                *selected_context_refs,
            ]
        ),
        "return_contract": {
            "template_id": "ion.template.autonomous_loop.local_worker.v1",
            "required_sections": [
                "### CONTEXT PROOF",
                "### TEMPLATE ACTION PROOF",
                "### VALIDATION",
                "### RESULT",
                "### WORKLOAD DIFF",
                "### BLOCKERS",
                "### RECOMMENDED NEXT PACKET",
            ],
        },
        "validation_expectations": [
            "Read the dogfood capsule and referenced projection receipts.",
            "Preserve production/live/accepted-state/secrets authority as false.",
            "Emit at most one follow-up packet unless a proof blocker requires settlement.",
        ],
        "authority": {
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    for key in (
        "recommended_route",
        "target_surfaces",
        "known_good_surface_refs",
        "acceptance_gates",
        "authority",
    ):
        value = selected.get(key)
        if value:
            packet[key] = value
    return packet


def _domain_weaver_cockpit_panel_ready(root: Path | None) -> bool:
    if root is None:
        return False
    path = root / DOMAIN_WEAVER_COCKPIT_PANEL_PATH
    if not path.is_file():
        return False
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return False
    required_tokens = (
        "function DomainWeaverOpsView",
        "Domain Weaver operating loop",
        "QUEUE GOVERNANCE",
        "SELF-DOGFOOD STEPS",
        "NEXT BOUNDED PACKETS",
        "PROMOTION / RECEIPT PROOF",
    )
    return all(token in text for token in required_tokens)


def _source_readiness(root: Path, path: Path, required_tokens: tuple[str, ...]) -> dict[str, Any]:
    abs_path = root / path
    exists = abs_path.is_file()
    content = ""
    if exists:
        try:
            content = abs_path.read_text(encoding="utf-8")
        except OSError:
            content = ""
    def requirement_met(token: str) -> bool:
        alternatives = [part.strip() for part in token.split("||") if part.strip()]
        return any(part in content for part in alternatives)

    missing_tokens = [token for token in required_tokens if not requirement_met(token)]
    return {
        "path": path.as_posix(),
        "exists": exists,
        "required_token_count": len(required_tokens),
        "matched_token_count": len(required_tokens) - len(missing_tokens),
        "missing_tokens": missing_tokens,
        "ready": exists and not missing_tokens,
    }


def _domain_weaver_dist_bundle_mentions(root: Path) -> bool:
    dist_dir = root / DOMAIN_WEAVER_COCKPIT_DIST_DIR
    if not dist_dir.is_dir():
        return False
    candidates = [dist_dir / "index.html"]
    assets_dir = dist_dir / "assets"
    if assets_dir.is_dir():
        candidates.extend(
            path
            for path in assets_dir.iterdir()
            if path.suffix.lower() in {".js", ".css", ".html"}
        )
    for path in candidates:
        if not path.is_file():
            continue
        try:
            content = path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue
        if "DOMAIN WEAVER WORKBENCH" in content or "Domain Weaver cockpit workbench" in content:
            return True
    return False


def _domain_weaver_ui_native_capability(root: Path) -> dict[str, Any]:
    context_refs = [
        _file_ref(root, rel_path, reason)
        for rel_path, reason in UI_FRONTEND_EXCELLENCE_CONTEXT_REFS
    ]
    specialist_route: list[dict[str, Any]] = []
    for ordinal, route_row in enumerate(UI_FRONTEND_EXCELLENCE_AGENT_ROUTE, start=1):
        boot_path = str(route_row.get("boot_path") or "")
        boot_exists = bool(boot_path and (root / boot_path).is_file())
        delegated_role = str(route_row.get("delegated_active_role") or "")
        if boot_exists:
            status = "candidate_boot_ready"
        elif delegated_role:
            status = "delegated_to_active_role"
        else:
            status = "candidate_boot_missing"
        specialist_route.append(
            {
                "ordinal": ordinal,
                "agent_id": route_row.get("agent_id"),
                "boot_path": boot_path or None,
                "boot_exists": boot_exists,
                "delegated_active_role": delegated_role or None,
                "status": status,
            }
        )
    context_ref_ready_count = sum(1 for ref in context_refs if ref.get("exists"))
    specialist_ready_count = sum(
        1
        for row in specialist_route
        if row.get("boot_exists") or row.get("delegated_active_role")
    )
    route_ready = context_ref_ready_count == len(context_refs) and specialist_ready_count == len(specialist_route)
    return {
        "schema_id": "ion.domain_weaver.native_ui_development_capability.v0_1",
        "status": "native_ui_development_route_ready" if route_ready else "native_ui_development_route_incomplete",
        "domain_id": UI_FRONTEND_EXCELLENCE_DOMAIN_ID,
        "skill_id": UI_FRONTEND_EXCELLENCE_SKILL_ID,
        "template_id": UI_FRONTEND_EXCELLENCE_TEMPLATE_ID,
        "specialist_route": specialist_route,
        "context_refs": context_refs,
        "summary": {
            "context_ref_ready_count": context_ref_ready_count,
            "context_ref_required_count": len(context_refs),
            "specialist_ready_count": specialist_ready_count,
            "specialist_required_count": len(specialist_route),
            "route_ready": route_ready,
        },
        "source_priority": [
            "current active ION protocol/state/receipt",
            "active cockpit source and running UI",
            "JOC maintained-work-surface and cockpit protocols",
            "UI Frontend Excellence candidate domain and template gate",
            "known good cockpit workbench pages before generic frontend taste",
        ],
    }


def _domain_weaver_ui_operator_feedback(root: Path) -> dict[str, Any]:
    feedback = _read_json_file(root / DOMAIN_WEAVER_UI_OPERATOR_FEEDBACK_PATH)
    if not feedback:
        return {
            "schema_id": "ion.domain_weaver.ui_operator_feedback_projection.v0_1",
            "status": "no_current_operator_ui_feedback",
            "feedback_path": DOMAIN_WEAVER_UI_OPERATOR_FEEDBACK_PATH.as_posix(),
            "operator_rejected_current_ui": False,
            "operator_accepted_current_ui": False,
            "semantic_operator_proof_ready": False,
            "summary": {
                "feedback_exists": False,
                "operator_rejected_current_ui": False,
                "operator_accepted_current_ui": False,
                "semantic_operator_proof_ready": False,
            },
        }
    operator_rejected = bool(feedback.get("operator_rejected_current_ui"))
    operator_accepted = bool(feedback.get("operator_accepted_current_ui")) and not operator_rejected
    operator_rejection_blocks_domain_weaver_evolution = bool(
        feedback.get("operator_rejection_blocks_domain_weaver_evolution", operator_rejected)
    )
    return {
        "schema_id": "ion.domain_weaver.ui_operator_feedback_projection.v0_1",
        "status": (
            "operator_rejected_current_ui"
            if operator_rejected and operator_rejection_blocks_domain_weaver_evolution
            else "operator_rejected_current_ui_evolution_unblocked"
            if operator_rejected
            else "operator_accepted_current_ui"
            if operator_accepted
            else "operator_feedback_present_unsettled"
        ),
        "feedback_path": DOMAIN_WEAVER_UI_OPERATOR_FEEDBACK_PATH.as_posix(),
        "operator_rejected_current_ui": operator_rejected,
        "operator_accepted_current_ui": operator_accepted,
        "operator_rejection_blocks_domain_weaver_evolution": operator_rejection_blocks_domain_weaver_evolution,
        "semantic_operator_proof_ready": operator_accepted,
        "feedback": feedback,
        "summary": {
            "feedback_exists": True,
            "operator_rejected_current_ui": operator_rejected,
            "operator_accepted_current_ui": operator_accepted,
            "operator_rejection_blocks_domain_weaver_evolution": operator_rejection_blocks_domain_weaver_evolution,
            "semantic_operator_proof_ready": operator_accepted,
            "feedback_status": str(feedback.get("status") or "present"),
        },
    }


def _domain_weaver_ui_surface_quality(root: Path) -> dict[str, Any]:
    page_path = root / DOMAIN_WEAVER_COCKPIT_PAGE_PATH
    page_text = ""
    if page_path.is_file():
        try:
            page_text = page_path.read_text(encoding="utf-8")
        except OSError:
            page_text = ""
    present_zone_tokens = [token for token in DOMAIN_WEAVER_UI_SHELL_ZONE_TOKENS if token in page_text]
    known_good_surfaces: list[dict[str, Any]] = []
    for surface_id, path, reason in DOMAIN_WEAVER_UI_KNOWN_GOOD_SURFACES:
        exists = (root / path).is_file()
        known_good_surfaces.append(
            {
                "surface_id": surface_id,
                "path": path.as_posix(),
                "exists": exists,
                "reason": reason,
            }
        )
    smoke_path = root / DOMAIN_WEAVER_ACTION_HISTORY_VISUAL_SMOKE_RECEIPT_PATH
    smoke = _read_json_file(smoke_path)
    try:
        visual_smoke_mtime = smoke_path.stat().st_mtime
    except OSError:
        visual_smoke_mtime = 0.0
    visual_source_mtime = max(
        _path_mtime_epoch_seconds(root, DOMAIN_WEAVER_COCKPIT_PAGE_PATH),
        _path_mtime_epoch_seconds(root, DOMAIN_WEAVER_COCKPIT_SHELL_PATH),
        _path_mtime_epoch_seconds(root, DOMAIN_WEAVER_COCKPIT_RUNTIME_CSS_PATH),
        _path_mtime_epoch_seconds(root, DOMAIN_WEAVER_COCKPIT_DIST_DIR / "index.html"),
    )
    visual_smoke_fresh = bool(visual_smoke_mtime) and (
        visual_source_mtime <= 0 or visual_smoke_mtime >= visual_source_mtime
    )
    visual_smoke_ok = bool(smoke.get("ok")) and visual_smoke_fresh
    operator_feedback = _domain_weaver_ui_operator_feedback(root)
    feedback_summary = _as_mapping(operator_feedback.get("summary"))
    operator_rejected = bool(feedback_summary.get("operator_rejected_current_ui"))
    operator_rejection_blocks_domain_weaver_evolution = bool(
        feedback_summary.get("operator_rejection_blocks_domain_weaver_evolution", operator_rejected)
    )
    semantic_operator_proof_ready = bool(feedback_summary.get("semantic_operator_proof_ready"))
    architecture_ready = len(present_zone_tokens) >= 5
    operator_work_surface_ready = architecture_ready and visual_smoke_ok and semantic_operator_proof_ready and not operator_rejected
    return {
        "schema_id": "ion.domain_weaver.ui_surface_quality_projection.v0_1",
        "status": (
            "operator_rejected_current_ui"
            if operator_rejected and operator_rejection_blocks_domain_weaver_evolution
            else "operator_rejected_current_ui_evolution_unblocked"
            if operator_rejected
            else "operator_work_surface_ready"
            if operator_work_surface_ready
            else "operator_work_surface_needs_evolution"
        ),
        "known_good_surfaces": known_good_surfaces,
        "summary": {
            "known_good_surface_count": len(known_good_surfaces),
            "known_good_surface_available_count": sum(1 for row in known_good_surfaces if row.get("exists")),
            "shell_zone_token_count": len(present_zone_tokens),
            "shell_zone_required_count": 5,
            "shell_zone_tokens_present": present_zone_tokens,
            "work_surface_architecture_ready": architecture_ready,
            "visual_smoke_ok": visual_smoke_ok,
            "visual_smoke_raw_ok": bool(smoke.get("ok")),
            "visual_smoke_fresh": visual_smoke_fresh,
            "visual_smoke_mtime_epoch_seconds": visual_smoke_mtime,
            "visual_source_mtime_epoch_seconds": visual_source_mtime,
            "visual_smoke_receipt_path": DOMAIN_WEAVER_ACTION_HISTORY_VISUAL_SMOKE_RECEIPT_PATH.as_posix(),
            "semantic_operator_proof_ready": semantic_operator_proof_ready,
            "operator_rejected_current_ui": operator_rejected,
            "operator_rejection_blocks_domain_weaver_evolution": operator_rejection_blocks_domain_weaver_evolution,
            "operator_feedback_status": operator_feedback.get("status"),
            "operator_feedback_path": DOMAIN_WEAVER_UI_OPERATOR_FEEDBACK_PATH.as_posix(),
            "operator_work_surface_ready": operator_work_surface_ready,
        },
        "operator_feedback": operator_feedback,
        "operator_usability_rule": (
            "Route/build/screenshot presence is not enough. Domain Weaver UI is operator-usable only after it maps "
            "the page into explicit work-surface zones, has visual proof, and has no current operator rejection."
        ),
    }


def _domain_weaver_request_carrier_intake_status(root: Path, request: Mapping[str, Any]) -> dict[str, Any]:
    return_paths = [
        str(path)
        for path in [
            *[item for item in request.get("return_packet_paths") or [] if str(item)],
            request.get("latest_return_packet_path"),
        ]
        if str(path or "").strip()
    ]
    unique_return_paths = _unique_paths(return_paths)
    latest_return_path = unique_return_paths[-1] if unique_return_paths else ""
    latest_return = _read_json_file(root / latest_return_path) if latest_return_path else {}
    accepted = bool(
        request.get("status") == "RETURN_RECORDED_PROOF_ACCEPTED"
        or latest_return.get("accepted_for_carrier_intake") is True
    )
    return {
        "accepted_for_carrier_intake": accepted,
        "latest_return_packet_path": latest_return_path,
        "return_packet_count": len(unique_return_paths),
        "request_status": request.get("status") or "",
    }


def _domain_weaver_request_context_read_paths(request: Mapping[str, Any]) -> list[str]:
    paths: list[str] = []
    for item in request.get("required_context_reads") or []:
        if isinstance(item, Mapping):
            path = str(item.get("path") or "").strip()
        else:
            path = str(item or "").strip()
        if path:
            paths.append(path)
    return _clean_list(paths)


def _domain_weaver_run_packets_for_request(root: Path, *, request_id: str, request_path: str) -> list[dict[str, Any]]:
    run_root = root / CODEX_QUEUE_RUNS_DIR
    if not run_root.is_dir():
        return []
    rows: list[dict[str, Any]] = []
    for run_path in run_root.glob("*/run.json"):
        run = _read_json_file(run_path)
        if not run:
            continue
        if str(run.get("request_id") or "") != request_id and str(run.get("request_path") or "") != request_path:
            continue
        rows.append({"path": _rel(root, run_path), "mtime": run_path.stat().st_mtime, "run": run})
    rows.sort(key=lambda row: float(row.get("mtime") or 0.0), reverse=True)
    return rows


def _domain_weaver_worker_awareness_context_contract(
    root: Path,
    *,
    request_id: str,
    request_path: str,
) -> dict[str, Any]:
    required_ui_canon = set(_domain_weaver_ui_canon_context_reads(root, existing_only=True))
    run_rows = _domain_weaver_run_packets_for_request(root, request_id=request_id, request_path=request_path)
    observed: list[dict[str, Any]] = []
    for row in run_rows:
        run = _as_mapping(row.get("run"))
        awareness_path = str(run.get("worker_context_awareness_receipt_path") or "").strip()
        awareness = _read_json_file(root / awareness_path) if awareness_path else {}
        if not awareness:
            observed.append(
                {
                    "run_packet_path": row.get("path"),
                    "worker_context_awareness_receipt_path": awareness_path,
                    "status": "missing",
                    "ui_canon_missing_count": len(required_ui_canon),
                    "selected_model": None,
                    "selected_reasoning_effort": None,
                    "ready": False,
                }
            )
            continue
        reads = {
            str(item.get("path") or "").strip()
            for item in awareness.get("required_context_reads") or []
            if isinstance(item, Mapping) and str(item.get("path") or "").strip()
        }
        missing = sorted(required_ui_canon - reads)
        selected_model = str(awareness.get("selected_model") or "").strip()
        selected_effort = str(awareness.get("selected_reasoning_effort") or "").strip()
        awareness_status = str(awareness.get("status") or "").strip()
        missing_required = _clean_list(awareness.get("missing_required_context_paths"))
        ready = bool(
            awareness_status == "WORKER_CONTEXT_ACKNOWLEDGED"
            and selected_model == "gpt-5.5"
            and selected_effort == "xhigh"
            and not missing_required
            and not missing
        )
        observed.append(
            {
                "run_packet_path": row.get("path"),
                "worker_context_awareness_receipt_path": awareness_path,
                "status": awareness_status,
                "selected_model": selected_model,
                "selected_reasoning_effort": selected_effort,
                "missing_required_context_paths": missing_required,
                "ui_canon_missing_count": len(missing),
                "ui_canon_missing_paths": missing[:8],
                "ready": ready,
            }
        )
        if ready:
            return {**observed[-1], "observed_run_count": len(run_rows)}
    if observed:
        return {**observed[0], "observed_run_count": len(run_rows)}
    return {
        "run_packet_path": "",
        "worker_context_awareness_receipt_path": "",
        "status": "missing",
        "selected_model": None,
        "selected_reasoning_effort": None,
        "missing_required_context_paths": [],
        "ui_canon_missing_count": len(required_ui_canon),
        "ui_canon_missing_paths": sorted(required_ui_canon)[:8],
        "observed_run_count": 0,
        "ready": False,
    }


def _domain_weaver_ui_canon_context_contract_for_request(
    root: Path,
    *,
    request_path: str,
    request: Mapping[str, Any],
) -> dict[str, Any]:
    required_ui_canon = set(_domain_weaver_ui_canon_context_reads(root, existing_only=True))
    request_reads = set(_domain_weaver_request_context_read_paths(request))
    request_missing = sorted(required_ui_canon - request_reads)
    request_id = str(request.get("request_id") or "").strip()
    awareness = _domain_weaver_worker_awareness_context_contract(
        root,
        request_id=request_id,
        request_path=request_path,
    )
    request_model_ready = str(request.get("requested_model") or "").strip() == "gpt-5.5"
    request_effort_ready = str(request.get("requested_reasoning_effort") or "").strip() == "xhigh"
    override = request.get("codex_model_override") if isinstance(request.get("codex_model_override"), Mapping) else {}
    override_ready = bool(
        str(override.get("selected_model") or "").strip() == "gpt-5.5"
        and str(override.get("selected_reasoning_effort") or "").strip() == "xhigh"
    )
    ready = bool(
        required_ui_canon
        and not request_missing
        and request_model_ready
        and request_effort_ready
        and override_ready
        and awareness.get("ready")
    )
    missing_reasons: list[str] = []
    if request_missing:
        missing_reasons.append("request_missing_current_ui_canon_context")
    if not request_model_ready or not request_effort_ready or not override_ready:
        missing_reasons.append("request_missing_gpt_5_5_xhigh_override")
    if not awareness.get("ready"):
        missing_reasons.append("worker_context_awareness_missing_or_stale")
    return {
        "schema_id": "ion.domain_weaver.ui_canon_context_contract.v0_1_candidate",
        "ready": ready,
        "required_ui_canon_path_count": len(required_ui_canon),
        "request_required_context_read_count": len(request_reads),
        "request_missing_ui_canon_count": len(request_missing),
        "request_missing_ui_canon_paths": request_missing[:8],
        "request_model_ready": request_model_ready,
        "request_reasoning_effort_ready": request_effort_ready,
        "request_model_override_ready": override_ready,
        "worker_context_awareness": awareness,
        "missing_reasons": missing_reasons,
    }


def _domain_weaver_ui_declared_route_execution_gate(root: Path, native_capability: Mapping[str, Any]) -> dict[str, Any]:
    specialist_route = [row for row in native_capability.get("specialist_route") or [] if isinstance(row, Mapping)]
    declared_route = [str(row.get("agent_id") or "").strip() for row in specialist_route if str(row.get("agent_id") or "").strip()]
    route_set = set(declared_route)
    native_summary = _as_mapping(native_capability.get("summary"))
    native_queue_ledger = _read_json_file(root / DOMAIN_WEAVER_NATIVE_UI_DEVELOPMENT_QUEUE_LEDGER_PATH)
    specialist_queue_ledger = _read_json_file(root / DOMAIN_WEAVER_UI_SPECIALIST_ROUTE_FANOUT_QUEUE_LEDGER_PATH)
    native_queued_rows = [
        {**dict(row), "source_queue": "native_ui_development"}
        for row in native_queue_ledger.get("queued_requests") or []
        if isinstance(row, Mapping)
    ]
    if not native_queued_rows:
        native_queued_rows = [
            {
                "request_id": path.stem,
                "packet_path": _rel(root, path),
                "worker_started": False,
                "source_queue": "native_ui_development",
            }
            for path in sorted(
                (root / CODEX_WORK_REQUESTS_DIR).glob(
                    "codex_req_domain_weaver_native_ui_development_worksurface_20260531_attempt_*.json"
                )
            )
        ]
    specialist_queued_rows = [
        {**dict(row), "source_queue": "ui_specialist_route_fanout"}
        for row in specialist_queue_ledger.get("queued_requests") or []
        if isinstance(row, Mapping)
    ]
    queued_rows = [*native_queued_rows, *specialist_queued_rows]

    observed_requests: list[dict[str, Any]] = []
    accepted_roles: dict[str, list[dict[str, Any]]] = {}
    for queued in queued_rows:
        request_path = str(queued.get("packet_path") or "").strip()
        request = _read_json_file(root / request_path) if request_path else {}
        if not request:
            observed_requests.append(
                {
                    "request_id": queued.get("request_id"),
                    "request_path": request_path,
                    "source_queue": queued.get("source_queue") or "",
                    "request_status": "missing",
                    "worker_started": bool(queued.get("worker_started")),
                    "accepted_for_carrier_intake": False,
                    "agent_role": "",
                    "recommended_route_count": 0,
                    "latest_return_packet_path": "",
                }
            )
            continue
        carrier = _domain_weaver_request_carrier_intake_status(root, request)
        agent_role = str(request.get("agent_role") or "").strip()
        ui_payload = _as_mapping(request.get("domain_weaver_ui_development"))
        recommended_route = _clean_list(ui_payload.get("recommended_route"))
        if not recommended_route:
            recommended_route = _clean_list(_as_mapping(request.get("next_packet")).get("recommended_route"))
        row = {
            "request_id": request.get("request_id") or queued.get("request_id"),
            "request_path": request_path,
            "source_queue": queued.get("source_queue") or "",
            "request_status": carrier.get("request_status") or "missing",
            "request_kind": request.get("request_kind") or "",
            "agent_role": agent_role,
            "worker_started": bool(queued.get("worker_started")),
            "accepted_for_carrier_intake": bool(carrier.get("accepted_for_carrier_intake")),
            "latest_return_packet_path": carrier.get("latest_return_packet_path") or "",
            "return_packet_count": carrier.get("return_packet_count", 0),
            "recommended_route_count": len(recommended_route),
            "recommended_route": recommended_route,
        }
        context_contract = _domain_weaver_ui_canon_context_contract_for_request(
            root,
            request_path=request_path,
            request=request,
        )
        row["ui_canon_context_contract"] = context_contract
        row["ui_canon_context_ready"] = bool(context_contract.get("ready"))
        observed_requests.append(row)
        if row["accepted_for_carrier_intake"] and agent_role in route_set and row["ui_canon_context_ready"]:
            accepted_roles.setdefault(agent_role, []).append(row)

    activation_ledger = _read_json_file(root / DOMAIN_WEAVER_ACTIVATION_LEDGER_PATH)
    activation_decisions = {
        str(row.get("request_id") or ""): row
        for row in activation_ledger.get("decision_records") or []
        if isinstance(row, Mapping)
    }
    proof_rows: list[dict[str, Any]] = []
    for route_row in specialist_route:
        agent_id = str(route_row.get("agent_id") or "").strip()
        request_id = f"act_req_{_safe_id(agent_id)}"
        decision = _as_mapping(activation_decisions.get(request_id))
        independent_returns = accepted_roles.get(agent_id, [])
        stale_context_returns = [
            row
            for row in observed_requests
            if row.get("accepted_for_carrier_intake") and row.get("agent_role") == agent_id and not row.get("ui_canon_context_ready")
        ]
        if independent_returns:
            proof_type = "independent_worker_return"
            proof_ready = True
            proof_ref = independent_returns[-1].get("latest_return_packet_path") or independent_returns[-1].get("request_path")
            context_contract = independent_returns[-1].get("ui_canon_context_contract")
        elif stale_context_returns:
            proof_type = "stale_context_worker_return"
            proof_ready = False
            proof_ref = stale_context_returns[-1].get("latest_return_packet_path") or stale_context_returns[-1].get("request_path")
            context_contract = stale_context_returns[-1].get("ui_canon_context_contract")
        elif decision.get("decision") == "route_to_existing_agent" and decision.get("selected_agent"):
            proof_type = "governed_delegation_decision"
            proof_ready = True
            proof_ref = str(decision.get("settlement_target") or DOMAIN_WEAVER_ACTIVATION_LEDGER_PATH.as_posix())
            context_contract = None
        elif decision.get("decision") == "blocked":
            proof_type = "blocked_receipt"
            proof_ready = True
            proof_ref = str(decision.get("settlement_target") or DOMAIN_WEAVER_ACTIVATION_LEDGER_PATH.as_posix())
            context_contract = None
        else:
            proof_type = "missing"
            proof_ready = False
            proof_ref = ""
            context_contract = None
        proof_rows.append(
            {
                "agent_id": agent_id,
                "candidate_boot_ready": route_row.get("status") == "candidate_boot_ready",
                "delegated_active_role": route_row.get("delegated_active_role"),
                "proof_type": proof_type,
                "proof_ready": proof_ready,
                "proof_ref": proof_ref,
                "ui_canon_context_ready": bool(_as_mapping(context_contract).get("ready")) if context_contract else None,
                "ui_canon_context_contract": context_contract,
                "candidate_boot_is_execution_proof": False,
            }
        )

    declared_route_count = len(declared_route)
    independent_worker_return_count = sum(1 for row in proof_rows if row.get("proof_type") == "independent_worker_return")
    stale_context_worker_return_count = sum(1 for row in proof_rows if row.get("proof_type") == "stale_context_worker_return")
    ui_canon_context_ready_count = sum(
        1
        for row in proof_rows
        if row.get("proof_type") == "independent_worker_return" and row.get("ui_canon_context_ready") is True
    )
    governed_delegation_count = sum(1 for row in proof_rows if row.get("proof_type") == "governed_delegation_decision")
    blocked_receipt_count = sum(1 for row in proof_rows if row.get("proof_type") == "blocked_receipt")
    proof_complete_count = sum(1 for row in proof_rows if row.get("proof_ready"))
    carrier_intake_accepted_count = sum(1 for row in observed_requests if row.get("accepted_for_carrier_intake"))
    candidate_boot_count = sum(1 for row in proof_rows if row.get("candidate_boot_ready"))
    queue_summary = _as_mapping(native_queue_ledger.get("summary"))
    worker_started_count = int(queue_summary.get("worker_started_count") or 0)
    work_request_template_count = int(queue_summary.get("work_request_template_count") or len(observed_requests))
    max_worker_starts = int(queue_summary.get("max_worker_starts") or 0)
    route_claim_count = sum(
        1
        for row in observed_requests
        if int(row.get("recommended_route_count") or 0) > 1 and row.get("agent_role") in route_set
    )
    single_worker_substitution_blocked = bool(
        declared_route_count > 1
        and route_claim_count > 0
        and not specialist_queued_rows
        and work_request_template_count <= 1
        and (worker_started_count <= 1 or max_worker_starts <= 1)
        and proof_complete_count < declared_route_count
    )
    route_execution_ready = bool(declared_route_count) and proof_complete_count >= declared_route_count and not single_worker_substitution_blocked
    if single_worker_substitution_blocked:
        status = "critical_architecture_breach_single_worker_substitution"
    elif route_execution_ready:
        status = "declared_route_execution_ready"
    elif stale_context_worker_return_count:
        status = "declared_route_execution_context_stale"
    elif declared_route_count:
        status = "declared_route_execution_proof_missing"
    else:
        status = "declared_route_execution_not_applicable"
    return {
        "schema_id": "ion.domain_weaver.declared_route_execution_gate.v0_1_candidate",
        "status": status,
        "gate_path": DOMAIN_WEAVER_ROUTE_EXECUTION_GATE_PATH.as_posix(),
        "route_id": "domain_weaver_native_ui_development_declared_route",
        "declared_route": declared_route,
        "proof_rows": proof_rows,
        "observed_requests": observed_requests,
        "queue_ledger_path": DOMAIN_WEAVER_NATIVE_UI_DEVELOPMENT_QUEUE_LEDGER_PATH.as_posix(),
        "specialist_fanout_queue_ledger_path": DOMAIN_WEAVER_UI_SPECIALIST_ROUTE_FANOUT_QUEUE_LEDGER_PATH.as_posix(),
        "activation_ledger_path": DOMAIN_WEAVER_ACTIVATION_LEDGER_PATH.as_posix(),
        "summary": {
            "declared_route_count": declared_route_count,
            "candidate_boot_count": candidate_boot_count,
            "native_route_descriptor_ready": bool(native_summary.get("route_ready")),
            "candidate_boot_counts_as_execution": False,
            "observed_request_count": len(observed_requests),
            "specialist_fanout_observed_request_count": len(specialist_queued_rows),
            "work_request_template_count": work_request_template_count,
            "worker_started_count": worker_started_count,
            "carrier_intake_accepted_count": carrier_intake_accepted_count,
            "independent_worker_return_count": independent_worker_return_count,
            "stale_context_worker_return_count": stale_context_worker_return_count,
            "ui_canon_context_ready_count": ui_canon_context_ready_count,
            "missing_ui_canon_context_count": stale_context_worker_return_count,
            "governed_delegation_count": governed_delegation_count,
            "blocked_receipt_count": blocked_receipt_count,
            "proof_complete_count": proof_complete_count,
            "route_claim_count": route_claim_count,
            "single_worker_substitution_blocked": single_worker_substitution_blocked,
            "route_execution_ready": route_execution_ready,
            "missing_route_proof_count": max(0, declared_route_count - proof_complete_count),
        },
        "settlement_rule": (
            "Candidate boot files, route arrays, role labels, screenshots, build success, and carrier return intake "
            "do not prove a declared Domain Weaver specialist route executed. Each route member needs an independent "
            "worker return, a governed delegation decision, or an explicit blocked receipt."
        ),
        "authority": {
            "candidate_gate_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }


def _domain_weaver_latest_ui_specialist_fanin_retry_gate_refs(root: Path) -> dict[str, Any]:
    prefix = "codex_req_domain_weaver_ui_specialist_fanin_and_retry_gate_20260531_attempt_"
    request_rows: list[tuple[float, Path, dict[str, Any], dict[str, Any]]] = []
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        payload = _read_json_file(path)
        return_path = str(payload.get("latest_return_packet_path") or "").strip()
        latest_return = _read_json_file(root / return_path) if return_path else {}
        if (
            str(payload.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
            and latest_return.get("accepted_for_carrier_intake") is True
        ):
            request_rows.append((path.stat().st_mtime, path, payload, latest_return))
    if not request_rows:
        return {
            "accepted": False,
            "retry_gate_ready": False,
            "finding": "ui_specialist_fanin_retry_gate_not_accepted",
        }
    _mtime, request_path, request, latest_return = sorted(request_rows, key=lambda row: row[0])[-1]
    request_rel = _rel(root, request_path)
    return_path = str(request.get("latest_return_packet_path") or "").strip()
    run_packet_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = (root / task_return_body_path).read_text(encoding="utf-8", errors="replace") if task_return_body_path and (root / task_return_body_path).is_file() else ""
    recommended_packet_id = ""
    match = re.search(r"`(PCKT-DOMAIN-WEAVER-UI-IMPLEMENTATION-RETRY-GATED-[^`\s]+)`", body_text)
    if match:
        recommended_packet_id = match.group(1)
    context_contract = _domain_weaver_ui_canon_context_contract_for_request(
        root,
        request_path=request_rel,
        request=request,
    )
    retry_gate_ready = bool(
        context_contract.get("ready")
        and "READY_FOR_NO_CODE_STEWARD_RETRY_GATE_REVIEW" in body_text
        and recommended_packet_id
    )
    return {
        "accepted": True,
        "retry_gate_ready": retry_gate_ready,
        "finding": "" if retry_gate_ready else "accepted_ui_fanin_retry_gate_missing_ready_verdict_or_context_contract",
        "request_path": request_rel,
        "request_id": request.get("request_id"),
        "return_path": return_path,
        "run_packet_path": run_packet_path,
        "task_return_body_path": task_return_body_path,
        "machine_receipt_path": str(latest_return.get("machine_receipt_path") or ""),
        "recommended_next_packet_id": recommended_packet_id,
        "context_contract": context_contract,
        "context_contract_ready": bool(context_contract.get("ready")),
        "ready_verdict_present": "READY_FOR_NO_CODE_STEWARD_RETRY_GATE_REVIEW" in body_text,
    }


def _domain_weaver_latest_ui_implementation_retry_refs(root: Path) -> dict[str, Any]:
    prefix = "codex_req_domain_weaver_ui_implementation_retry_gated_20260601_attempt_"
    request_rows: list[tuple[float, Path, dict[str, Any], dict[str, Any]]] = []
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        payload = _read_json_file(path)
        return_path = str(payload.get("latest_return_packet_path") or "").strip()
        latest_return = _read_json_file(root / return_path) if return_path else {}
        if (
            str(payload.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
            and latest_return.get("accepted_for_carrier_intake") is True
        ):
            request_rows.append((path.stat().st_mtime, path, payload, latest_return))
    if not request_rows:
        return {
            "accepted": False,
            "visual_review_ready": False,
            "visual_proof_blocked": False,
            "finding": "ui_implementation_retry_not_accepted",
        }
    _mtime, request_path, request, latest_return = sorted(request_rows, key=lambda row: row[0])[-1]
    request_rel = _rel(root, request_path)
    return_path = str(request.get("latest_return_packet_path") or "").strip()
    run_packet_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = (
        (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
        if task_return_body_path and (root / task_return_body_path).is_file()
        else ""
    )
    recommended_packet_id = ""
    match = re.search(
        r"(PCKT-DOMAIN-WEAVER-UI-VISUAL-PROOF-AND-STEWARDSHIP-REVIEW-[A-Z0-9-]+)",
        body_text,
    )
    if match:
        recommended_packet_id = match.group(1)
    visual_receipt_path = ""
    receipt_match = re.search(
        r"(ION/05_context/current/domain_weaver/visual_smoke/[A-Za-z0-9_.\-/]*VISUAL_PROOF_BLOCKED\.json)",
        body_text,
    )
    if receipt_match:
        visual_receipt_path = receipt_match.group(1)
    known_blocked_receipt_path = (
        "ION/05_context/current/domain_weaver/visual_smoke/"
        "DOMAIN_WEAVER_UI_RETRY_20260601_VISUAL_PROOF_BLOCKED.json"
    )
    if not visual_receipt_path and (root / known_blocked_receipt_path).is_file():
        visual_receipt_path = known_blocked_receipt_path
    visual_receipt = _read_json_file(root / visual_receipt_path) if visual_receipt_path else {}
    visual_proof_blocked = bool(
        visual_receipt.get("result") == "blocked"
        or visual_receipt.get("fresh_visual_proof_captured") is False
        or "Fresh visual proof is blocked" in body_text
        or "Fresh desktop/tablet/mobile screenshots were not captured" in body_text
    )
    visual_review_ready = bool(recommended_packet_id)
    return {
        "accepted": True,
        "visual_review_ready": visual_review_ready,
        "visual_proof_blocked": visual_proof_blocked,
        "finding": "" if visual_review_ready else "accepted_ui_implementation_retry_missing_visual_review_next_packet",
        "request_path": request_rel,
        "request_id": request.get("request_id"),
        "return_path": return_path,
        "run_packet_path": run_packet_path,
        "task_return_body_path": task_return_body_path,
        "machine_receipt_path": str(latest_return.get("machine_receipt_path") or ""),
        "recommended_next_packet_id": recommended_packet_id,
        "visual_proof_blocked_receipt_path": visual_receipt_path,
        "fresh_visual_proof_captured": bool(visual_receipt.get("fresh_visual_proof_captured")),
        "operator_rejection_preserved": bool(
            visual_receipt.get("operator_rejection_preserved") is True
            or "Preserved active rejection" in body_text
            or "operator rejection remains valid" in body_text
        ),
    }


def _domain_weaver_latest_live_model_hydration_endpoint_reproof(root: Path) -> dict[str, Any]:
    visual_root = root / DOMAIN_WEAVER_VISUAL_SMOKE_DIR
    rows: list[tuple[float, Path, dict[str, Any]]] = []
    if visual_root.is_dir():
        for path in sorted(visual_root.glob("*/live_model_hydration_endpoint_reproof.json")):
            payload = _read_json_file(path)
            if payload.get("schema_id") == "ion.domain_weaver.live_model_hydration_endpoint_reproof.v1":
                rows.append((path.stat().st_mtime, path, payload))
    if not rows:
        return {
            "schema_id": "ion.domain_weaver.live_model_hydration_endpoint_reproof.latest.v1",
            "reproof_ready": False,
            "model_endpoint_live_hydration_proved": False,
            "fresh_live_browser_screenshot_captured": False,
            "proof_path": "",
            "screenshot_path": "",
            "finding": "live_model_hydration_endpoint_reproof_not_recorded",
        }
    _mtime, proof_path, proof = sorted(rows, key=lambda row: (row[0], row[1].as_posix()))[-1]
    screenshot_path = str(proof.get("final_screenshot_path") or proof.get("screenshot_path") or "")
    screenshot_exists = bool(screenshot_path and (root / screenshot_path).is_file())
    endpoint_proved = bool(
        proof.get("model_endpoint_live_hydration_proved") is True
        and int(proof.get("http_status") or 0) == 200
        and str(proof.get("surface") or "") == "weave"
    )
    reproof_ready = bool(endpoint_proved and proof.get("fresh_live_browser_screenshot_captured") is True and screenshot_exists)
    return {
        "schema_id": "ion.domain_weaver.live_model_hydration_endpoint_reproof.latest.v1",
        "reproof_ready": reproof_ready,
        "model_endpoint_live_hydration_proved": endpoint_proved,
        "fresh_live_browser_screenshot_captured": bool(proof.get("fresh_live_browser_screenshot_captured")),
        "proof_path": _rel(root, proof_path),
        "model_path": str(proof.get("model_path") or ""),
        "screenshot_path": screenshot_path,
        "screenshot_exists": screenshot_exists,
        "response_seconds": proof.get("response_seconds"),
        "response_bytes": proof.get("response_bytes"),
        "operator_rejection_superseded": bool(proof.get("operator_rejection_superseded")),
        "operator_rejection_still_active": bool(proof.get("operator_rejection_still_active")),
        "packet_id": proof.get("packet_id"),
        "finding": "" if reproof_ready else "live_model_hydration_endpoint_reproof_incomplete",
    }


def _domain_weaver_latest_ui_visual_stewardship_review_refs(root: Path) -> dict[str, Any]:
    review_rows: list[tuple[float, Path, dict[str, Any]]] = []
    visual_root = root / "ION/05_context/current/domain_weaver/visual_smoke"
    for path in sorted(visual_root.glob("*STEWARDSHIP_REVIEW*.json")) if visual_root.is_dir() else []:
        payload = _read_json_file(path)
        if payload.get("schema_id") == "ion.domain_weaver.ui_visual_stewardship_review.v1":
            review_rows.append((path.stat().st_mtime, path, payload))
    proof_rows: list[tuple[float, Path, dict[str, Any]]] = []
    if visual_root.is_dir():
        for path in sorted(visual_root.glob("*/visual_proof_attempt.json")):
            payload = _read_json_file(path)
            if payload.get("schema_id") == "ion.domain_weaver.visual_proof_attempt.v1":
                proof_rows.append((path.stat().st_mtime, path, payload))
        local_proof = visual_root / "DOMAIN_WEAVER_UI_VISUAL_PROOF_20260601_LOCAL_PLAYWRIGHT.json"
        if local_proof.is_file():
            payload = _read_json_file(local_proof)
            if payload.get("schema_id") == "ion.domain_weaver.visual_proof.local_playwright.v1":
                proof_rows.append((local_proof.stat().st_mtime, local_proof, payload))
    model_hang_path = visual_root / "DOMAIN_WEAVER_UI_MODEL_ENDPOINT_HANG_20260601_LOCAL.json"
    model_hang = _read_json_file(model_hang_path)
    model_reproof = _domain_weaver_latest_live_model_hydration_endpoint_reproof(root)
    model_endpoint_reproofed = bool(model_reproof.get("model_endpoint_live_hydration_proved"))
    model_endpoint_blocked = bool(model_hang) and not model_endpoint_reproofed
    model_endpoint_receipt_path = (
        str(model_reproof.get("proof_path") or "")
        if model_endpoint_reproofed
        else _rel(root, model_hang_path)
        if model_hang
        else ""
    )
    latest_proof_path = ""
    latest_proof: dict[str, Any] = {}
    if proof_rows:
        _proof_mtime, proof_path, latest_proof = sorted(proof_rows, key=lambda row: row[0])[-1]
        latest_proof_path = _rel(root, proof_path)
    if not review_rows:
        return {
            "review_ready": False,
            "fresh_visual_proof_captured": bool(
                latest_proof.get("fresh_visual_proof_captured") or latest_proof.get("ok")
            ),
            "all_requested_viewports_captured": bool(
                latest_proof.get("all_requested_viewports_captured") or latest_proof.get("ok")
            ),
            "visual_proof_path": latest_proof_path,
            "model_endpoint_blocked": model_endpoint_blocked,
            "model_endpoint_receipt_path": model_endpoint_receipt_path,
            "model_endpoint_live_hydration_proved": model_endpoint_reproofed,
            "model_endpoint_reproof": model_reproof,
            "finding": "ui_visual_stewardship_review_not_recorded",
        }
    _mtime, review_path, review = sorted(review_rows, key=lambda row: row[0])[-1]
    review_ready = bool(review.get("stewardship_verdict"))
    operator_rejection_superseded = bool(review.get("operator_rejection_superseded"))
    domain_quality_settlement_ready = bool(review.get("domain_quality_settlement_ready"))
    return {
        "review_ready": review_ready,
        "finding": "" if review_ready else "ui_visual_stewardship_review_missing_verdict",
        "review_path": _rel(root, review_path),
        "source_visual_proof_path": str(review.get("source_visual_proof_path") or latest_proof_path),
        "visual_proof_path": latest_proof_path,
        "model_endpoint_blocked": model_endpoint_blocked,
        "model_endpoint_receipt_path": model_endpoint_receipt_path,
        "model_endpoint_live_hydration_proved": model_endpoint_reproofed,
        "model_endpoint_reproof": model_reproof,
        "stewardship_verdict": review.get("stewardship_verdict"),
        "operator_rejection_superseded": operator_rejection_superseded,
        "domain_quality_settlement_ready": domain_quality_settlement_ready,
        "fresh_visual_proof_captured": bool(
            review.get("fresh_visual_proof_captured")
            or latest_proof.get("fresh_visual_proof_captured")
            or latest_proof.get("ok")
        ),
        "all_requested_viewports_captured": bool(
            latest_proof.get("all_requested_viewports_captured") or latest_proof.get("ok")
        ),
        "required_next_packet": review.get("required_next_packet"),
        "finding_codes": [
            str(row.get("code") or "")
            for row in review.get("findings") or []
            if isinstance(row, Mapping) and row.get("code")
        ],
    }


