def _domain_weaver_path_fission_bucket(path: str) -> str:
    if path.startswith("ION/04_packages/kernel/"):
        return "kernel_runtime"
    if path.startswith("ION/08_ui/"):
        return "cockpit_surface"
    if path.startswith("ION/tests/"):
        return "validation"
    if path.startswith("browser_extension/"):
        return "browser_extension"
    if path.startswith("ION/05_context/"):
        return "context_state"
    if path.startswith("ION/02_architecture/") or path.startswith("ION/03_registry/") or path.startswith("ION/07_templates/"):
        return "canon_registry"
    if path.startswith("Needs_Routed/"):
        return "needs_routed_intake"
    return "miscellaneous"


def _domain_weaver_fission_dryrun_candidate(
    root: Path,
    *,
    domains_out: list[Mapping[str, Any]],
    edges: list[Mapping[str, Any]],
    materialize: bool = False,
) -> dict[str, Any]:
    edge_counts: dict[str, int] = {}
    for edge in edges:
        if not isinstance(edge, Mapping):
            continue
        for key in ("from", "to"):
            node = str(edge.get(key) or "")
            if node:
                edge_counts[node] = edge_counts.get(node, 0) + 1
    candidates: list[tuple[int, str, Mapping[str, Any]]] = []
    for domain in domains_out:
        if domain.get("candidate_domain"):
            continue
        domain_id = str(domain.get("domain_id") or "")
        paths = [str(path) for path in domain.get("paths") or [] if str(path)]
        if not domain_id:
            continue
        score = len(paths) * 2 + int(domain.get("agent_count") or 0) * 3 + edge_counts.get(domain_id, 0)
        candidates.append((score, domain_id, domain))
    candidates.sort(key=lambda item: (-item[0], item[1]))
    if not candidates:
        proposal = {
            "schema_id": "ion.domain_weaver.domain_fission_dryrun.v0_1_candidate",
            "status": "no_fission_candidate_available",
            "dry_run_ready": False,
            "summary": {
                "source_domain_id": "",
                "pressure_score": 0,
                "proposed_child_domain_count": 0,
                "active_registry_write_count": 0,
            },
            "proposed_child_domains": [],
            "authority": {
                "candidate_dryrun_only": True,
                "production_authority": False,
                "live_execution_authority": False,
                "accepted_state_authority": False,
                "secrets_authority": False,
            },
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        }
    else:
        pressure_score, source_domain_id, source_domain = candidates[0]
        source_paths = [str(path) for path in source_domain.get("paths") or [] if str(path)]
        buckets: dict[str, list[str]] = {}
        for path in source_paths:
            bucket = _domain_weaver_path_fission_bucket(path)
            buckets.setdefault(bucket, []).append(path)
        ordered_buckets = sorted(buckets.items(), key=lambda item: (-len(item[1]), item[0]))
        source_stem = _safe_id(source_domain_id.removeprefix("domain."))
        child_domains: list[dict[str, Any]] = []
        for ordinal, (bucket, paths) in enumerate(ordered_buckets[:3], start=1):
            child_domains.append(
                {
                    "ordinal": ordinal,
                    "domain_id": f"domain.{source_stem}_{bucket}_candidate",
                    "display_name": f"{source_domain_id} / {bucket.replace('_', ' ')}",
                    "source_domain_id": source_domain_id,
                    "fission_bucket": bucket,
                    "status": "candidate_dryrun_not_active_registry",
                    "path_count": len(paths),
                    "paths": paths,
                    "suggested_steward_class": (
                        "steward.runtime"
                        if bucket == "kernel_runtime"
                        else "steward.ui_surface"
                        if bucket == "cockpit_surface"
                        else "steward.validation"
                        if bucket == "validation"
                        else "steward.context"
                        if bucket == "context_state"
                        else "steward.domain"
                    ),
                    "active_registry_write_performed": False,
                    "accepted_ion_state": False,
                }
            )
        proposal = {
            "schema_id": "ion.domain_weaver.domain_fission_dryrun.v0_1_candidate",
            "status": "candidate_fission_dryrun_ready",
            "dry_run_ready": bool(child_domains),
            "source_domain": {
                "domain_id": source_domain_id,
                "display_name": source_domain.get("display_name"),
                "path_count": len(source_paths),
                "agent_count": source_domain.get("agent_count", 0),
                "edge_count": edge_counts.get(source_domain_id, 0),
                "pressure_score": pressure_score,
            },
            "split_rule": "Group source-domain paths by implementation surface so an overloaded domain can propose bounded child stewards without writing active registry state.",
            "proposed_child_domains": child_domains,
            "summary": {
                "source_domain_id": source_domain_id,
                "pressure_score": pressure_score,
                "source_path_count": len(source_paths),
                "source_agent_count": source_domain.get("agent_count", 0),
                "source_edge_count": edge_counts.get(source_domain_id, 0),
                "proposed_child_domain_count": len(child_domains),
                "active_registry_write_count": 0,
                "accepted_state_count": 0,
            },
            "authority": {
                "candidate_dryrun_only": True,
                "production_authority": False,
                "live_execution_authority": False,
                "accepted_state_authority": False,
                "secrets_authority": False,
            },
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        }
    materialized_paths: list[str] = []
    if materialize:
        path = root / DOMAIN_WEAVER_FISSION_DRYRUN_PROPOSAL_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(proposal, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        materialized_paths.append(DOMAIN_WEAVER_FISSION_DRYRUN_PROPOSAL_PATH.as_posix())
    proposal["proposal_path"] = DOMAIN_WEAVER_FISSION_DRYRUN_PROPOSAL_PATH.as_posix()
    proposal["proposal_ref"] = _file_ref(
        root,
        DOMAIN_WEAVER_FISSION_DRYRUN_PROPOSAL_PATH,
        "Candidate Domain Weaver fission dry-run proposal.",
        required=False,
    )
    proposal["materialized_paths"] = materialized_paths
    return proposal


