def _domain_weaver_topology_ref_text(root: Path, value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    root_prefix = root.as_posix().rstrip("/") + "/"
    if text.startswith(root_prefix):
        text = text[len(root_prefix) :]
    return text.lstrip("./")


def _domain_weaver_path_owner(
    root: Path,
    value: Any,
    domain_path_prefixes: list[tuple[str, str]],
) -> str:
    text = _domain_weaver_topology_ref_text(root, value)
    if not text:
        return ""
    for prefix, domain_id in domain_path_prefixes:
        if text == prefix or text.startswith(prefix.rstrip("/") + "/"):
            return domain_id
    return ""


def _domain_weaver_role_groups_for_domain(domain: Mapping[str, Any]) -> dict[str, list[str]]:
    groups: dict[str, list[str]] = {
        "primary_specialists": [],
        "secondary_couplings": [],
        "review_reflex": [],
    }
    for role in domain.get("agent_roles") or []:
        if not isinstance(role, Mapping):
            continue
        role_id = str(role.get("role_id") or "")
        if not role_id:
            continue
        relationships = {str(item or "") for item in role.get("relationships") or []}
        display = str(role.get("display_name") or role_id).lower()
        if "primary" in relationships or "mount" in relationships:
            groups["primary_specialists"].append(role_id)
        elif "nemesis" in display or "review" in display or "steward" in display:
            groups["review_reflex"].append(role_id)
        else:
            groups["secondary_couplings"].append(role_id)
    return {key: value for key, value in groups.items() if value}


def _domain_weaver_adaptive_topology_controls(
    *,
    active_domain_count: int,
    agent_count: int,
    path_count: int,
    bucket_count: int,
    bucket_concentration: float,
    cross_context_ref_count: int,
    dominant_coupling_count: int,
    coupling_coefficient: float,
    internal_operational_volume: int,
    fission_pressure: int,
) -> dict[str, Any]:
    active_domain_count = max(1, int(active_domain_count or 0))
    agent_count = max(0, int(agent_count or 0))
    path_count = max(0, int(path_count or 0))
    bucket_count = max(0, int(bucket_count or 0))
    cross_context_ref_count = max(0, int(cross_context_ref_count or 0))
    dominant_coupling_count = max(0, int(dominant_coupling_count or 0))
    internal_operational_volume = max(1, int(internal_operational_volume or 0))
    fission_pressure = max(0, int(fission_pressure or 0))
    coupling_units = max(0, int(round(float(coupling_coefficient or 0.0) * 100)))
    concentration_units = max(0, int(round(float(bucket_concentration or 0.0) * 10)))
    graph_pressure = (
        dominant_coupling_count
        + cross_context_ref_count
        + max(0, coupling_units // max(1, active_domain_count))
        + max(0, fission_pressure // max(1, active_domain_count))
    )
    structural_diversity = max(1, bucket_count + (1 if path_count else 0))
    coupling_threshold = round(
        max(
            0.08,
            min(
                0.85,
                (structural_diversity + max(1, path_count)) / max(1, internal_operational_volume + graph_pressure),
            ),
        ),
        3,
    )
    binding_pressure = max(
        1,
        structural_diversity
        + graph_pressure
        + max(0, concentration_units // 2)
        + (1 if not path_count and agent_count else 0),
    )
    specialist_binding_budget = max(1, internal_operational_volume // binding_pressure)
    topology_group_floor = max(
        1,
        min(
            max(1, agent_count),
            int(round((agent_count + structural_diversity + dominant_coupling_count) ** 0.5)),
        ),
    )
    if agent_count > 1:
        specialist_binding_budget = max(specialist_binding_budget, topology_group_floor)
    if not path_count and agent_count:
        role_only_group = max(
            topology_group_floor,
            max(1, agent_count // max(1, dominant_coupling_count + cross_context_ref_count)),
        )
        specialist_binding_budget = max(1, min(max(specialist_binding_budget, role_only_group), agent_count))
    recommended_child_domain_count = 0
    if agent_count > specialist_binding_budget:
        recommended_child_domain_count = (agent_count + specialist_binding_budget - 1) // specialist_binding_budget
    elif float(coupling_coefficient or 0.0) > coupling_threshold:
        recommended_child_domain_count = max(1, bucket_count or dominant_coupling_count or cross_context_ref_count or 1)
    return {
        "control_mode": "adaptive_topology_derived",
        "fixed_domain_count_target": False,
        "fixed_specialist_binding_limit": False,
        "coupling_threshold": coupling_threshold,
        "specialist_binding_budget": specialist_binding_budget,
        "recommended_child_domain_count": recommended_child_domain_count,
        "graph_pressure": graph_pressure,
        "binding_pressure": binding_pressure,
        "structural_diversity": structural_diversity,
        "operator_parallelism_reference_ceiling": DOMAIN_WEAVER_OPERATOR_PARALLELISM_REFERENCE_CEILING,
        "operator_parallelism_reference_is_target": False,
    }


