    plan = _as_mapping(projection.get("dynamic_swarm_operation_plan"))
    if not plan:
        plan = _read_json_file(root / DOMAIN_WEAVER_DYNAMIC_SWARM_OPERATION_PLAN_PATH)
    plan_summary = _as_mapping(plan.get("summary"))
    plan_controls = _as_mapping(plan.get("controls"))
    candidate_lanes = [row for row in plan.get("candidate_lanes") or [] if isinstance(row, Mapping)]
    templates: list[dict[str, Any]] = []
