def _domain_weaver_context_receipt_hash_drift(root: Path, receipt_rel: str) -> dict[str, Any]:
    if not receipt_rel:
        return {
            "receipt_path": "",
            "receipt_present": False,
            "drift_count": 0,
            "missing_current_path_count": 0,
            "drift_records": [],
        }
    receipt_path = root / receipt_rel
    receipt = _read_json_file(receipt_path)
    if not receipt:
        return {
            "receipt_path": receipt_rel,
            "receipt_present": False,
            "drift_count": 0,
            "missing_current_path_count": 0,
            "drift_records": [],
        }
    drift_records: list[dict[str, Any]] = []
    missing_count = 0
    for row in receipt.get("required_context_reads") or []:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("kind") or "") != "file":
            continue
        path_text = str(row.get("path") or "").strip()
        expected_sha = str(row.get("sha256") or "").strip()
        if not path_text or not expected_sha:
            continue
        current_path = root / path_text
        if not current_path.is_file():
            missing_count += 1
            continue
        current_sha = _sha256_file(current_path)
        if current_sha != expected_sha:
            drift_records.append(
                {
                    "path": path_text,
                    "receipt_sha256": expected_sha,
                    "current_sha256": current_sha,
                }
            )
    return {
        "receipt_path": receipt_rel,
        "receipt_present": True,
        "drift_count": len(drift_records),
        "missing_current_path_count": missing_count,
        "drift_records": drift_records[:20],
    }


def _domain_weaver_dynamic_swarm_run_records_by_request(root: Path) -> dict[str, list[dict[str, Any]]]:
    records: dict[str, list[dict[str, Any]]] = {}
    for run_path in sorted((root / CODEX_QUEUE_RUNS_DIR).glob("codex_run_*dynamic_swarm*/run.json")):
        run = _read_json_file(run_path)
        if not run:
            continue
        request_id = str(run.get("request_id") or "").strip()
        if not request_id:
            request_path = str(run.get("request_path") or "")
            request_id = Path(request_path).stem if request_path else ""
        if not request_id:
            continue
        body_rel = str(run.get("task_return_body_path") or "")
        receipt_rel = str(run.get("context_receipt_path") or "")
        submit_result = _as_mapping(run.get("submit_result"))
        command = [str(item) for item in run.get("codex_command") or []]
        record = {
            "run_packet_path": _rel(root, run_path),
            "status": run.get("status"),
            "request_path": run.get("request_path"),
            "task_return_body_path": body_rel,
            "task_return_body_present": bool(body_rel and (root / body_rel).is_file()),
            "latest_return_packet_path": run.get("latest_return_packet_path") or submit_result.get("packet_path"),
            "submit_result_packet_path": submit_result.get("packet_path"),
            "context_receipt_path": receipt_rel,
            "context_receipt_present": bool(receipt_rel and (root / receipt_rel).is_file()),
            "context_receipt_hash_drift": _domain_weaver_context_receipt_hash_drift(root, receipt_rel),
            "codex_service_tier": run.get("codex_service_tier"),
            "codex_command_has_fast_service_tier": "service_tier=fast" in command,
            "worker_pid": run.get("worker_pid") or run.get("pid"),
            "worker_sign_in_status": run.get("worker_sign_in_status"),
            "failure_classification": run.get("failure_classification"),
            "completed_at": run.get("completed_at"),
        }
        records.setdefault(request_id, []).append(record)
    return records


def _domain_weaver_dynamic_swarm_fresh_context_reconciliation(
    root: Path,
    projection: Mapping[str, Any],
    *,
    materialize: bool = True,
) -> dict[str, Any]:
    terminal_statuses = {
        "RETURN_RECORDED_PROOF_ACCEPTED",
        "RETURN_RECORDED_PROOF_BLOCKED",
        "RETURN_TEMPLATE_INVALID",
    }
    accepted_statuses = {"RETURN_RECORDED_PROOF_ACCEPTED"}
    blocked_statuses = {"RETURN_RECORDED_PROOF_BLOCKED", "RETURN_TEMPLATE_INVALID"}
    failed_run_statuses = {
        "CODEX_CLI_VANISHED_NO_OUTPUT",
        "DAEMON_WORKER_EXITED_WITHOUT_FINALIZATION",
        "CODEX_QUEUE_RUNNER_FAILED",
        "CODEX_CLI_EXIT_NONZERO",
        "CODEX_CLI_TIMEOUT",
    }
    plan = _as_mapping(projection.get("dynamic_swarm_operation_plan"))
    templates = _domain_weaver_dynamic_swarm_candidate_work_request_templates(root, projection)
    run_records = _domain_weaver_dynamic_swarm_run_records_by_request(root)
    lane_records: list[dict[str, Any]] = []
    for template in templates:
        request_id = str(template.get("request_id") or "")
        request_rel = str(template.get("packet_path") or "")
        request = _read_json_file(root / request_rel)
        lane_payload = _as_mapping(request.get("domain_weaver_dynamic_swarm_candidate_lane"))
        if not lane_payload:
            lane_payload = _as_mapping(template.get("domain_weaver_dynamic_swarm_candidate_lane"))
        lane_ordinal = int(lane_payload.get("lane_ordinal") or 0)
        status = str(request.get("status") or "MISSING_REQUEST").strip()
        return_paths = _clean_list(request.get("return_packet_paths") or [])
        runs = run_records.get(request_id, [])
        latest_run = runs[-1] if runs else {}
        run_statuses = _clean_list([row.get("status") for row in runs])
        context_drifts = [_as_mapping(row.get("context_receipt_hash_drift")) for row in runs]
        context_drift_count = sum(int(row.get("drift_count") or 0) for row in context_drifts)
        context_missing_count = sum(int(row.get("missing_current_path_count") or 0) for row in context_drifts)
        running = any(str(row.get("status") or "") == "CODEX_CLI_RUNNING" for row in runs) and status not in terminal_statuses
        stranded = status not in terminal_statuses and any(
            str(row.get("status") or "") in failed_run_statuses and bool(row.get("task_return_body_present"))
            for row in runs
        )
        fast_ready = bool(
            status == "QUEUED_FOR_CODEX_CARRIER"
            and request.get("requested_service_tier") == "fast"
            and request.get("codex_service_tier") == "fast"
            and _as_mapping(request.get("codex_model_override")).get("service_tier") == "fast"
            and lane_payload.get("requested_service_tier") == "fast"
        )
        if status in accepted_statuses:
            lane_state = "accepted"
        elif status in blocked_statuses:
            lane_state = "blocked"
        elif running:
            lane_state = "running"
        elif stranded:
            lane_state = "stranded_body_needs_submit"
        elif status == "QUEUED_FOR_CODEX_CARRIER":
            lane_state = "queueable"
        elif status == "MISSING_REQUEST":
            lane_state = "missing_request"
        else:
            lane_state = "unresolved"
        lane_records.append(
            {
                "lane_ordinal": lane_ordinal,
                "domain_id": lane_payload.get("domain_id"),
                "display_name": lane_payload.get("display_name"),
                "lane_id": request.get("lane_id") or template.get("lane_id"),
                "work_class": request.get("work_class") or template.get("work_class"),
                "request_id": request_id,
                "request_path": request_rel,
                "request_present": bool(request),
                "request_status": status,
                "lane_state": lane_state,
                "latest_return_packet_path": request.get("latest_return_packet_path"),
                "return_packet_paths": return_paths,
                "duplicate_return_count": max(0, len(return_paths) - 1),
                "latest_task_return_machine_receipt_path": request.get("latest_task_return_machine_receipt_path"),
                "run_count": len(runs),
                "run_statuses": run_statuses,
                "latest_run_packet_path": latest_run.get("run_packet_path"),
                "latest_run_status": latest_run.get("status"),
                "latest_run_task_return_body_path": latest_run.get("task_return_body_path"),
                "latest_run_task_return_body_present": bool(latest_run.get("task_return_body_present")),
                "context_hash_drift_count": context_drift_count,
                "context_missing_current_path_count": context_missing_count,
                "latest_context_hash_drift_sample": _as_mapping(
                    latest_run.get("context_receipt_hash_drift")
                ).get("drift_records", [])[:5],
                "queued_fast_service_tier_ready": fast_ready,
                "historical_fast_service_tier_claim": bool(
                    status in terminal_statuses
                    and (
                        request.get("requested_service_tier") == "fast"
                        or request.get("codex_service_tier") == "fast"
                        or _as_mapping(request.get("codex_model_override")).get("service_tier") == "fast"
                        or lane_payload.get("requested_service_tier") == "fast"
                    )
                ),
            }
        )
    lane_records.sort(key=lambda row: int(row.get("lane_ordinal") or 0))
    accepted_count = sum(1 for row in lane_records if row.get("lane_state") == "accepted")
    blocked_count = sum(1 for row in lane_records if row.get("lane_state") == "blocked")
    queueable_count = sum(1 for row in lane_records if row.get("lane_state") == "queueable")
    running_count = sum(1 for row in lane_records if row.get("lane_state") == "running")
    stranded_count = sum(1 for row in lane_records if row.get("lane_state") == "stranded_body_needs_submit")
    unresolved_count = sum(
        1
        for row in lane_records
        if row.get("lane_state") in {"missing_request", "unresolved"}
    )
    duplicate_return_lane_count = sum(1 for row in lane_records if int(row.get("duplicate_return_count") or 0) > 0)
    historical_fast_claim_count = sum(1 for row in lane_records if row.get("historical_fast_service_tier_claim"))
    context_drift_lane_count = sum(1 for row in lane_records if int(row.get("context_hash_drift_count") or 0) > 0)
    context_drift_record_count = sum(int(row.get("context_hash_drift_count") or 0) for row in lane_records)
    queued_fast_ready_count = sum(1 for row in lane_records if row.get("queued_fast_service_tier_ready"))
    if stranded_count or running_count or unresolved_count:
        next_action = "reconcile_stranded_or_running_lanes_before_worker_start"
    elif queueable_count:
        next_action = "start_dynamic_swarm_candidate_workers"
    else:
        next_action = "queue_dynamic_swarm_fanin_settlement_reissue"
    result = {
        "schema_id": "ion.domain_weaver.dynamic_swarm_fresh_context_return_monitor_stranded_run_reconciliation.v0_1_candidate",
        "generated_at": _now(),
        "status": "fresh_context_return_monitor_reconciled",
        "packet_id": (
            "PCKT-DOMAIN-WEAVER-DYNAMIC-SWARM-FRESH-CONTEXT-RETURN-MONITOR-"
            "STRANDED-RUN-RECONCILIATION-20260602-ATTEMPT-001"
        ),
        "source_plan_path": DOMAIN_WEAVER_DYNAMIC_SWARM_OPERATION_PLAN_PATH.as_posix(),
        "queue_ledger_path": DOMAIN_WEAVER_DYNAMIC_SWARM_CANDIDATE_QUEUE_LEDGER_PATH.as_posix(),
        "summary": {
            "expected_lane_count": len(templates),
            "observed_lane_count": len(lane_records),
            "accepted_return_count": accepted_count,
            "blocked_return_count": blocked_count,
            "queueable_start_request_count": queueable_count,
            "running_lane_count": running_count,
            "stranded_lane_count": stranded_count,
            "unresolved_lane_count": unresolved_count,
            "duplicate_return_lane_count": duplicate_return_lane_count,
            "context_hash_drift_lane_count": context_drift_lane_count,
            "context_hash_drift_record_count": context_drift_record_count,
            "historical_fast_service_tier_claim_count": historical_fast_claim_count,
            "queued_fast_service_tier_ready_count": queued_fast_ready_count,
            "all_lanes_resolved_for_fanin": bool(
                len(lane_records) == len(templates)
                and queueable_count == 0
                and running_count == 0
                and stranded_count == 0
                and unresolved_count == 0
            ),
            "next_lawful_action": next_action,
            "dynamic_start_window": _as_mapping(plan.get("summary")).get("dynamic_start_window", 0),
            "fixed_domain_count_target": False,
            "operator_parallelism_reference_is_target": False,
        },
        "lane_records": lane_records,
        "authority": {
            "candidate_reconciliation_only": True,
            "source_edit_authority": False,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    if materialize:
        path = root / DOMAIN_WEAVER_DYNAMIC_SWARM_FRESH_CONTEXT_RECONCILIATION_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return result


