def _domain_weaver_latest_dynamic_swarm_context_duplicate_lifecycle_refs(root: Path) -> dict[str, Any]:
    prefix = "codex_req_domain_weaver_dynamic_swarm_context_duplicate_lifecycle_gate_20260602_attempt_"
    request_rows: list[tuple[float, Path, dict[str, Any], dict[str, Any]]] = []
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        payload = _read_json_file(path)
        return_path = str(payload.get("latest_return_packet_path") or "").strip()
        latest_return = _read_json_file(root / return_path) if return_path else {}
        if (
            str(payload.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
            and latest_return.get("accepted_for_carrier_intake") is True
        ):
            request_rows.append((path.stat().st_mtime, path, payload, latest_return))
    if not request_rows:
        return {
            "accepted": False,
            "fresh_current_settlement_ready": False,
            "finding": "dynamic_swarm_context_duplicate_lifecycle_gate_not_accepted",
        }
    _mtime, request_path, request, latest_return = sorted(request_rows, key=lambda row: row[0])[-1]
    request_rel = _rel(root, request_path)
    return_path = str(request.get("latest_return_packet_path") or "").strip()
    run_packet_path = ""
    context_receipt_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        run_receipt = str(run_payload.get("context_receipt_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
        if run_receipt and (root / run_receipt).is_file():
            context_receipt_path = run_receipt
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = ""
    if task_return_body_path and (root / task_return_body_path).is_file():
        body_text = (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
    recommended_packet_id = ""
    match = re.search(
        r"`?(PCKT-DOMAIN-WEAVER-DYNAMIC-SWARM-FRESH-CURRENT-LIFECYCLE-SETTLEMENT-AND-"
        r"CONTROL-PLANE-DRIFT-RECONCILIATION-20260602-ATTEMPT-001)`?",
        body_text,
    )
    if match:
        recommended_packet_id = match.group(1)
    fresh_current_settlement_ready = bool(
        task_return_body_path
        and recommended_packet_id == DOMAIN_WEAVER_DYNAMIC_SWARM_FRESH_CURRENT_LIFECYCLE_PACKET_ID
    )
    return {
        "accepted": True,
        "fresh_current_settlement_ready": fresh_current_settlement_ready,
        "finding": "" if fresh_current_settlement_ready else "accepted_lifecycle_gate_missing_fresh_current_packet",
        "request_path": request_rel,
        "request_id": request.get("request_id"),
        "return_path": return_path,
        "run_packet_path": run_packet_path,
        "context_receipt_path": context_receipt_path,
        "task_return_body_path": task_return_body_path,
        "machine_receipt_path": str(latest_return.get("machine_receipt_path") or ""),
        "recommended_next_packet_id": recommended_packet_id,
        "request": request,
    }


def _domain_weaver_dynamic_swarm_fresh_current_lifecycle_settlement(
    root: Path,
    *,
    materialize: bool = True,
) -> dict[str, Any]:
    lifecycle = _domain_weaver_latest_dynamic_swarm_context_duplicate_lifecycle_refs(root)
    lifecycle_request = _as_mapping(lifecycle.get("request"))
    lifecycle_payload = _as_mapping(lifecycle_request.get("domain_weaver_dynamic_swarm_context_duplicate_lifecycle_gate"))
    receipt = _read_json_file(root / str(lifecycle.get("context_receipt_path") or ""))
    receipt_rows = {
        str(row.get("path") or ""): row
        for row in receipt.get("required_context_reads") or []
        if isinstance(row, Mapping) and row.get("path")
    }
    required_paths = _clean_list(
        [
            str(lifecycle.get("request_path") or ""),
            str(lifecycle.get("return_path") or ""),
            str(lifecycle.get("machine_receipt_path") or ""),
            str(lifecycle.get("run_packet_path") or ""),
            str(lifecycle.get("context_receipt_path") or ""),
            str(lifecycle.get("task_return_body_path") or ""),
            CODEX_WORK_QUEUE_PATH.as_posix(),
            CODEX_WORK_LANE_INDEX_PATH.as_posix(),
            *(lifecycle_request.get("required_context_reads") or []),
            *list(receipt_rows.keys()),
        ]
    )
    current_rows: list[dict[str, Any]] = []
    missing_count = 0
    changed_count = 0
    control_plane_changed_count = 0
    volatile_names = {
        CODEX_WORK_QUEUE_PATH.as_posix(),
        CODEX_WORK_LANE_INDEX_PATH.as_posix(),
        str(lifecycle.get("request_path") or ""),
    }
    for rel_path in required_paths:
        current_path = root / rel_path
        exists = current_path.is_file()
        current_sha = _sha256_file(current_path) if exists else ""
        receipt_sha = str(_as_mapping(receipt_rows.get(rel_path)).get("sha256") or "")
        changed = bool(receipt_sha and current_sha and receipt_sha != current_sha)
        if not exists:
            missing_count += 1
        if changed:
            changed_count += 1
            if rel_path in volatile_names:
                control_plane_changed_count += 1
        current_rows.append(
            {
                "path": rel_path,
                "exists": exists,
                "sha256_current": current_sha,
                "sha256_receipt": receipt_sha,
                "changed_after_lifecycle_receipt": changed,
                "control_plane_volatile_path": rel_path in volatile_names,
            }
        )
    lane_records = [row for row in lifecycle_payload.get("lane_records") or [] if isinstance(row, Mapping)]
    selected_latest_rows: list[dict[str, Any]] = []
    selected_missing_count = 0
    selected_not_accepted_count = 0
    duplicate_return_record_count = 0
    for row in lane_records:
        return_paths = _clean_list(row.get("return_packet_paths") or [])
        duplicate_return_record_count += max(0, len(return_paths) - 1)
        selected_return = str(row.get("latest_return_packet_path") or "")
        selected_payload = _read_json_file(root / selected_return) if selected_return else {}
        selected_exists = bool(selected_return and (root / selected_return).is_file())
        selected_accepted = bool(selected_payload.get("accepted_for_carrier_intake") is True)
        if not selected_exists:
            selected_missing_count += 1
        if selected_exists and not selected_accepted:
            selected_not_accepted_count += 1
        selected_latest_rows.append(
            {
                "lane_ordinal": row.get("lane_ordinal"),
                "domain_id": row.get("domain_id"),
                "latest_return_packet_path": selected_return,
                "latest_return_exists": selected_exists,
                "latest_return_accepted_for_carrier_intake": selected_accepted,
                "return_packet_paths": return_paths,
                "duplicate_return_count": max(0, len(return_paths) - 1),
                "context_hash_drift_count": row.get("context_hash_drift_count"),
                "inheritance_classification": "candidate_evidence_only_preserve_lineage",
            }
        )
    selected_binding_ready = bool(
        lifecycle.get("fresh_current_settlement_ready")
        and missing_count == 0
        and selected_missing_count == 0
        and selected_not_accepted_count == 0
        and len(selected_latest_rows) == int(lifecycle_payload.get("expected_lane_count") or len(selected_latest_rows))
    )
    next_lawful_action = (
        "queue_topology_evolution_materialization_readiness_proof_gate"
        if selected_binding_ready
        else "repair_fresh_current_lifecycle_settlement_inputs"
    )
    result = {
        "schema_id": "ion.domain_weaver.dynamic_swarm_fresh_current_lifecycle_settlement.v0_1_candidate",
        "generated_at": _now(),
        "packet_id": DOMAIN_WEAVER_DYNAMIC_SWARM_FRESH_CURRENT_LIFECYCLE_PACKET_ID,
        "status": "fresh_current_lifecycle_settlement_materialized",
        "source_lifecycle_request_path": lifecycle.get("request_path"),
        "source_lifecycle_return_path": lifecycle.get("return_path"),
        "source_lifecycle_task_return_body_path": lifecycle.get("task_return_body_path"),
        "source_lifecycle_context_receipt_path": lifecycle.get("context_receipt_path"),
        "summary": {
            "lifecycle_gate_accepted": bool(lifecycle.get("accepted")),
            "fresh_current_settlement_ready": selected_binding_ready,
            "current_replay_path_count": len(current_rows),
            "missing_current_path_count": missing_count,
            "changed_after_lifecycle_receipt_count": changed_count,
            "control_plane_volatile_changed_after_receipt_count": control_plane_changed_count,
            "expected_lane_count": lifecycle_payload.get("expected_lane_count", len(selected_latest_rows)),
            "selected_latest_binding_count": len(selected_latest_rows),
            "selected_latest_missing_count": selected_missing_count,
            "selected_latest_not_accepted_count": selected_not_accepted_count,
            "duplicate_return_lane_count": lifecycle_payload.get("duplicate_return_lane_count", 0),
            "duplicate_return_record_count": duplicate_return_record_count,
            "context_hash_drift_lane_count": lifecycle_payload.get("context_hash_drift_lane_count", 0),
            "context_hash_drift_record_count": lifecycle_payload.get("context_hash_drift_record_count", 0),
            "next_lawful_action": next_lawful_action,
        },
        "current_context_rows": current_rows,
        "selected_latest_return_bindings": selected_latest_rows,
        "inheritance_decision": {
            "candidate_evidence_binding_allowed": selected_binding_ready,
            "topology_materialization_allowed": False,
            "vnext_production_spec_claim_allowed": False,
            "source_edit_allowed": False,
            "live_execution_allowed": False,
            "accepted_state_allowed": False,
            "production_allowed": False,
            "deletion_allowed": False,
            "duplicate_return_policy": "preserve_all_duplicate_returns_as_lineage_evidence",
        },
        "authority": {
            "candidate_reconciliation_only": True,
            "source_edit_authority": False,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
            "deletion_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    if materialize:
        path = root / DOMAIN_WEAVER_DYNAMIC_SWARM_FRESH_CURRENT_LIFECYCLE_SETTLEMENT_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return result


