def _domain_weaver_latest_founding_audit_refs(root: Path) -> dict[str, Any]:
    prefix = "codex_req_domain_weaver_founding_assembly_nemesis_audit_20260601_attempt_"
    request_rows: list[tuple[float, Path, dict[str, Any]]] = []
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        payload = _read_json_file(path)
        if str(payload.get("status") or "") != "RETURN_RECORDED_PROOF_ACCEPTED":
            continue
        request_rows.append((path.stat().st_mtime, path, payload))
    if not request_rows:
        return {
            "accepted": False,
            "finding": "founding_assembly_nemesis_audit_not_accepted",
        }
    _mtime, request_path, request = sorted(request_rows, key=lambda row: row[0])[-1]
    return_path = str(request.get("latest_return_packet_path") or "").strip()
    run_body_path = ""
    run_packet_path = ""
    run_prefix = "codex_run_"
    for run_path in sorted((root / CODEX_QUEUE_RUNS_DIR).glob(f"{run_prefix}*{prefix}*/run.json")):
        run = _read_json_file(run_path)
        if str(run.get("request_id") or "") != request.get("request_id"):
            continue
        body_path = str(run.get("task_return_body_path") or "").strip()
        if not body_path:
            candidate_body = run_path.parent / "task_return_body.md"
            if candidate_body.is_file():
                body_path = _rel(root, candidate_body)
        run_body_path = body_path
        run_packet_path = _rel(root, run_path)
    return {
        "accepted": True,
        "request_path": _rel(root, request_path),
        "request_id": request.get("request_id"),
        "return_path": return_path,
        "run_packet_path": run_packet_path,
        "task_return_body_path": run_body_path,
        "machine_receipt_path": str(
            _as_mapping(_read_json_file(root / return_path)).get("machine_receipt_path") or ""
        )
        if return_path
        else "",
    }


def _domain_weaver_foundation_wave0_attempt_index(root: Path, domain_id: str) -> int:
    prefix = f"codex_req_domain_weaver_foundation_wave0_{_safe_id(domain_id)}_20260601_attempt_"
    latest_index = 0
    reusable_index = 0
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        suffix = path.stem.replace(prefix, "", 1)
        try:
            index = int(suffix)
        except ValueError:
            continue
        latest_index = max(latest_index, index)
        status = str(_read_json_file(path).get("status") or "")
        if status in {
            "QUEUED_FOR_CODEX_CARRIER",
            "CLAIMED_BY_CODEX_QUEUE_RUNNER",
            "CODEX_QUEUE_RUNNER_WORKER_STARTED",
            "CODEX_CLI_RUNNING",
        }:
            reusable_index = max(reusable_index, index)
    return reusable_index or latest_index + 1


def _domain_weaver_latest_foundation_wave0_request_path(
    root: Path,
    domain_id: str,
    *,
    fallback_path: str = "",
) -> str:
    prefix = f"codex_req_domain_weaver_foundation_wave0_{_safe_id(domain_id)}_20260601_attempt_"
    latest: tuple[int, Path] | None = None
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        suffix = path.stem.replace(prefix, "", 1)
        try:
            index = int(suffix)
        except ValueError:
            continue
        if latest is None or index > latest[0]:
            latest = (index, path)
    if latest:
        return _rel(root, latest[1])
    return fallback_path


