def _domain_weaver_wave1_candidate_fanin_attempt_index(root: Path) -> int:
    prefix = "codex_req_domain_weaver_wave1_candidate_fanin_settlement_and_nemesis_review_20260601_attempt_"
    latest_index = 0
    reusable_index = 0
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        suffix = path.stem.replace(prefix, "", 1)
        try:
            index = int(suffix)
        except ValueError:
            continue
        latest_index = max(latest_index, index)
        status = str(_read_json_file(path).get("status") or "")
        if status in {
            "QUEUED_FOR_CODEX_CARRIER",
            "CLAIMED_BY_CODEX_QUEUE_RUNNER",
            "CODEX_QUEUE_RUNNER_WORKER_STARTED",
            "CODEX_CLI_RUNNING",
        }:
            reusable_index = max(reusable_index, index)
    return reusable_index or latest_index + 1


def _domain_weaver_wave1_candidate_return_records(root: Path) -> dict[str, Any]:
    records: list[dict[str, Any]] = []
    for route in DOMAIN_WEAVER_WAVE1_CANDIDATE_FANOUT_ROUTE:
        domain_id = str(route["domain_id"])
        latest = _domain_weaver_latest_wave1_candidate_fanout_request(root, domain_id)
        request_path = str(latest.get("path") or "")
        request = _as_mapping(latest.get("payload"))
        request_status = str(request.get("status") or latest.get("status") or "missing")
        run_path = ""
        if request_path:
            runs = _domain_weaver_request_run_packets(root, request_path)
            if runs:
                run_path = str(runs[-1].get("run_packet_path") or "")
        run = _read_json_file(root / run_path) if run_path else {}
        run_status = str(run.get("status") or "")
        return_paths = _unique_paths(
            [
                *[str(item) for item in request.get("return_packet_paths") or [] if str(item)],
                str(request.get("latest_return_packet_path") or ""),
                str(run.get("latest_return_packet_path") or ""),
            ]
        )
        latest_return_path = return_paths[-1] if return_paths else ""
        latest_return = _read_json_file(root / latest_return_path) if latest_return_path else {}
        context_result = _as_mapping(latest_return.get("context_proof_result"))
        template_result = _as_mapping(latest_return.get("template_action_proof_result"))
        task_return_body_path = str(run.get("task_return_body_path") or "")
        if task_return_body_path and not (root / task_return_body_path).is_file():
            task_return_body_path = ""
        if not task_return_body_path:
            task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
        if not task_return_body_path and run_path:
            body_candidate = (root / run_path).parent / "task_return_body.md"
            if body_candidate.is_file():
                task_return_body_path = _rel(root, body_candidate)
        latest_return_markdown_path = str(run.get("last_message_path") or "")
        if latest_return_markdown_path and not (root / latest_return_markdown_path).is_file():
            latest_return_markdown_path = ""
        accepted = bool(
            request_status == "RETURN_RECORDED_PROOF_ACCEPTED"
            and latest_return.get("accepted_for_carrier_intake")
        )
        blocked = bool(
            not accepted
            and (
                request_status in {"RETURN_RECORDED_PROOF_BLOCKED", "RETURN_TEMPLATE_INVALID", "CODEX_QUEUE_RUNNER_FAILED"}
                or run_status in {"RETURN_RECORDED_PROOF_BLOCKED", "RETURN_TEMPLATE_INVALID", "CODEX_CLI_VANISHED_NO_OUTPUT"}
                or (latest_return_path and latest_return.get("accepted_for_carrier_intake") is False)
            )
        )
        attempt_count = len(
            list(
                (root / CODEX_WORK_REQUESTS_DIR).glob(
                    f"codex_req_domain_weaver_wave1_{_safe_id(domain_id)}_20260601_attempt_*.json"
                )
            )
        )
        records.append(
            {
                "domain_id": domain_id,
                "agent_role": str(route["agent_role"]),
                "supporting_roles": [str(role) for role in route.get("supporting_roles") or [] if str(role)],
                "lane_id": str(route["lane_id"]),
                "request_id": request.get("request_id"),
                "request_path": request_path,
                "request_status": request_status,
                "run_packet_path": run_path,
                "run_status": run_status,
                "return_packet_paths": return_paths,
                "latest_return_packet_path": latest_return_path,
                "machine_receipt_path": str(latest_return.get("machine_receipt_path") or ""),
                "task_return_body_path": task_return_body_path,
                "latest_return_markdown_path": latest_return_markdown_path,
                "accepted_return": accepted,
                "explicit_blocked_receipt": blocked,
                "terminal": bool(accepted or blocked),
                "carrier_intake_accepted": bool(latest_return.get("accepted_for_carrier_intake")),
                "return_template_valid": bool(latest_return.get("return_template_valid")),
                "context_proof_accepted": bool(context_result.get("accepted")),
                "template_action_proof_accepted": bool(template_result.get("accepted")),
                "workload_diff_accepted": bool(latest_return.get("workload_diff_accepted")),
                "task_return_created_at": latest_return.get("created_at"),
                "candidate_attempt_count": attempt_count,
                "duplicate_attempt_count": max(attempt_count - 1, 0),
                "duplicate_return_packet_count": max(len(return_paths) - 1, 0),
                "selection_policy": "latest_attempt_per_declared_domain",
            }
        )

    expected_count = len(DOMAIN_WEAVER_WAVE1_CANDIDATE_FANOUT_ROUTE)
    accepted_count = sum(1 for record in records if record.get("accepted_return"))
    blocked_count = sum(1 for record in records if record.get("explicit_blocked_receipt"))
    terminal_count = sum(1 for record in records if record.get("terminal"))
    missing = [record["domain_id"] for record in records if not record.get("terminal")]
    return {
        "schema_id": "ion.domain_weaver.wave1_candidate_return_records.v0_1_candidate",
        "created_at": _now(),
        "source_queue_ledger_path": DOMAIN_WEAVER_WAVE1_CANDIDATE_FANOUT_QUEUE_LEDGER_PATH.as_posix(),
        "source_worker_start_ledger_path": DOMAIN_WEAVER_WAVE1_CANDIDATE_FANOUT_WORKER_START_QUEUE_LEDGER_PATH.as_posix(),
        "return_records": records,
        "summary": {
            "expected_return_count": expected_count,
            "terminal_return_count": terminal_count,
            "accepted_return_count": accepted_count,
            "explicit_blocked_receipt_count": blocked_count,
            "missing_or_running_return_count": max(expected_count - terminal_count, 0),
            "all_wave1_returns_terminal": bool(expected_count and terminal_count == expected_count),
            "missing_or_running_domains": missing,
            "duplicate_attempt_count": sum(int(record.get("duplicate_attempt_count") or 0) for record in records),
            "duplicate_return_packet_count": sum(int(record.get("duplicate_return_packet_count") or 0) for record in records),
        },
        "authority": {
            "candidate_wave1_fanin_observation_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }


