def _domain_weaver_latest_wave2_accepted_state_movement_refs(root: Path) -> dict[str, Any]:
    prefix = "codex_req_domain_weaver_wave2_candidate_source_patch_accepted_state_movement_20260601_attempt_"
    request_rows: list[tuple[float, Path, dict[str, Any]]] = []
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        payload = _read_json_file(path)
        return_path = str(payload.get("latest_return_packet_path") or "").strip()
        latest_return = _read_json_file(root / return_path) if return_path else {}
        if (
            str(payload.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
            and latest_return.get("accepted_for_carrier_intake") is True
        ):
            request_rows.append((path.stat().st_mtime, path, payload))
    if not request_rows:
        return {
            "accepted": False,
            "finding": "wave2_accepted_state_movement_not_accepted",
        }
    _mtime, request_path, request = sorted(request_rows, key=lambda row: row[0])[-1]
    return_path = str(request.get("latest_return_packet_path") or "").strip()
    latest_return = _read_json_file(root / return_path) if return_path else {}
    run_packet_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, _rel(root, request_path)):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    verdict = ""
    if task_return_body_path and (root / task_return_body_path).is_file():
        body_text = (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
        for line in body_text.splitlines():
            stripped = line.strip()
            if stripped.startswith("verdict:"):
                verdict = stripped.split(":", 1)[1].strip()
                break
        if not verdict and "NO_OP_BLOCKED_MISSING_EXPLICIT_ACCEPTED_STATE_MOVEMENT_AUTHORITY_RECEIPT" in body_text:
            verdict = "NO_OP_BLOCKED_MISSING_EXPLICIT_ACCEPTED_STATE_MOVEMENT_AUTHORITY_RECEIPT"
    movement = _as_mapping(request.get("domain_weaver_wave2_candidate_source_patch_accepted_state_movement"))
    return {
        "accepted": True,
        "request_path": _rel(root, request_path),
        "request_id": request.get("request_id"),
        "return_path": return_path,
        "run_packet_path": run_packet_path,
        "task_return_body_path": task_return_body_path,
        "machine_receipt_path": str(
            latest_return.get("machine_receipt_path") or request.get("latest_task_return_machine_receipt_path") or ""
        ),
        "verdict": verdict,
        "preview_path": movement.get("preview_path"),
        "rollback_matrix_path": movement.get("rollback_matrix_path"),
        "approval_limits_schema_path": movement.get("approval_limits_schema_path"),
        "source_patch_return_path": movement.get("source_patch_return_path"),
        "source_patch_settlement_return_path": movement.get("source_patch_settlement_return_path"),
        "readiness_gate_return_path": movement.get("readiness_gate_return_path"),
        "accepted_state_settlement_gate_return_path": movement.get("accepted_state_settlement_gate_return_path"),
        "accepted_state_authority_receipt_required": movement.get("accepted_state_authority_receipt_required"),
        "expected_noop_without_authority_receipt": movement.get("expected_noop_without_authority_receipt"),
    }


