def _domain_weaver_latest_operator_rejection_activity_city_candidate_implementation_refs(
    root: Path,
) -> dict[str, Any]:
    prefix = (
        "codex_req_domain_weaver_operator_rejection_activity_city_bounded_candidate_implementation_preview_"
        "20260602_attempt_"
    )
    request_rows: list[tuple[int, float, Path, dict[str, Any], dict[str, Any]]] = []
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        payload = _read_json_file(path)
        return_path = str(payload.get("latest_return_packet_path") or "").strip()
        latest_return = _read_json_file(root / return_path) if return_path else {}
        suffix = path.stem.replace(prefix, "", 1)
        try:
            attempt_index = int(suffix)
        except ValueError:
            attempt_index = 0
        if (
            str(payload.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
            and latest_return.get("accepted_for_carrier_intake") is True
        ):
            request_rows.append((attempt_index, path.stat().st_mtime, path, payload, latest_return))
    if not request_rows:
        return {
            "accepted": False,
            "served_route_proof_blocked": False,
            "finding": "operator_rejection_activity_city_candidate_implementation_not_accepted",
        }
    _attempt, _mtime, request_path, request, latest_return = sorted(
        request_rows,
        key=lambda row: (row[0], row[1], row[2].name),
    )[-1]
    request_rel = _rel(root, request_path)
    return_path = str(request.get("latest_return_packet_path") or "").strip()
    run_packet_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = (
        (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
        if task_return_body_path and (root / task_return_body_path).is_file()
        else ""
    )
    body_lower = body_text.lower()
    recommended_packet_id = ""
    match = re.search(r"`?(PCKT-DOMAIN-WEAVER-[A-Z0-9-]*SERVED-ROUTE[A-Z0-9-]*)`?", body_text)
    if match:
        recommended_packet_id = match.group(1)
    visual_proof_path = ""
    match = re.search(
        r"`?(ION/05_context/current/domain_weaver/visual_smoke/[A-Za-z0-9_.:/-]+activity_city_bounded_candidate_preview_visual_proof\.json)`?",
        body_text,
    )
    if match:
        visual_proof_path = match.group(1)
    artifact_manifest_path = ""
    matches = re.findall(
        r"`?(ION/05_context/current/domain_weaver/visual_smoke/[A-Za-z0-9_.:/-]+ARTIFACT_MANIFEST\.json)`?",
        body_text,
    )
    if matches:
        proof_dir = str(Path(visual_proof_path).parent) if visual_proof_path else ""
        same_proof_dir_matches = [rel for rel in matches if proof_dir and rel.startswith(f"{proof_dir}/")]
        artifact_manifest_path = (same_proof_dir_matches or matches)[-1]
    proof = _read_json_file(root / visual_proof_path) if visual_proof_path else {}
    proof_artifacts = _as_mapping(proof.get("artifacts"))
    screenshot_paths = _clean_list(
        [
            str(_as_mapping(proof_artifacts.get(key)).get("path") or "")
            for key in ("desktop_1440x1000", "tablet_1024x900", "mobile_390x844", "mobile_360x800")
        ]
    )
    implementation_source_paths = _clean_list(proof.get("implementation_source_paths"))
    if not implementation_source_paths:
        implementation_source_paths = _clean_list(
            re.findall(r"`?(ION/08_ui/joc_cockpit_shell/[A-Za-z0-9_.:/-]+)`?", body_text)
        )
    static_preview_path = str(_as_mapping(proof_artifacts.get("static_preview_html")).get("path") or "")
    served_route_proof_blocked = bool(
        "live served" in body_lower
        and "blocked" in body_lower
        and ("socket permissionerror" in body_lower or "preview ports" in body_lower or "static" in body_lower)
    )
    proof_contract = _as_mapping(proof.get("contract_checks"))
    return {
        "accepted": True,
        "served_route_proof_blocked": served_route_proof_blocked,
        "static_preview_proof_ready": bool(visual_proof_path and screenshot_paths),
        "operator_rejection_preserved": (
            "operator rejection remains active" in body_lower
            or "operator_rejection_superseded=false" in body_lower
            or '"operator_rejection_superseded": false' in body_lower
            or proof_contract.get("operator_rejection_superseded") is False
        ),
        "endpoint_hydration_not_acceptance": (
            "endpoint hydration" in body_lower
            and ("evidence only" in body_lower or "not acceptance" in body_lower)
        ),
        "request_path": request_rel,
        "request_id": request.get("request_id"),
        "return_path": return_path,
        "run_packet_path": run_packet_path,
        "task_return_body_path": task_return_body_path,
        "machine_receipt_path": str(
            latest_return.get("machine_receipt_path") or request.get("latest_task_return_machine_receipt_path") or ""
        ),
        "recommended_next_packet_id": recommended_packet_id,
        "visual_proof_path": visual_proof_path,
        "artifact_manifest_path": artifact_manifest_path,
        "static_preview_path": static_preview_path,
        "screenshot_paths": screenshot_paths,
        "implementation_source_paths": implementation_source_paths,
        "validation_present": "### VALIDATION" in body_text,
        "ui_implementation_present": "### UI IMPLEMENTATION" in body_text,
        "visual_proof_present": "### VISUAL PROOF" in body_text,
        "steward_verdict": (
            "PASS_BOUNDED_CANDIDATE_IMPLEMENTATION_PREVIEW_WITH_PROOF_LIMIT"
            if "PASS_BOUNDED_CANDIDATE_IMPLEMENTATION_PREVIEW_WITH_PROOF_LIMIT" in body_text
            else ""
        ),
        "nemesis_verdict": (
            "PASS_WITH_EXPLICIT_LIVE_ROUTE_PROOF_BLOCKER"
            if "PASS_WITH_EXPLICIT_LIVE_ROUTE_PROOF_BLOCKER" in body_text
            else ""
        ),
        "body_sha256": hashlib.sha256(body_text.encode("utf-8")).hexdigest() if body_text else "",
    }


def _domain_weaver_latest_operator_rejection_activity_city_served_route_proof_refs(
    root: Path,
) -> dict[str, Any]:
    prefix = (
        "codex_req_domain_weaver_operator_rejection_activity_city_served_route_proof_and_operator_review_"
        "20260602_attempt_"
    )
    request_rows: list[tuple[int, float, Path, dict[str, Any], dict[str, Any]]] = []
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        payload = _read_json_file(path)
        return_path = str(payload.get("latest_return_packet_path") or "").strip()
        latest_return = _read_json_file(root / return_path) if return_path else {}
        suffix = path.stem.replace(prefix, "", 1)
        try:
            attempt_index = int(suffix)
        except ValueError:
            attempt_index = 0
        if (
            str(payload.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
            and latest_return.get("accepted_for_carrier_intake") is True
        ):
            request_rows.append((attempt_index, path.stat().st_mtime, path, payload, latest_return))
    if not request_rows:
        return {
            "accepted": False,
            "served_route_blocked": False,
            "authorized_preview_reproof_ready": False,
            "finding": "operator_rejection_activity_city_served_route_proof_not_accepted",
        }
    _attempt, _mtime, request_path, request, latest_return = sorted(
        request_rows,
        key=lambda row: (row[0], row[1], row[2].name),
    )[-1]
    request_rel = _rel(root, request_path)
    return_path = str(request.get("latest_return_packet_path") or "").strip()
    run_packet_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = (
        (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
        if task_return_body_path and (root / task_return_body_path).is_file()
        else ""
    )
    body_lower = body_text.lower()
    recommended_packet_id = ""
    match = re.search(
        r"`?(PCKT-DOMAIN-WEAVER-ACTIVITY-CITY-AUTHORIZED-PREVIEW-LANE-SERVED-ROUTE-REPROOF-[A-Z0-9-]+)`?",
        body_text,
    )
    if match:
        recommended_packet_id = match.group(1)
    proof_blocker_path = ""
    match = re.search(
        r"`?(ION/05_context/current/domain_weaver/visual_smoke/[A-Za-z0-9_.:/-]+activity_city_served_route_proof_blocker\.json)`?",
        body_text,
    )
    if match:
        proof_blocker_path = match.group(1)
    artifact_manifest_path = ""
    matches = re.findall(
        r"`?(ION/05_context/current/domain_weaver/visual_smoke/[A-Za-z0-9_.:/-]+ARTIFACT_MANIFEST\.json)`?",
        body_text,
    )
    if matches:
        proof_dir = str(Path(proof_blocker_path).parent) if proof_blocker_path else ""
        same_proof_dir_matches = [rel for rel in matches if proof_dir and rel.startswith(f"{proof_dir}/")]
        artifact_manifest_path = (same_proof_dir_matches or matches)[-1]
    served_route_available: bool | None = None
    if re.search(r"\bserved_route_available\s*[:=]\s*true\b", body_text, flags=re.IGNORECASE):
        served_route_available = True
    elif re.search(r"\bserved_route_available\s*[:=]\s*false\b", body_text, flags=re.IGNORECASE):
        served_route_available = False
    served_screenshots_captured: bool | None = None
    if re.search(r"\bserved_screenshots_captured\s*[:=]\s*true\b", body_text, flags=re.IGNORECASE):
        served_screenshots_captured = True
    elif re.search(r"\bserved_screenshots_captured\s*[:=]\s*false\b", body_text, flags=re.IGNORECASE):
        served_screenshots_captured = False
    served_route_blocked = bool(
        "blocked_no_served_route_available" in body_lower
        or "served /cockpit#weave proof is blocked" in body_lower
        or "no_served_screenshots" in body_lower
        or served_route_available is False
        or served_screenshots_captured is False
    )
    operator_rejection_preserved = bool(
        "operator_rejection_superseded: false" in body_lower
        or "operator_rejection_superseded=false" in body_lower
        or "operator rejection preserved" in body_lower
        or "operator rejection remains" in body_lower
        or "operator rejection active" in body_lower
    )
    operator_acceptance_claim = bool(
        "operator_acceptance_claim: true" in body_lower
        or "operator_acceptance_claim=true" in body_lower
        or '"operator_acceptance_claim": true' in body_lower
        or "operator acceptance claim: true" in body_lower
    )
    authorized_preview_reproof_ready = bool(
        recommended_packet_id
        and ("authorized preview" in body_lower or "authorized-preview" in body_lower)
        and "reproof" in body_lower
    )
    return {
        "accepted": True,
        "served_route_blocked": served_route_blocked,
        "authorized_preview_reproof_ready": authorized_preview_reproof_ready,
        "finding": "" if authorized_preview_reproof_ready else "accepted_served_route_proof_missing_reproof_gate",
        "request_path": request_rel,
        "request_id": request.get("request_id"),
        "return_path": return_path,
        "run_packet_path": run_packet_path,
        "task_return_body_path": task_return_body_path,
        "machine_receipt_path": str(
            latest_return.get("machine_receipt_path") or request.get("latest_task_return_machine_receipt_path") or ""
        ),
        "proof_blocker_path": proof_blocker_path,
        "artifact_manifest_path": artifact_manifest_path,
        "recommended_next_packet_id": recommended_packet_id,
        "served_route_available": served_route_available,
        "served_screenshots_captured": served_screenshots_captured,
        "operator_rejection_preserved": operator_rejection_preserved,
        "operator_acceptance_claim": operator_acceptance_claim,
        "served_route_proof_present": "### SERVED ROUTE PROOF" in body_text,
        "visual_proof_present": "### VISUAL PROOF" in body_text,
        "operator_review_present": "### OPERATOR REVIEW" in body_text,
        "body_sha256": hashlib.sha256(body_text.encode("utf-8")).hexdigest() if body_text else "",
    }


def _domain_weaver_latest_operator_rejection_activity_city_authorized_preview_reproof_refs(
    root: Path,
) -> dict[str, Any]:
    proof_rows: list[tuple[float, Path, dict[str, Any]]] = []
    visual_root = root / DOMAIN_WEAVER_ROOT / "visual_smoke"
    if visual_root.is_dir():
        for path in sorted(visual_root.glob("*activity_city_authorized_preview_reproof*/activity_city_authorized_preview_served_route_reproof.json")):
            payload = _read_json_file(path)
            if str(payload.get("schema_id") or "") != (
                "ion.domain_weaver.activity_city_authorized_preview_served_route_reproof.v1"
            ):
                continue
            proof_rows.append((path.stat().st_mtime, path, payload))
    if not proof_rows:
        return {
            "recorded": False,
            "review_required": False,
            "finding": "operator_rejection_activity_city_authorized_preview_reproof_not_recorded",
        }
    _mtime, proof_path, proof = sorted(proof_rows, key=lambda row: (row[0], row[1].name))[-1]
    proof_rel = _rel(root, proof_path)
    proof_dir = proof_path.parent
    manifest_path = proof_dir / "ARTIFACT_MANIFEST.json"
    manifest = _read_json_file(manifest_path)
    manifest_rel = _rel(root, manifest_path) if manifest_path.is_file() else ""
    captures = [row for row in proof.get("captures") or [] if isinstance(row, Mapping)]
    screenshot_paths = _clean_list(
        [
            *[str(row.get("screenshot_path") or "") for row in captures],
            *list(manifest.get("screenshot_paths") or []),
        ]
    )
    acceptance_checks = _as_mapping(proof.get("acceptance_checks"))
    proof_verdict = str(proof.get("proof_verdict") or "")
    proof_verdict_upper = proof_verdict.upper()
    served_route_available = bool(proof.get("served_route_available"))
    served_screenshots_captured = bool(proof.get("served_screenshots_captured"))
    review_required = bool(
        "REVIEW_REQUIRED" in proof_verdict_upper
        or not bool(acceptance_checks.get("comms_or_activity_visible", True))
        or not bool(acceptance_checks.get("left_and_right_rails_visible", True))
        or not bool(acceptance_checks.get("screenshots_nonzero_png", True))
    )
    operator_acceptance_claim = bool(
        proof.get("operator_acceptance_claim")
        or acceptance_checks.get("operator_acceptance_claim")
    )
    operator_rejection_preserved = bool(
        acceptance_checks.get("operator_rejection_preserved")
        or proof.get("operator_rejection_superseded") is False
    )
    selector_checks = _as_mapping(proof.get("selector_checks"))
    viewport_visibility_checks = _as_mapping(proof.get("viewport_visibility_checks"))
    quality_blockers: list[str] = []
    if not served_route_available:
        quality_blockers.append("served_route_unavailable")
    if not served_screenshots_captured:
        quality_blockers.append("served_screenshots_missing_or_invalid")
    if selector_checks.get("event_stream") is False:
        quality_blockers.append("comms_event_stream_selector_absent")
    if viewport_visibility_checks.get("proof_overlay") is False:
        quality_blockers.append("proof_overlay_not_visible_in_all_viewports")
    if viewport_visibility_checks.get("left_rail") is False or viewport_visibility_checks.get("right_rail") is False:
        quality_blockers.append("left_or_right_rail_not_visible_in_all_viewports")
    if review_required and not quality_blockers:
        quality_blockers.append("authorized_preview_visual_review_required")
    local_browser_receipt_path = str(
        proof.get("local_browser_execution_run_receipt_path")
        or manifest.get("local_browser_execution_run_receipt_path")
        or ""
    )
    return {
        "recorded": True,
        "review_required": review_required,
        "finding": "" if review_required else "authorized_preview_reproof_recorded_without_review_blocker",
        "proof_path": proof_rel,
        "artifact_manifest_path": manifest_rel,
        "local_browser_receipt_path": local_browser_receipt_path,
        "screenshot_paths": screenshot_paths,
        "proof_verdict": proof_verdict,
        "served_route_available": served_route_available,
        "served_screenshots_captured": served_screenshots_captured,
        "operator_rejection_preserved": operator_rejection_preserved,
        "operator_acceptance_claim": operator_acceptance_claim,
        "accepted_state_claim": bool(proof.get("accepted_state_claim") or acceptance_checks.get("accepted_state_claim")),
        "quality_blockers": _clean_list(quality_blockers),
        "selector_checks": dict(selector_checks),
        "viewport_visibility_checks": dict(viewport_visibility_checks),
        "body_sha256": hashlib.sha256(json.dumps(proof, sort_keys=True).encode("utf-8")).hexdigest(),
    }


