def _domain_weaver_ui_semantic_redesign_accepted_role_ref(
    root: Path,
    member: Mapping[str, str],
) -> dict[str, Any]:
    agent_role = str(member.get("agent_role") or "")
    safe_role = _safe_id(agent_role)
    prefix = f"codex_req_domain_weaver_ui_semantic_redesign_{safe_role}_20260601_attempt_"
    request_rows: list[tuple[int, float, Path, dict[str, Any], dict[str, Any]]] = []
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        payload = _read_json_file(path)
        return_path = str(payload.get("latest_return_packet_path") or "").strip()
        latest_return = _read_json_file(root / return_path) if return_path else {}
        suffix = path.stem.replace(prefix, "", 1)
        try:
            attempt_index = int(suffix)
        except ValueError:
            attempt_index = 0
        if (
            str(payload.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
            and latest_return.get("accepted_for_carrier_intake") is True
        ):
            request_rows.append((attempt_index, path.stat().st_mtime, path, payload, latest_return))
    if not request_rows:
        return {
            "accepted": False,
            "agent_role": agent_role,
            "lane_id": member.get("lane_id"),
            "work_class": member.get("work_class"),
            "finding": "semantic_redesign_role_return_not_accepted",
        }
    _attempt, _mtime, request_path, request, latest_return = sorted(
        request_rows,
        key=lambda row: (row[0], row[1], row[2].name),
    )[-1]
    request_rel = _rel(root, request_path)
    return_path = str(request.get("latest_return_packet_path") or "").strip()
    run_packet_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = ""
    if task_return_body_path and (root / task_return_body_path).is_file():
        body_text = (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
    return {
        "accepted": True,
        "agent_role": agent_role,
        "lane_id": request.get("lane_id") or member.get("lane_id"),
        "work_class": request.get("work_class") or member.get("work_class"),
        "focus": member.get("focus"),
        "required_output": member.get("required_output"),
        "request_path": request_rel,
        "request_id": request.get("request_id"),
        "return_path": return_path,
        "run_packet_path": run_packet_path,
        "task_return_body_path": task_return_body_path,
        "machine_receipt_path": str(
            latest_return.get("machine_receipt_path") or request.get("latest_task_return_machine_receipt_path") or ""
        ),
        "body_sha256": hashlib.sha256(body_text.encode("utf-8")).hexdigest() if body_text else "",
        "return_contract_sections": request.get("return_contract_sections") or [],
    }


def _domain_weaver_ui_semantic_redesign_fanout_refs(root: Path) -> dict[str, Any]:
    members = _domain_weaver_ui_semantic_redesign_route_members()
    accepted_refs: list[dict[str, Any]] = []
    missing_members: list[str] = []
    accepted_request_paths: set[str] = set()
    for member in members:
        role_ref = _domain_weaver_ui_semantic_redesign_accepted_role_ref(root, member)
        if role_ref.get("accepted"):
            accepted_refs.append(role_ref)
            accepted_request_paths.add(str(role_ref.get("request_path") or ""))
        else:
            missing_members.append(str(member.get("agent_role") or ""))
    duplicate_queued: list[dict[str, Any]] = []
    accepted_roles = {str(row.get("agent_role") or "") for row in accepted_refs}
    for member in members:
        agent_role = str(member.get("agent_role") or "")
        if agent_role not in accepted_roles:
            continue
        safe_role = _safe_id(agent_role)
        prefix = f"codex_req_domain_weaver_ui_semantic_redesign_{safe_role}_20260601_attempt_"
        for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
            request_rel = _rel(root, path)
            if request_rel in accepted_request_paths:
                continue
            payload = _read_json_file(path)
            status = str(payload.get("status") or "")
            if status in {
                "QUEUED_FOR_CODEX_CARRIER",
                "CLAIMED_BY_CODEX_QUEUE_RUNNER",
                "CODEX_QUEUE_RUNNER_WORKER_STARTED",
                "CODEX_CLI_RUNNING",
                "CODEX_QUEUE_RUNNER_FAILED",
                "AI_MOVEMENT_GATE_REJECTED",
            }:
                duplicate_queued.append(
                    {
                        "agent_role": agent_role,
                        "request_path": request_rel,
                        "request_id": payload.get("request_id"),
                        "status": status,
                    }
                )
    context_refs: list[str] = []
    for ref in accepted_refs:
        context_refs.extend(
            [
                str(ref.get("request_path") or ""),
                str(ref.get("return_path") or ""),
                str(ref.get("task_return_body_path") or ""),
                str(ref.get("machine_receipt_path") or ""),
            ]
        )
    fanout_complete = len(accepted_refs) == len(members)
    return {
        "schema_id": "ion.domain_weaver.ui_semantic_redesign_fanout_refs.v0_1",
        "status": "semantic_redesign_fanout_complete" if fanout_complete else "semantic_redesign_fanout_incomplete",
        "fanout_complete": fanout_complete,
        "expected_return_count": len(members),
        "accepted_return_count": len(accepted_refs),
        "missing_route_members": missing_members,
        "accepted_route_returns": accepted_refs,
        "duplicate_queued_request_count": len(duplicate_queued),
        "duplicate_queued_requests": duplicate_queued,
        "context_refs": _clean_list(context_refs),
        "finding": "" if fanout_complete else "semantic_redesign_fanout_missing_accepted_returns",
        "authority": {
            "candidate_projection_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
    }


def _domain_weaver_supersede_duplicate_semantic_redesign_requests(root: Path) -> dict[str, Any]:
    fanout_refs = _domain_weaver_ui_semantic_redesign_fanout_refs(root)
    accepted_by_role = {
        str(row.get("agent_role") or ""): row
        for row in fanout_refs.get("accepted_route_returns") or []
        if isinstance(row, Mapping) and row.get("accepted")
    }
    superseded: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    now = _now()
    for duplicate in fanout_refs.get("duplicate_queued_requests") or []:
        if not isinstance(duplicate, Mapping):
            continue
        request_path = str(duplicate.get("request_path") or "")
        agent_role = str(duplicate.get("agent_role") or "")
        replacement = _as_mapping(accepted_by_role.get(agent_role))
        target_path = root / request_path
        if not target_path.is_file():
            skipped.append(
                {
                    "request_path": request_path,
                    "agent_role": agent_role,
                    "reason": "request_file_missing",
                }
            )
            continue
        payload = _read_json_file(target_path)
        original_status = str(payload.get("status") or "")
        if payload.get("latest_return_packet_path"):
            skipped.append(
                {
                    "request_path": request_path,
                    "agent_role": agent_role,
                    "reason": "duplicate_has_return_packet_path",
                }
            )
            continue
        payload["status"] = "SUPERSEDED_DUPLICATE_AFTER_ACCEPTED_ROLE_RETURN"
        payload["updated_at"] = now
        payload["queue_lifecycle_decision"] = {
            "schema_id": "ion.codex_work_request_queue_lifecycle_decision.v1",
            "created_at": now,
            "decision_source": "domain_weaver_ui_semantic_redesign_fanin_preflight",
            "disposition": "duplicate_semantic_redesign_request_superseded_by_accepted_role_return",
            "request_file_mutation": "status_and_lifecycle_metadata_only",
            "original_status": original_status,
            "superseded": True,
            "effective_replacement_accepted": True,
            "replacement_request_id": replacement.get("request_id"),
            "replacement_request_path": replacement.get("request_path"),
            "replacement_return_packet_path": replacement.get("return_path"),
            "replacement_machine_receipt_path": replacement.get("machine_receipt_path"),
            "operator_magic_string_required": False,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        }
        target_path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        superseded.append(
            {
                "request_path": request_path,
                "request_id": payload.get("request_id"),
                "agent_role": agent_role,
                "original_status": original_status,
                "replacement_request_path": replacement.get("request_path"),
                "replacement_return_path": replacement.get("return_path"),
            }
        )
    queue_refresh = _refresh_codex_work_queue_and_lane_projection(root)
    receipt = {
        "schema_id": "ion.domain_weaver.ui_semantic_redesign_duplicate_supersession_receipt.v0_1",
        "created_at": now,
        "status": "semantic_duplicate_requests_superseded" if superseded else "semantic_duplicate_requests_none",
        "mutation_scope": "duplicate_semantic_redesign_work_request_status_only",
        "superseded_count": len(superseded),
        "skipped_count": len(skipped),
        "superseded_requests": superseded,
        "skipped_requests": skipped,
        "queue_projection_refresh": queue_refresh,
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    receipt_path = root / DOMAIN_WEAVER_RECEIPT_DIR / f"{_stamp()}_domain_weaver_ui_semantic_duplicate_supersession.json"
    receipt_path.parent.mkdir(parents=True, exist_ok=True)
    receipt_path.write_text(json.dumps(receipt, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return {
        **receipt,
        "receipt_path": _rel(root, receipt_path),
    }


def _domain_weaver_ui_semantic_redesign_fanin_attempt_index(root: Path) -> int:
    prefix = "codex_req_domain_weaver_ui_semantic_redesign_fanin_settlement_20260601_attempt_"
    latest_index = 0
    reusable_index = 0
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        suffix = path.stem.replace(prefix, "", 1)
        try:
            index = int(suffix)
        except ValueError:
            continue
        latest_index = max(latest_index, index)
        status = str(_read_json_file(path).get("status") or "")
        if status in {
            "QUEUED_FOR_CODEX_CARRIER",
            "CLAIMED_BY_CODEX_QUEUE_RUNNER",
            "CODEX_QUEUE_RUNNER_WORKER_STARTED",
            "CODEX_CLI_RUNNING",
            "CODEX_QUEUE_RUNNER_FAILED",
            "AI_MOVEMENT_GATE_REJECTED",
        }:
            reusable_index = max(reusable_index, index)
    return reusable_index or latest_index + 1


def _domain_weaver_ui_semantic_redesign_fanin_work_request_template(
    root: Path,
    projection: Mapping[str, Any],
    *,
    duplicate_supersession: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    ui_development = _as_mapping(projection.get("ui_development"))
    packet = _as_mapping(ui_development.get("next_packet"))
    fanout_refs = _as_mapping(
        packet.get("source_semantic_redesign_fanout") or ui_development.get("ui_semantic_redesign_fanout")
    )
    visual_review = _as_mapping(packet.get("source_visual_stewardship_review") or ui_development.get("ui_visual_stewardship_review"))
    packet_id = str(
        packet.get("packet_id")
        or "PCKT-DOMAIN-WEAVER-UI-SEMANTIC-REDESIGN-FANIN-SETTLEMENT-20260601-ATTEMPT-001"
    )
    attempt_index = _domain_weaver_ui_semantic_redesign_fanin_attempt_index(root)
    request_id = f"codex_req_domain_weaver_ui_semantic_redesign_fanin_settlement_20260601_attempt_{attempt_index:03d}"
    request_path = CODEX_WORK_REQUESTS_DIR / f"{request_id}.json"
