def _domain_weaver_latest_ui_semantic_redesign_fanin_refs(root: Path) -> dict[str, Any]:
    prefix = "codex_req_domain_weaver_ui_semantic_redesign_fanin_settlement_20260601_attempt_"
    request_rows: list[tuple[int, float, Path, dict[str, Any], dict[str, Any]]] = []
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        payload = _read_json_file(path)
        return_path = str(payload.get("latest_return_packet_path") or "").strip()
        latest_return = _read_json_file(root / return_path) if return_path else {}
        suffix = path.stem.replace(prefix, "", 1)
        try:
            attempt_index = int(suffix)
        except ValueError:
            attempt_index = 0
        if (
            str(payload.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
            and latest_return.get("accepted_for_carrier_intake") is True
        ):
            request_rows.append((attempt_index, path.stat().st_mtime, path, payload, latest_return))
    if not request_rows:
        return {
            "accepted": False,
            "finding": "ui_semantic_redesign_fanin_settlement_not_accepted",
        }
    _attempt, _mtime, request_path, request, latest_return = sorted(
        request_rows,
        key=lambda row: (row[0], row[1], row[2].name),
    )[-1]
    request_rel = _rel(root, request_path)
    return_path = str(request.get("latest_return_packet_path") or "").strip()
    run_packet_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = ""
    if task_return_body_path and (root / task_return_body_path).is_file():
        body_text = (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
    recommended_packet_id = ""
    match = re.search(
        r"`?(PCKT-DOMAIN-WEAVER-UI-SEMANTIC-REDESIGN-MOCK-PROOF-STEWARDSHIP-NEMESIS-GATE-[A-Z0-9-]+)`?",
        body_text,
    )
    if match:
        recommended_packet_id = match.group(1)
    run_reconciliation_receipt_path = ""
    for receipt_path in sorted((root / DOMAIN_WEAVER_RECEIPT_DIR).glob("*semantic_fanin_run_wrapper_reconciled.json")):
        receipt = _read_json_file(receipt_path)
        if str(receipt.get("run_path") or "") == run_packet_path:
            run_reconciliation_receipt_path = _rel(root, receipt_path)
    return {
        "accepted": True,
        "request_path": request_rel,
        "request_id": request.get("request_id"),
        "return_path": return_path,
        "run_packet_path": run_packet_path,
        "task_return_body_path": task_return_body_path,
        "machine_receipt_path": str(
            latest_return.get("machine_receipt_path") or request.get("latest_task_return_machine_receipt_path") or ""
        ),
        "run_reconciliation_receipt_path": run_reconciliation_receipt_path,
        "recommended_next_packet_id": recommended_packet_id,
        "not_implementation_ready": "NOT_IMPLEMENTATION_READY" in body_text,
        "visual_proposal_present": "### VISUAL PROPOSAL" in body_text,
        "implementation_gate_present": "### IMPLEMENTATION GATE" in body_text,
        "operator_rejection_preserved": (
            "operator_rejection_superseded=false" in body_text
            or "operator rejection" in body_text.lower()
        ),
        "body_sha256": hashlib.sha256(body_text.encode("utf-8")).hexdigest() if body_text else "",
    }


