def _domain_weaver_latest_ui_activity_city_candidate_implementation_refs(root: Path) -> dict[str, Any]:
    prefix = "codex_req_domain_weaver_ui_semantic_redesign_candidate_implementation_activity_city_map_20260601_attempt_"
    request_rows: list[tuple[int, float, Path, dict[str, Any], dict[str, Any]]] = []
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        payload = _read_json_file(path)
        return_path = str(payload.get("latest_return_packet_path") or "").strip()
        latest_return = _read_json_file(root / return_path) if return_path else {}
        suffix = path.stem.replace(prefix, "", 1)
        try:
            attempt_index = int(suffix)
        except ValueError:
            attempt_index = 0
        if (
            str(payload.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
            and latest_return.get("accepted_for_carrier_intake") is True
        ):
            request_rows.append((attempt_index, path.stat().st_mtime, path, payload, latest_return))
    if not request_rows:
        return {
            "accepted": False,
            "proof_recovery_ready": False,
            "visual_proof_blocked": False,
            "finding": "ui_activity_city_candidate_implementation_not_accepted",
        }
    _attempt, _mtime, request_path, request, latest_return = sorted(
        request_rows,
        key=lambda row: (row[0], row[1], row[2].name),
    )[-1]
    request_rel = _rel(root, request_path)
    return_path = str(request.get("latest_return_packet_path") or "").strip()
    run_packet_path = ""
    run_status = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_status = str(run.get("status") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = (
        (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
        if task_return_body_path and (root / task_return_body_path).is_file()
        else ""
    )
    recommended_packet_id = ""
    match = re.search(
        r"`?(PCKT-DOMAIN-WEAVER-UI-ACTIVITY-CITY-CANDIDATE-PATCH-FANIN-STEWARDSHIP-NEMESIS-VISUAL-PROOF-RECOVERY-[A-Z0-9-]+)`?",
        body_text,
    )
    if match:
        recommended_packet_id = match.group(1)
    body_lower = body_text.lower()
    body_upper = body_text.upper()
    visual_proof_blocked = "visual_proof_verdict: blocked" in body_lower or "VISUAL_PROOF_VERDICT: BLOCKED" in body_upper
    timeout_recovered = "CODEX_CLI_TIMEOUT" in body_text or run_status == "CODEX_CLI_TIMEOUT"
    no_quality_settlement = (
        "DO_NOT_SETTLE_UI_QUALITY" in body_text
        or "REJECT_ACCEPTED_STATE_AND_OPERATOR_USABILITY_CLAIMS" in body_text
        or "not accepted as ui quality settlement" in body_lower
    )
    blocked_but_preserved = "BLOCKED_BUT_PRESERVED" in body_text
    proof_recovery_ready = bool(
        recommended_packet_id
        and blocked_but_preserved
        and visual_proof_blocked
        and no_quality_settlement
    )
    proof_artifact_paths = _clean_list(
        re.findall(
            r"`?(ION/05_context/current/domain_weaver/visual_smoke/[A-Za-z0-9_./-]+json)`?",
            body_text,
        )
    )
    candidate_source_paths = _clean_list(
        [
            DOMAIN_WEAVER_COCKPIT_PANEL_PATH.as_posix(),
            DOMAIN_WEAVER_COCKPIT_RUNTIME_CSS_PATH.as_posix(),
            "ION/08_ui/joc_cockpit_shell/dist/index.html",
            *re.findall(r"`?(ION/08_ui/joc_cockpit_shell/dist/assets/[A-Za-z0-9_.-]+)`?", body_text),
        ]
    )
    return {
        "accepted": True,
        "proof_recovery_ready": proof_recovery_ready,
        "finding": "" if proof_recovery_ready else "accepted_candidate_implementation_missing_visual_recovery_gate",
        "request_path": request_rel,
        "request_id": request.get("request_id"),
        "return_path": return_path,
        "run_packet_path": run_packet_path,
        "run_status": run_status,
        "task_return_body_path": task_return_body_path,
        "machine_receipt_path": str(
            latest_return.get("machine_receipt_path") or request.get("latest_task_return_machine_receipt_path") or ""
        ),
        "recommended_next_packet_id": recommended_packet_id,
        "result_verdict": "BLOCKED_BUT_PRESERVED" if blocked_but_preserved else "",
        "visual_proof_blocked": visual_proof_blocked,
        "timeout_recovered": timeout_recovered,
        "no_quality_settlement": no_quality_settlement,
        "operator_rejection_preserved": "operator rejection" in body_lower
        and any(token in body_lower for token in ("preserved", "remains active", "not superseded")),
        "model_endpoint_degraded": "model endpoint" in body_lower
        and any(token in body_lower for token in ("timeout", "degraded", "times out")),
        "proof_artifact_paths": proof_artifact_paths,
        "candidate_source_paths": candidate_source_paths,
        "body_sha256": hashlib.sha256(body_text.encode("utf-8")).hexdigest() if body_text else "",
    }


def _domain_weaver_ui_activity_city_candidate_patch_recovery_attempt_index(root: Path) -> int:
    prefix = (
        "codex_req_domain_weaver_ui_activity_city_candidate_patch_fanin_stewardship_nemesis_"
        "visual_proof_recovery_20260601_attempt_"
    )
    latest_index = 0
    reusable_index = 0
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        suffix = path.stem.replace(prefix, "", 1)
        try:
            index = int(suffix)
        except ValueError:
            continue
        latest_index = max(latest_index, index)
        status = str(_read_json_file(path).get("status") or "")
        if status in {
            "QUEUED_FOR_CODEX_CARRIER",
            "CLAIMED_BY_CODEX_QUEUE_RUNNER",
            "CODEX_QUEUE_RUNNER_WORKER_STARTED",
            "CODEX_CLI_RUNNING",
            "CODEX_QUEUE_RUNNER_FAILED",
            "AI_MOVEMENT_GATE_REJECTED",
        }:
            reusable_index = max(reusable_index, index)
    return reusable_index or latest_index + 1


