def _domain_weaver_latest_ui_activity_city_visual_proof_recovery_refs(root: Path) -> dict[str, Any]:
    prefix = "codex_req_domain_weaver_ui_activity_city_visual_proof_recovery_chromium_only_20260601_attempt_"
    request_rows: list[tuple[int, float, Path, dict[str, Any], dict[str, Any]]] = []
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        payload = _read_json_file(path)
        return_path = str(payload.get("latest_return_packet_path") or "").strip()
        latest_return = _read_json_file(root / return_path) if return_path else {}
        suffix = path.stem.replace(prefix, "", 1)
        try:
            attempt_index = int(suffix)
        except ValueError:
            attempt_index = 0
        if (
            str(payload.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
            and latest_return.get("accepted_for_carrier_intake") is True
        ):
            request_rows.append((attempt_index, path.stat().st_mtime, path, payload, latest_return))
    if not request_rows:
        return {
            "accepted": False,
            "ui_revision_required": False,
            "visual_artifacts_captured": False,
            "operator_usable": False,
            "finding": "ui_activity_city_visual_proof_recovery_not_accepted",
        }
    _attempt, _mtime, request_path, request, latest_return = sorted(
        request_rows,
        key=lambda row: (row[0], row[1], row[2].name),
    )[-1]
    request_rel = _rel(root, request_path)
    return_path = str(request.get("latest_return_packet_path") or "").strip()
    run_packet_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = (
        (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
        if task_return_body_path and (root / task_return_body_path).is_file()
        else ""
    )
    body_lower = body_text.lower()
    recommended_packet_id = ""
    match = re.search(
        (
            r"`?(PCKT-DOMAIN-WEAVER-UI-ACTIVITY-CITY-RESPONSIVE-VISIBILITY-AND-MODEL-ENDPOINT-"
            r"REPAIR-[A-Z0-9-]+)`?"
        ),
        body_text,
    )
    if match:
        recommended_packet_id = match.group(1)
    revise_required = (
        "revise_required_candidate_not_operator_usable" in body_lower
        or "keep_revise_revert: `revise`" in body_lower
        or "keep_revise_revert: revise" in body_lower
        or "revise required" in body_lower
    )
    all_viewports_captured = bool(
        re.search(r"all_requested_viewports_captured\s*:\s*`?true`?", body_lower)
    )
    zero_byte_count_zero = bool(re.search(r"zero_byte_screenshot_count\s*:\s*`?0`?", body_lower))
    proof_manifest_matches = _clean_list(
        re.findall(
            (
                r"`?(ION/05_context/current/domain_weaver/visual_smoke/[A-Za-z0-9_./-]+"
                r"activity_city_chromium_visual_proof\.json)`?"
            ),
            body_text,
        )
    )
    context_path_audit_matches = _clean_list(
        re.findall(
            (
                r"`?(ION/05_context/current/domain_weaver/visual_smoke/[A-Za-z0-9_./-]+"
                r"activity_city_chromium_context_path_audit\.json)`?"
            ),
            body_text,
        )
    )
    screenshot_paths = _clean_list(
        re.findall(
            r"`?(ION/05_context/current/domain_weaver/visual_smoke/[A-Za-z0-9_./-]+\.png)`?",
            body_text,
        )
    )
    proof_manifest_path = proof_manifest_matches[0] if proof_manifest_matches else ""
    context_path_audit_path = context_path_audit_matches[0] if context_path_audit_matches else ""
    manifest = _read_json_file(root / proof_manifest_path) if proof_manifest_path else {}
    manifest_summary = _as_mapping(manifest.get("summary"))
    if "all_requested_viewports_captured" in manifest_summary:
        all_viewports_captured = bool(manifest_summary.get("all_requested_viewports_captured"))
    if "zero_byte_screenshot_count" in manifest_summary:
        try:
            zero_byte_count_zero = int(manifest_summary.get("zero_byte_screenshot_count") or 0) == 0
        except (TypeError, ValueError):
            zero_byte_count_zero = False
    if not screenshot_paths:
        screenshot_paths = _clean_list(
            str(row.get("screenshot_path") or "")
            for row in manifest.get("captures") or []
            if isinstance(row, Mapping)
        )
    existing_screenshot_paths = [path for path in screenshot_paths if (root / path).is_file()]
    proof_manifest_exists = bool(proof_manifest_path and (root / proof_manifest_path).is_file())
    context_path_audit_exists = bool(context_path_audit_path and (root / context_path_audit_path).is_file())
    visual_artifacts_captured = bool(
        all_viewports_captured
        and zero_byte_count_zero
        and proof_manifest_exists
        and context_path_audit_exists
        and len(screenshot_paths) >= 4
        and len(existing_screenshot_paths) == len(screenshot_paths)
    )
    operator_usable = not revise_required and "operator_usable: `true`" in body_lower
    ui_revision_required = bool(recommended_packet_id and revise_required and visual_artifacts_captured)
    return {
        "accepted": True,
        "ui_revision_required": ui_revision_required,
        "visual_artifacts_captured": visual_artifacts_captured,
        "operator_usable": operator_usable,
        "finding": "" if ui_revision_required else "accepted_visual_proof_missing_responsive_repair_gate",
        "request_path": request_rel,
        "request_id": request.get("request_id"),
        "return_path": return_path,
        "run_packet_path": run_packet_path,
        "task_return_body_path": task_return_body_path,
        "machine_receipt_path": str(
            latest_return.get("machine_receipt_path") or request.get("latest_task_return_machine_receipt_path") or ""
        ),
        "recommended_next_packet_id": recommended_packet_id,
        "result_verdict": "revise_required_candidate_not_operator_usable" if revise_required else "",
        "keep_revise_revert": "revise" if revise_required else "",
        "all_requested_viewports_captured": all_viewports_captured,
        "zero_byte_screenshot_count_zero": zero_byte_count_zero,
        "proof_manifest_path": proof_manifest_path,
        "context_path_audit_path": context_path_audit_path,
        "screenshot_paths": screenshot_paths,
        "missing_screenshot_paths": sorted(set(screenshot_paths) - set(existing_screenshot_paths)),
        "selector_visibility_failure_count": len(_as_mapping(manifest_summary.get("selector_visibility_by_viewport"))),
        "operator_rejection_preserved": "operator rejection" in body_lower
        and any(token in body_lower for token in ("preserved", "remains active", "not superseded")),
        "model_endpoint_degraded": "model" in body_lower and any(token in body_lower for token in ("degraded", "endpoint")),
        "body_sha256": hashlib.sha256(body_text.encode("utf-8")).hexdigest() if body_text else "",
    }


