def _domain_weaver_start_repin_plan_nemesis_reaudit(
    root: Path,
    *,
    semantic_repin_plan: Mapping[str, Any],
    packet_id: str | None = None,
) -> dict[str, Any]:
    template = _domain_weaver_repin_nemesis_reaudit_request_template(
        semantic_repin_plan=semantic_repin_plan,
        packet_id=packet_id,
    )
    request_rel = str(template["packet_path"])
    target_path = root / request_rel
    existing = _read_json_file(target_path)
    created_at = _now()
    request_payload = dict(existing) if existing else dict(template)
    if existing:
        for key in (
            "objective",
            "objective_sha256",
            "dedupe_key",
            "idempotency_key",
            "idempotency_source",
            "requested_by",
            "work_class",
            "lane_id",
            "risk_level",
            "route_family",
            "request_kind",
            "target_root_id",
            "movement_class",
            "requested_model",
            "requested_reasoning_effort",
            "model_override_reason",
            "codex_model_override",
            "ai_movement_root_envelope",
            "requested_authority",
            "return_contract_sections",
            "required_context_reads",
            "domain_weaver_repin_reaudit",
            "production_authority",
            "live_execution_authority",
            "accepted_state_authority",
            "secrets_authority",
        ):
            request_payload[key] = template[key]
        if str(request_payload.get("status") or "") not in {
            "CODEX_CLI_RUNNING",
            "RETURN_RECORDED_PROOF_ACCEPTED",
        }:
            request_payload["status"] = "QUEUED_FOR_CODEX_CARRIER"
    request_payload.setdefault("created_at", created_at)
    request_payload["updated_at"] = created_at
    target_path.parent.mkdir(parents=True, exist_ok=True)
    target_path.write_text(json.dumps(request_payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    queue_refresh: dict[str, Any]
    try:
        from .ion_chatgpt_browser_mcp_connector_contract import _write_codex_work_queue_index

        queue = _write_codex_work_queue_index(root)
        queue_refresh = {
            "ok": True,
            "codex_work_queue_path": CODEX_WORK_QUEUE_PATH.as_posix(),
            "request_count": queue.get("request_count"),
        }
    except Exception as exc:  # pragma: no cover - best-effort connector index refresh.
        queue_refresh = {"ok": False, "error": type(exc).__name__, "detail": str(exc)}
    worker_started = False
    start_result: dict[str, Any]
    worker_start_context_gate: dict[str, Any] = {}
    if str(request_payload.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED":
        start_result = {
            "ok": False,
            "finding": "repinned_reaudit_already_returned",
            "worker_started": False,
        }
    elif str(request_payload.get("status") or "") == "CODEX_CLI_RUNNING":
        start_result = {
            "ok": False,
            "finding": "repinned_reaudit_already_running",
            "worker_started": False,
        }
    else:
        worker_start_context_gate = _domain_weaver_worker_start_context_gate(
            root,
            lane_id=str(request_payload.get("lane_id") or "").strip() or None,
        )
        if not worker_start_context_gate.get("worker_start_allowed"):
            start_result = _domain_weaver_worker_start_context_block_result(
                worker_start_context_gate,
                request_path=request_rel,
            )
        else:
            try:
                from .ion_codex_queue_runner import process_codex_queue_once

                raw_start = process_codex_queue_once(root, request_path=request_rel, start=True, background=True)
                run = _as_mapping(raw_start.get("run"))
                worker_started = bool(
                    raw_start.get("ok") and raw_start.get("result") == "CODEX_QUEUE_RUNNER_WORKER_STARTED"
                )
                start_result = {
                    "ok": bool(raw_start.get("ok")),
                    "result": raw_start.get("result"),
                    "finding": raw_start.get("finding"),
                    "request_path": request_rel,
                    "run_packet_path": run.get("run_packet_path"),
                    "worker_pid": run.get("pid"),
                    "worker_started": worker_started,
                }
            except Exception as exc:  # pragma: no cover - live runner start is environment-dependent.
                start_result = {
                    "ok": False,
                    "finding": "worker_start_exception",
                    "error": type(exc).__name__,
                    "detail": str(exc),
                    "request_path": request_rel,
                    "worker_started": False,
                }
    return {
        "schema_id": "ion.domain_weaver.repinned_nemesis_reaudit_start.v0_1",
        "ok": worker_started,
        "created_at": created_at,
        "request_path": request_rel,
        "request_id": template["request_id"],
        "run_packet_path": start_result.get("run_packet_path") or "",
        "codex_work_queue_path": CODEX_WORK_QUEUE_PATH.as_posix() if queue_refresh.get("ok") else "",
        "work_request_status_before_start": existing.get("status") if existing else "",
        "codex_work_queue_refresh": queue_refresh,
        "worker_start_context_gate": worker_start_context_gate,
        "worker_start_result": start_result,
        "summary": {
            "request_materialized": True,
            "worker_start_status": start_result.get("worker_start_status")
            or start_result.get("result")
            or start_result.get("finding"),
            "worker_started_count": 1 if worker_started else 0,
            "worker_start_context_allowed": (
                bool(worker_start_context_gate.get("worker_start_allowed")) if worker_start_context_gate else None
            ),
            "worker_start_context_blocked": start_result.get("finding") == "context_active_resolver_blocked",
            "repin_record_count": _as_mapping(semantic_repin_plan.get("summary")).get("repin_record_count", 0),
            "current_context_pin_count": _as_mapping(semantic_repin_plan.get("summary")).get(
                "current_context_pin_count", 0
            ),
            "reauditable_return_count": _as_mapping(semantic_repin_plan.get("summary")).get(
                "reauditable_return_count", 0
            ),
        },
        "authority": {
            "candidate_reaudit_request_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }


def _domain_weaver_task_body_from_return_packet(return_packet: Mapping[str, Any]) -> str:
    template_result = _as_mapping(return_packet.get("template_action_proof_result"))
    for item in template_result.get("touched_paths") or []:
        rel = str(item or "")
        if rel.endswith("/task_return_body.md") or rel.endswith("task_return_body.md"):
            return rel
    return str(return_packet.get("task_return_body_path") or "")


def _domain_weaver_context_pin(root: Path, rel_path: str) -> dict[str, Any]:
    path = root / rel_path
    return {
        "path": rel_path,
        "exists": path.is_file(),
        "sha256_current": _sha256_file(path) if path.is_file() else "",
    }


def _domain_weaver_20260601b_classification_rows(source_body_text: str = "") -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    for line in source_body_text.splitlines():
        stripped = line.strip()
        if not stripped.startswith("| codex_req_domain_weaver_"):
            continue
        cells = [cell.strip() for cell in stripped.strip("|").split("|")]
        if len(cells) < 2:
            continue
        request_id = cells[0]
        classification = cells[1]
        if not request_id.startswith("codex_req_domain_weaver_"):
            continue
        rows.append(
            {
                "request_id": request_id,
                "classification": classification,
                "proof": cells[2] if len(cells) > 2 else "",
            }
        )
    return rows


def _domain_weaver_20260601b_reissue_source_request_ids(source_body_text: str = "") -> list[str]:
    parsed = [
        row["request_id"]
        for row in _domain_weaver_20260601b_classification_rows(source_body_text)
        if row.get("classification") == "reissue_required"
    ]
    if parsed:
        return _unique_paths(parsed)
    return [
        "codex_req_domain_weaver_approval_fanout_act_req_frontend_work_surface_architect",
        "codex_req_domain_weaver_approval_fanout_fission_domain_archaeology_drift_watch_canon_registry_candidate",
    ]


def _domain_weaver_20260601b_context_rebaseline_plan(root: Path, *, materialize: bool = False) -> dict[str, Any]:
    packet_id = "PCKT-DOMAIN-WEAVER-LIVE-FANIN-20260601B-CONTEXT-REBASELINE-AND-TWO-REISSUE"
    source_reaudit_request_path = (
        CODEX_WORK_REQUESTS_DIR
        / "codex_req_domain_weaver_live_fanin_repin_plan_stabilize_projection_and_reaudit_20260601b.json"
    ).as_posix()
    source_reaudit_request = _read_json_file(root / source_reaudit_request_path)
    source_reaudit_return_path = str(source_reaudit_request.get("latest_return_packet_path") or "")
    source_reaudit_return = _read_json_file(root / source_reaudit_return_path) if source_reaudit_return_path else {}
    source_reaudit_body_path = _domain_weaver_task_body_from_return_packet(source_reaudit_return)
    source_body_text = ""
    if source_reaudit_body_path and (root / source_reaudit_body_path).is_file():
        source_body_text = (root / source_reaudit_body_path).read_text(encoding="utf-8", errors="replace")
    classification_counts = {
        "semantic_clean_after_repin": source_body_text.count("| semantic_clean_after_repin |"),
        "reissue_required": source_body_text.count("| reissue_required |"),
        "supersede_required": source_body_text.count("| supersede_required |"),
        "still_blocked": source_body_text.count("| still_blocked |"),
    }
    classification_records = _domain_weaver_20260601b_classification_rows(source_body_text)
    reissue_records: list[dict[str, Any]] = []
    blockers: list[dict[str, Any]] = []
    for request_id in _domain_weaver_20260601b_reissue_source_request_ids(source_body_text):
        source_request_path = (CODEX_WORK_REQUESTS_DIR / f"{_safe_id(request_id)}.json").as_posix()
        source_request = _read_json_file(root / source_request_path)
        latest_return_packet_path = str(source_request.get("latest_return_packet_path") or "")
        latest_return_packet = _read_json_file(root / latest_return_packet_path) if latest_return_packet_path else {}
        task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return_packet)
        if not source_request:
            blockers.append(
                {"code": "REISSUE_SOURCE_REQUEST_MISSING", "request_id": request_id, "severity": "critical"}
            )
        if not latest_return_packet_path or not latest_return_packet:
            blockers.append(
                {"code": "REISSUE_SOURCE_RETURN_MISSING", "request_id": request_id, "severity": "critical"}
            )
        reissue_records.append(
            {
                "source_request_id": request_id,
                "source_request_path": source_request_path,
                "source_latest_return_packet_path": latest_return_packet_path,
                "source_task_return_body_path": task_return_body_path,
                "source_lane_id": source_request.get("lane_id"),
                "source_work_class": source_request.get("work_class"),
                "classification": "reissue_required",
                "reissue_reason": (
                    "20260601B Nemesis classification requires this accepted return to be rerun against "
                    "current pinned context before semantic settlement can advance."
                ),
            }
        )
    rebaseline_context_paths = [
        source_reaudit_request_path,
        source_reaudit_return_path,
        source_reaudit_body_path,
        DOMAIN_WEAVER_LIVE_FANIN_SEMANTIC_REPIN_PLAN_PATH.as_posix(),
        DOMAIN_WEAVER_LIVE_FANIN_SEMANTIC_SETTLEMENT_PATH.as_posix(),
        DOMAIN_WEAVER_LIVE_FANIN_SETTLEMENT_PATH.as_posix(),
        DOMAIN_WEAVER_LIVE_RETURN_MONITOR_PATH.as_posix(),
        DOMAIN_WEAVER_PROJECTION_PATH.as_posix(),
        CODEX_WORK_QUEUE_PATH.as_posix(),
        ACTIVE_CARRIER_MESSAGE_QUEUE_PATH.as_posix(),
        "ION/04_packages/kernel/ion_domain_weaver.py",
        "ION/04_packages/kernel/ion_codex_queue_runner.py",
        "ION/04_packages/kernel/ion_carrier_task_return.py",
    ]
    rebaseline_context_paths.extend(row["source_request_path"] for row in reissue_records)
    rebaseline_context_paths.extend(row["source_latest_return_packet_path"] for row in reissue_records)
    rebaseline_context_paths.extend(row["source_task_return_body_path"] for row in reissue_records)
    rebaseline_context_pins = [
        _domain_weaver_context_pin(root, rel)
        for rel in _unique_paths([path for path in rebaseline_context_paths if path])
    ]
    accepted_reaudit = bool(
        source_reaudit_request.get("status") == "RETURN_RECORDED_PROOF_ACCEPTED"
        and source_reaudit_return.get("accepted_for_carrier_intake") is True
    )
    if not accepted_reaudit:
        blockers.append(
            {
                "code": "SOURCE_20260601B_REAUDIT_NOT_ACCEPTED",
                "severity": "critical",
                "detail": "The 20260601B Nemesis return must be accepted before reissue queueing.",
            }
        )
    missing_pin_count = sum(1 for row in rebaseline_context_pins if not row.get("exists"))
    if missing_pin_count:
        blockers.append(
            {
                "code": "REBASELINE_CONTEXT_PIN_MISSING",
                "severity": "critical",
                "missing_count": missing_pin_count,
            }
        )
    plan_ready = accepted_reaudit and not blockers and len(reissue_records) == 2
    plan = {
        "schema_id": "ion.domain_weaver.live_fanin_20260601b_context_rebaseline_reissue_plan.v0_1_candidate",
        "created_at": _now(),
        "status": "context_rebaseline_reissue_plan_ready" if plan_ready else "context_rebaseline_reissue_plan_blocked",
        "packet_id": packet_id,
        "source_reaudit_request_path": source_reaudit_request_path,
        "source_reaudit_return_packet_path": source_reaudit_return_path,
        "source_reaudit_task_return_body_path": source_reaudit_body_path,
        "classification_counts": classification_counts,
        "classification_records": classification_records,
        "reissue_records": reissue_records,
        "rebaseline_context_pins": rebaseline_context_pins,
        "blockers": blockers,
        "summary": {
            "context_rebaseline_ready": plan_ready,
            "source_reaudit_accepted": accepted_reaudit,
            "rebaseline_context_pin_count": len(rebaseline_context_pins),
            "missing_rebaseline_context_pin_count": missing_pin_count,
            "semantic_clean_after_repin_count": classification_counts["semantic_clean_after_repin"],
            "reissue_required_count": len(reissue_records),
            "supersede_required_count": classification_counts["supersede_required"],
            "still_blocked_count": classification_counts["still_blocked"],
            "blocker_count": len(blockers),
        },
        "authority": {
            "candidate_rebaseline_reissue_plan_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    if materialize:
        path = root / DOMAIN_WEAVER_LIVE_FANIN_20260601B_CONTEXT_REBASELINE_PLAN_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(plan, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        plan["plan_path"] = DOMAIN_WEAVER_LIVE_FANIN_20260601B_CONTEXT_REBASELINE_PLAN_PATH.as_posix()
        plan["materialized_paths"] = [
            DOMAIN_WEAVER_LIVE_FANIN_20260601B_CONTEXT_REBASELINE_PLAN_PATH.as_posix()
        ]
    else:
        plan["plan_path"] = DOMAIN_WEAVER_LIVE_FANIN_20260601B_CONTEXT_REBASELINE_PLAN_PATH.as_posix()
        plan["materialized_paths"] = []
    return plan


