def _domain_weaver_latest_recursive_cycle_readiness_result(
    root: Path,
    *,
    materialize: bool = False,
) -> dict[str, Any]:
    request_id = "codex_req_domain_weaver_recursive_cycle_fission_reflex_binding_readiness_20260602_attempt_001"
    request_path = CODEX_WORK_REQUESTS_DIR / f"{request_id}.json"
    request_rel = request_path.as_posix()
    request = _read_json_file(root / request_path)
    return_path = str(request.get("latest_return_packet_path") or "").strip()
    latest_return = _read_json_file(root / return_path) if return_path else {}
    accepted = bool(
        request.get("status") == "RETURN_RECORDED_PROOF_ACCEPTED"
        and latest_return.get("accepted_for_carrier_intake") is True
    )
    run_packet_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = ""
    if task_return_body_path and (root / task_return_body_path).is_file():
        body_text = (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
    body_lower = body_text.lower()
    recommended_packet_id = ""
    match = re.search(
        r"`?(PCKT-DOMAIN-WEAVER-FISSION-REFLEX-BINDING-FANOUT-TEMPLATE-MATERIALIZATION-[A-Z0-9-]+)`?",
        body_text,
    )
    if match:
        recommended_packet_id = match.group(1)
    template_packet_ids = _unique_paths(
        re.findall(
            r"PCKT-DOMAIN-WEAVER-(?:FISSION-EXECUTION-GATES|DOMAIN-REFLEX-NETWORK-RULESET|SPECIALIST-BINDING-MATRIX)-[A-Z0-9-]+",
            body_text,
        )
    )
    result_ready = bool(accepted and recommended_packet_id and len(template_packet_ids) >= 3)
    next_packet = (
        {
            "packet_id": recommended_packet_id,
            "lane_id": "architecture_lane",
            "work_class": "queue_materialization",
            "recommended_worker": "role.steward",
            "objective": (
                "Materialize the three candidate-only fission/reflex/binding fanout templates from the accepted "
                "readiness result through Domain Weaver queue owners. Queue only; do not start the three fanout "
                "workers until a later start gate."
            ),
        }
        if result_ready
        else {}
    )
    result = {
        "schema_id": "ion.domain_weaver.recursive_cycle_readiness_result.v0_1_candidate",
        "generated_at": _now(),
        "accepted": accepted,
        "result_ready": result_ready,
        "status": "recursive_cycle_readiness_result_ready" if result_ready else "recursive_cycle_readiness_result_missing",
        "source_request_path": request_rel,
        "source_return_packet_path": return_path,
        "source_run_packet_path": run_packet_path,
        "source_task_return_body_path": task_return_body_path,
        "recommended_next_packet": next_packet,
        "recommended_next_packet_id": recommended_packet_id,
        "template_packet_ids": template_packet_ids,
        "live_start_blocked": "live_start_blocked" in body_lower or "no live workers started" in body_lower,
        "queue_only_required": "no live workers started" in body_lower or "do not start workers" in body_lower,
        "summary": {
            "result_ready": result_ready,
            "accepted_return": accepted,
            "recommended_next_packet_id": recommended_packet_id,
            "template_packet_count": len(template_packet_ids),
            "queue_only_required": "no live workers started" in body_lower or "do not start workers" in body_lower,
            "body_sha256": hashlib.sha256(body_text.encode("utf-8")).hexdigest() if body_text else "",
        },
        "authority": {
            "candidate_result_projection_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    if materialize:
        path = root / DOMAIN_WEAVER_RECURSIVE_CYCLE_READINESS_RESULT_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        result["result_path"] = DOMAIN_WEAVER_RECURSIVE_CYCLE_READINESS_RESULT_PATH.as_posix()
        result["materialized_paths"] = [DOMAIN_WEAVER_RECURSIVE_CYCLE_READINESS_RESULT_PATH.as_posix()]
    else:
        result["result_path"] = DOMAIN_WEAVER_RECURSIVE_CYCLE_READINESS_RESULT_PATH.as_posix()
        result["materialized_paths"] = []
    return result


