def _domain_weaver_fission_reflex_binding_materialization_state(root: Path) -> dict[str, Any]:
    ledger = _read_json_file(root / DOMAIN_WEAVER_FISSION_REFLEX_BINDING_TEMPLATE_MATERIALIZATION_QUEUE_LEDGER_PATH)
    queued_rows = [row for row in ledger.get("queued_requests") or [] if isinstance(row, Mapping)]
    request_records: list[dict[str, Any]] = []
    for row in queued_rows:
        rel = str(row.get("packet_path") or "").strip()
        request = _read_json_file(root / rel) if rel else {}
        request_records.append(
            {
                "request_id": request.get("request_id") or row.get("request_id"),
                "packet_path": rel,
                "lane_id": request.get("lane_id") or row.get("lane_id"),
                "request_kind": request.get("request_kind"),
                "status": request.get("status") or row.get("request_status"),
                "latest_return_packet_path": request.get("latest_return_packet_path"),
                "return_packet_paths": request.get("return_packet_paths") or [],
                "worker_started": bool(row.get("worker_started")),
            }
        )
    queued_count = len(request_records)
    queueable_count = sum(1 for row in request_records if row.get("status") == "QUEUED_FOR_CODEX_CARRIER")
    accepted_count = sum(1 for row in request_records if row.get("status") == "RETURN_RECORDED_PROOF_ACCEPTED")
    started_or_claimed_count = sum(
        1
        for row in request_records
        if str(row.get("status") or "") in {"CLAIMED_BY_CODEX_QUEUE_RUNNER", "CODEX_CLI_RUNNING"}
    )
    fanout_returns_complete = queued_count == 3 and accepted_count == 3
    ready = queued_count == 3 and queueable_count > 0
    next_packet = (
        {
            "packet_id": "PCKT-DOMAIN-WEAVER-FISSION-REFLEX-BINDING-FANIN-SETTLEMENT-20260602-ATTEMPT-001",
            "lane_id": "settlement_lane",
            "work_class": "settlement",
            "recommended_worker": "role.nemesis",
            "objective": (
                "Fan in the accepted fission execution gates, Domain Reflex Network ruleset, and specialist binding "
                "matrix returns. Settle blockers, overclaims, next packet, and authority posture before any source "
                "mutation, active registry write, accepted-state movement, or further live fanout."
            ),
        }
        if fanout_returns_complete
        else {
            "packet_id": "PCKT-DOMAIN-WEAVER-FISSION-REFLEX-BINDING-FANOUT-WORKER-START-20260602-ATTEMPT-001",
            "lane_id": "architecture_lane",
            "work_class": "worker_start_gate",
            "recommended_worker": "role.steward",
            "objective": (
                "Start queued fission/reflex/binding fanout workers under queue-runner lane locks and max worker "
                "limits. Preserve false production/live/accepted-state/secrets authority and do not bypass lane locks."
            ),
        }
        if ready
        else {}
    )
    if fanout_returns_complete:
        status = "fission_reflex_binding_fanout_returns_complete"
    elif ready:
        status = "fission_reflex_binding_templates_queued"
    else:
        status = "fission_reflex_binding_templates_not_ready"
    return {
        "schema_id": "ion.domain_weaver.fission_reflex_binding_materialization_state.v0_1_candidate",
        "generated_at": _now(),
        "status": status,
        "templates_queued": ready,
        "fanout_returns_complete": fanout_returns_complete,
        "source_queue_ledger_path": (
            DOMAIN_WEAVER_FISSION_REFLEX_BINDING_TEMPLATE_MATERIALIZATION_QUEUE_LEDGER_PATH.as_posix()
        ),
        "queued_requests": request_records,
        "recommended_next_packet": next_packet,
        "summary": {
            "templates_queued": ready,
            "queued_request_count": queued_count,
            "queueable_start_request_count": queueable_count,
            "accepted_return_count": accepted_count,
            "started_or_claimed_count": started_or_claimed_count,
            "fanout_returns_complete": fanout_returns_complete,
        },
        "authority": {
            "candidate_materialization_state_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }


