def _domain_weaver_latest_child_domain_specialist_binding_repair_ui_canon_reissue_fanin_result(
    root: Path,
    *,
    materialize: bool = False,
) -> dict[str, Any]:
    request_rel = (
        CODEX_WORK_REQUESTS_DIR
        / (
            "codex_req_domain_weaver_child_domain_specialist_binding_repair_ui_canon_reissue_fanin_settlement_"
            "20260602_attempt_001.json"
        )
    ).as_posix()
    request = _read_json_file(root / request_rel)
    return_rel = str(request.get("latest_return_packet_path") or "").strip()
    latest_return = _read_json_file(root / return_rel) if return_rel else {}
    accepted = bool(
        str(request.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
        and latest_return.get("accepted_for_carrier_intake") is True
    )
    run_packet_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = (
        (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
        if task_return_body_path and (root / task_return_body_path).is_file()
        else ""
    )
    match = re.search(
        (
            r"`?(PCKT-DOMAIN-WEAVER-CHILD-DOMAIN-SPECIALIST-BINDING-REPAIR-"
            r"ACTIVE-BINDING-READINESS-GATE-[A-Z0-9-]+)`?"
        ),
        body_text,
    )
    recommended_packet_id = match.group(1) if match else ""
    settlement = _as_mapping(
        request.get("domain_weaver_child_domain_specialist_binding_repair_ui_canon_reissue_fanin_settlement")
    )
    accepted_records = [row for row in settlement.get("accepted_returns") or [] if isinstance(row, Mapping)]
    implementation_ready_now = not (
        "implementation_ready_now: false" in body_text.lower()
        or "implementation_ready_now=false" in body_text.lower()
    )
    exact_active_binding_ready = not (
        "EXACT_ACTIVE_BINDING_MISSING" in body_text
        or "exact active specialist binding: fail" in body_text.lower()
        or "exact_active_binding_count=0" in body_text
    )
    result_ready = bool(accepted and recommended_packet_id)
    result = {
        "schema_id": (
            "ion.domain_weaver.child_domain_specialist_binding_repair_ui_canon_reissue_fanin_result."
            "v0_1_candidate"
        ),
        "generated_at": _now(),
        "accepted": accepted,
        "result_ready": result_ready,
        "status": (
            "child_domain_specialist_binding_repair_ui_canon_reissue_fanin_settled"
            if result_ready
            else "missing"
        ),
        "source_request_path": request_rel,
        "source_return_packet_path": return_rel,
        "source_run_packet_path": run_packet_path,
        "source_task_return_body_path": task_return_body_path,
        "source_machine_receipt_path": str(
            latest_return.get("machine_receipt_path")
            or request.get("latest_task_return_machine_receipt_path")
            or ""
        ),
        "recommended_next_packet": (
            {
                "packet_id": recommended_packet_id,
                "lane_id": "architecture_lane",
                "work_class": "architecture",
                "recommended_worker": "role.steward",
                "supporting_roles": ["role.nemesis", "role.scribe"],
                "objective": (
                    "Gate exact active child-domain/specialist bindings after UI-canon debt repair. Decide "
                    "whether candidate active-binding materialization may be queued or the missing exact bindings "
                    "must be stop-classified, without source, active registry, accepted-state, production, live "
                    "execution, service, queue fanout, or secrets authority."
                ),
            }
            if result_ready
            else {}
        ),
        "accepted_returns": accepted_records,
        "summary": {
            "result_ready": result_ready,
            "accepted": accepted,
            "recommended_next_packet_id": recommended_packet_id,
            "expected_return_count": int(settlement.get("expected_return_count") or 0),
            "accepted_return_count": int(settlement.get("accepted_return_count") or len(accepted_records)),
            "ui_canon_context_debt_repaired": "ui-canon context debt is repaired" in body_text.lower()
            or "ui_canon_reissue_fanin_settlement_complete" in body_text,
            "implementation_ready_now": implementation_ready_now,
            "exact_active_binding_ready": exact_active_binding_ready,
            "body_sha256": hashlib.sha256(body_text.encode("utf-8")).hexdigest() if body_text else "",
        },
        "authority": {
            "candidate_reissue_fanin_result_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    if materialize and result_ready:
        path = root / DOMAIN_WEAVER_CHILD_DOMAIN_SPECIALIST_BINDING_REPAIR_UI_CANON_REISSUE_FANIN_RESULT_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        result["result_path"] = (
            DOMAIN_WEAVER_CHILD_DOMAIN_SPECIALIST_BINDING_REPAIR_UI_CANON_REISSUE_FANIN_RESULT_PATH.as_posix()
        )
    return result


