def _domain_weaver_latest_exact_active_specialist_binding_proof_matrix_result(
    root: Path,
    *,
    materialize: bool = False,
) -> dict[str, Any]:
    request_rel = (
        CODEX_WORK_REQUESTS_DIR
        / "codex_req_domain_weaver_exact_active_specialist_binding_proof_matrix_20260602_attempt_001.json"
    ).as_posix()
    request = _read_json_file(root / request_rel)
    return_rel = str(request.get("latest_return_packet_path") or "").strip()
    latest_return = _read_json_file(root / return_rel) if return_rel else {}
    accepted = bool(
        str(request.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
        and latest_return.get("accepted_for_carrier_intake") is True
    )
    run_packet_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = (
        (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
        if task_return_body_path and (root / task_return_body_path).is_file()
        else ""
    )
    body_lower = body_text.lower()
    match = re.search(
        r"`?(PCKT-DOMAIN-WEAVER-EXACT-ACTIVE-SPECIALIST-BINDING-AUTHORITY-SETTLEMENT-[A-Z0-9-]+)`?",
        body_text,
    )
    recommended_packet_id = match.group(1) if match else ""
    verdict_match = re.search(r"verdict:\s*`?([A-Za-z0-9_:-]+)`?", body_text)
    matrix_match = re.search(r"Matrix verdict:\s*`?([A-Za-z0-9_:-]+)`?", body_text)
    result_verdict = verdict_match.group(1) if verdict_match else ""
    matrix_verdict = matrix_match.group(1) if matrix_match else ""
    stop_classified = bool(
        "STOP_CLASSIFIED_MISSING_EXACT_ACTIVE_SPECIALIST_BINDINGS" in body_text
        or "stop_classified" in body_lower
    )
    exact_binding_missing = bool(
        "EXACT_ACTIVE_BINDING_MISSING" in body_text
        or "exact_active_binding_count=0" in body_text
        or "exact active binding count is zero" in body_lower
    )
    delegated_substitution_settled = not (
        "DELEGATED_SUBSTITUTION_NOT_SETTLED" in body_text
        or "no accepted delegated-substitution gate" in body_lower
    )
    result_ready = bool(
        accepted
        and recommended_packet_id
        and "### EXACT ACTIVE SPECIALIST BINDING PROOF MATRIX" in body_text
    )
    result = {
        "schema_id": "ion.domain_weaver.exact_active_specialist_binding_proof_matrix_result.v0_1_candidate",
        "generated_at": _now(),
        "accepted": accepted,
        "result_ready": result_ready,
        "status": "exact_active_specialist_binding_proof_matrix_settled" if result_ready else "missing",
        "source_request_path": request_rel,
        "source_return_packet_path": return_rel,
        "source_run_packet_path": run_packet_path,
        "source_task_return_body_path": task_return_body_path,
        "source_machine_receipt_path": str(
            latest_return.get("machine_receipt_path")
            or request.get("latest_task_return_machine_receipt_path")
            or ""
        ),
        "recommended_next_packet": (
            {
                "packet_id": recommended_packet_id,
                "lane_id": "architecture_lane",
                "work_class": "architecture",
                "recommended_worker": "role.steward",
                "supporting_roles": ["role.nemesis", "role.scribe"],
                "objective": (
                    "Produce a bounded candidate-only authority settlement for exact active specialist bindings. "
                    "Either prove exact per-specialist active invocable bindings for all six required specialists "
                    "or explicitly settle the delegated-substitution exception for COMPONENT_BUILDER -> role.mason. "
                    "Do not write active registries, mutate source, claim accepted state, touch production/live "
                    "execution, restart services, fan out queues, delete paths, push git, or access secrets."
                ),
            }
            if result_ready
            else {}
        ),
        "summary": {
            "result_ready": result_ready,
            "accepted": accepted,
            "recommended_next_packet_id": recommended_packet_id,
            "result_verdict": result_verdict,
            "matrix_verdict": matrix_verdict,
            "exact_active_specialist_binding_matrix_ready": (
                "exact_active_specialist_binding_matrix_ready: true" in body_lower
            ),
            "candidate_materialization_ready": "candidate_materialization_ready: true" in body_lower,
            "implementation_ready_now": "implementation_ready_now: true" in body_lower,
            "stop_classified_missing_exact_active_bindings": stop_classified,
            "exact_active_binding_count": 0 if exact_binding_missing else None,
            "candidate_boot_only_count": 5 if "five candidate-boot-only" in body_lower else None,
            "delegated_binding_not_exact": "DELEGATED_BINDING_NOT_EXACT" in body_text,
            "delegated_substitution_settled": delegated_substitution_settled,
            "context_hash_drift_note_present": "Receipt/current hash note" in body_text,
            "body_sha256": hashlib.sha256(body_text.encode("utf-8")).hexdigest() if body_text else "",
        },
        "authority": {
            "candidate_exact_active_specialist_binding_proof_matrix_result_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    if materialize and result_ready:
        path = root / DOMAIN_WEAVER_EXACT_ACTIVE_SPECIALIST_BINDING_PROOF_MATRIX_RESULT_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        result["result_path"] = DOMAIN_WEAVER_EXACT_ACTIVE_SPECIALIST_BINDING_PROOF_MATRIX_RESULT_PATH.as_posix()
    return result


