def _domain_weaver_latest_exact_active_specialist_binding_activation_or_delegated_substitution_repair_result(
    root: Path,
    *,
    materialize: bool = False,
) -> dict[str, Any]:
    request_rel = (
        CODEX_WORK_REQUESTS_DIR
        / (
            "codex_req_domain_weaver_exact_active_specialist_binding_activation_or_delegated_substitution_repair_"
            "20260602_attempt_001.json"
        )
    ).as_posix()
    request = _read_json_file(root / request_rel)
    return_rel = str(request.get("latest_return_packet_path") or "").strip()
    latest_return = _read_json_file(root / return_rel) if return_rel else {}
    accepted = bool(
        str(request.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
        and latest_return.get("accepted_for_carrier_intake") is True
    )
    run_packet_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_payload = _read_json_file(root / run_packet_path) if run_packet_path else {}
        run_body = str(run_payload.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = (
        (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
        if task_return_body_path and (root / task_return_body_path).is_file()
        else ""
    )
    body_lower = body_text.lower()
    next_section_match = re.search(
        r"### RECOMMENDED NEXT PACKET(?P<section>.*?)(?:\n### |\Z)",
        body_text,
        flags=re.DOTALL,
    )
    next_section = next_section_match.group("section") if next_section_match else ""
    next_packet_matches = re.findall(
        r"`?(PCKT-DOMAIN-WEAVER-[A-Z0-9-]+)`?",
        next_section or body_text,
    )
    recommended_packet_id = next_packet_matches[-1] if next_packet_matches else ""
    verdict_match = re.search(r"verdict:\s*`?([A-Za-z0-9_:-]+)`?", body_text)
    delegated_verdict_match = re.search(
        r"delegated_substitution_verdict:\s*`?([A-Za-z0-9_:-]+)`?",
        body_text,
    )
    result_verdict = verdict_match.group(1) if verdict_match else ""
    delegated_substitution_verdict = delegated_verdict_match.group(1) if delegated_verdict_match else ""
    exact_active_binding_count = _domain_weaver_first_int_after_label(
        body_text,
        "exact_active_binding_count",
        default=-1,
    )
    candidate_boot_only_count = _domain_weaver_first_int_after_label(
        body_text,
        "candidate_boot_only_count",
        default=-1,
    )
    delegated_active_binding_count = _domain_weaver_first_int_after_label(
        body_text,
        "delegated_active_binding_count",
        default=-1,
    )
    exact_active_binding_count_out = exact_active_binding_count if exact_active_binding_count >= 0 else None
    candidate_boot_only_count_out = candidate_boot_only_count if candidate_boot_only_count >= 0 else None
    delegated_active_binding_count_out = (
        delegated_active_binding_count if delegated_active_binding_count >= 0 else None
    )
    delegated_substitution_settled = bool(
        "delegated_substitution_settled: true" in body_lower
        or "delegated_substitution_accepted: true" in body_lower
        or "delegated_substitution_verdict: accepted" in body_lower
        or "DELEGATED_SUBSTITUTION_ACCEPTED" in body_text
    )
    delegated_substitution_not_accepted = bool(
        "DELEGATED_SUBSTITUTION_NOT_ACCEPTED" in body_text
        or "DELEGATED_SUBSTITUTION_NOT_SETTLED" in body_text
        or "delegated_substitution_settled: false" in body_lower
    )
    all_required_specialists_bound = bool(
        "all_required_specialists_bound: true" in body_lower
        or "exact_active_specialist_binding_matrix_ready: true" in body_lower
        or "exact_active_binding_matrix_ready: true" in body_lower
        or exact_active_binding_count >= 6
    )
    materialization_ready = bool(
        "materialization_ready: true" in body_lower
        or "candidate_materialization_ready: true" in body_lower
        or "implementation_ready_now: true" in body_lower
        or all_required_specialists_bound
        or (exact_active_binding_count >= 5 and delegated_substitution_settled)
    )
    stop_classified = bool(
        "STOP_CLASSIFIED_MISSING_EXACT_ACTIVE_SPECIALIST_BINDINGS" in body_text
        or "stop_classified_missing_exact_active_specialist_bindings" in body_lower
        or "missing exact active specialist bindings" in body_lower
    )
    result_ready = bool(
        accepted
        and recommended_packet_id
        and "### ACTIVATION OR DELEGATED SUBSTITUTION REPAIR" in body_text
    )
    result = {
        "schema_id": (
            "ion.domain_weaver.exact_active_specialist_binding_activation_or_delegated_substitution_repair_result."
            "v0_1_candidate"
        ),
        "generated_at": _now(),
        "accepted": accepted,
        "result_ready": result_ready,
        "status": (
            "exact_active_specialist_binding_activation_or_delegated_substitution_repair_settled"
            if result_ready
            else "missing"
        ),
        "source_request_path": request_rel,
        "source_return_packet_path": return_rel,
        "source_run_packet_path": run_packet_path,
        "source_task_return_body_path": task_return_body_path,
        "source_machine_receipt_path": str(
            latest_return.get("machine_receipt_path")
            or request.get("latest_task_return_machine_receipt_path")
            or ""
        ),
        "recommended_next_packet": (
            {
                "packet_id": recommended_packet_id,
                "lane_id": "architecture_lane",
                "work_class": "architecture",
                "recommended_worker": "role.steward",
                "supporting_roles": ["role.nemesis", "role.scribe"],
                "objective": (
                    "Continue the exact active specialist binding repair from the accepted activation/delegated-"
                    "substitution result. Preserve candidate-only authority; do not mutate source, write active "
                    "registries, claim accepted state, touch production/live execution, restart services, fan out "
                    "queues, delete paths, push git, or access secrets unless a later explicit authority gate says so."
                ),
            }
            if result_ready
            else {}
        ),
        "summary": {
            "result_ready": result_ready,
            "accepted": accepted,
            "recommended_next_packet_id": recommended_packet_id,
            "result_verdict": result_verdict,
            "delegated_substitution_verdict": delegated_substitution_verdict,
            "activation_repair_settled": result_ready,
            "all_required_specialists_bound": all_required_specialists_bound,
            "materialization_ready": materialization_ready,
            "candidate_materialization_ready": "candidate_materialization_ready: true" in body_lower,
            "implementation_ready_now": "implementation_ready_now: true" in body_lower,
            "stop_classified_missing_exact_active_bindings": stop_classified,
            "exact_active_binding_count": exact_active_binding_count_out,
            "candidate_boot_only_count": candidate_boot_only_count_out,
            "delegated_active_binding_count": delegated_active_binding_count_out,
            "delegated_substitution_settled": delegated_substitution_settled,
            "delegated_substitution_not_accepted": delegated_substitution_not_accepted,
            "candidate_boot_only_not_active_binding": "CANDIDATE_BOOT_ONLY_NOT_ACTIVE_BINDING" in body_text,
            "delegated_binding_not_exact": "DELEGATED_BINDING_NOT_EXACT" in body_text,
            "body_sha256": hashlib.sha256(body_text.encode("utf-8")).hexdigest() if body_text else "",
        },
        "authority": {
            "candidate_exact_active_specialist_binding_activation_or_delegated_substitution_repair_result_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "active_registry_write_authority": False,
            "source_mutation_authority": False,
            "queue_fanout_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    if materialize and result_ready:
        path = (
            root
            / DOMAIN_WEAVER_EXACT_ACTIVE_SPECIALIST_BINDING_ACTIVATION_OR_DELEGATED_SUBSTITUTION_REPAIR_RESULT_PATH
        )
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        result["result_path"] = (
            DOMAIN_WEAVER_EXACT_ACTIVE_SPECIALIST_BINDING_ACTIVATION_OR_DELEGATED_SUBSTITUTION_REPAIR_RESULT_PATH.as_posix()
        )
    return result


