def _domain_weaver_latest_visual_proof_live_hydration_operator_rejection_settlement_result(
    root: Path,
    *,
    materialize: bool = False,
) -> dict[str, Any]:
    prefix = "codex_req_domain_weaver_visual_proof_live_hydration_operator_rejection_settlement_20260602_attempt_"
    request_rows: list[tuple[int, float, Path, dict[str, Any], dict[str, Any]]] = []
    for path in sorted((root / CODEX_WORK_REQUESTS_DIR).glob(f"{prefix}*.json")):
        request = _read_json_file(path)
        return_path = str(request.get("latest_return_packet_path") or "").strip()
        latest_return = _read_json_file(root / return_path) if return_path else {}
        suffix = path.stem.replace(prefix, "", 1)
        try:
            attempt_index = int(suffix)
        except ValueError:
            attempt_index = 0
        if (
            str(request.get("status") or "") == "RETURN_RECORDED_PROOF_ACCEPTED"
            and latest_return.get("accepted_for_carrier_intake") is True
        ):
            request_rows.append((attempt_index, path.stat().st_mtime, path, request, latest_return))
    if not request_rows:
        result = {
            "schema_id": (
                "ion.domain_weaver.visual_proof_live_hydration_operator_rejection_settlement_result."
                "v0_1_candidate"
            ),
            "created_at": _now(),
            "result_ready": False,
            "status": "missing",
            "finding": "visual_proof_live_hydration_operator_rejection_settlement_not_accepted",
            "summary": {
                "result_ready": False,
                "accepted": False,
                "live_model_hydration_proved": False,
                "live_model_hydration_blocked": False,
                "operator_rejection_superseded": False,
                "operator_rejection_active": False,
                "recommended_next_packet_id": "",
            },
            "authority": {
                "candidate_visual_proof_settlement_result_only": True,
                "production_authority": False,
                "live_execution_authority": False,
                "accepted_state_authority": False,
                "source_mutation_authority": False,
                "secrets_authority": False,
            },
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        }
        if materialize:
            path = root / DOMAIN_WEAVER_VISUAL_PROOF_LIVE_HYDRATION_OPERATOR_REJECTION_SETTLEMENT_RESULT_PATH
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
            result["result_path"] = (
                DOMAIN_WEAVER_VISUAL_PROOF_LIVE_HYDRATION_OPERATOR_REJECTION_SETTLEMENT_RESULT_PATH.as_posix()
            )
        return result
    attempt_index, _mtime, request_path, request, latest_return = sorted(
        request_rows,
        key=lambda row: (row[0], row[1], row[2].name),
    )[-1]
    request_rel = _rel(root, request_path)
    return_path = str(request.get("latest_return_packet_path") or "").strip()
    run_packet_path = ""
    task_return_body_path = _domain_weaver_task_body_from_return_packet(latest_return)
    for run in _domain_weaver_request_run_packets(root, request_rel):
        run_packet_path = str(run.get("run_packet_path") or "")
        run_body = str(run.get("task_return_body_path") or "")
        if run_body and (root / run_body).is_file():
            task_return_body_path = run_body
    if not task_return_body_path and run_packet_path:
        candidate = (root / run_packet_path).parent / "task_return_body.md"
        if candidate.is_file():
            task_return_body_path = _rel(root, candidate)
    body_text = (
        (root / task_return_body_path).read_text(encoding="utf-8", errors="replace")
        if task_return_body_path and (root / task_return_body_path).is_file()
        else ""
    )
    body_lower = body_text.lower()
    recommended_next_packet_id = ""
    match = re.search(
        r"`?(PCKT-DOMAIN-WEAVER-LIVE-MODEL-HYDRATION-ENDPOINT-HANG-REPAIR-AND-REPROOF-[A-Z0-9-]+)`?",
        body_text,
    )
    if match:
        recommended_next_packet_id = match.group(1)
    live_model_hydration_proved = bool(
        "live_model_hydration_proved: `true`" in body_lower
        or "model_endpoint_live_hydration_proved: `true`" in body_lower
    )
    live_model_hydration_blocked = bool(
        "live_model_hydration_proved: `false`" in body_lower
        or "model_endpoint_live_hydration_proved: false" in body_lower
        or "model_endpoint_live_hydration_blocked: `true`" in body_lower
        or "live_model_hydration_unproved" in body_lower
    )
    operator_rejection_superseded = bool("operator_rejection_superseded: `true`" in body_lower)
    operator_rejection_active = bool(
        "operator_rejection_superseded: `false`" in body_lower
        or "operator_rejection_still_active" in body_lower
        or "operator rejection remains active" in body_lower
    )
    fresh_live_browser_screenshot_uncaptured = "fresh_live_browser_screenshot_uncaptured" in body_lower
    endpoint_timeout_observed = "/cockpit/model.json" in body_lower and "timed out" in body_lower
    exact_active_binding_settlement_complete = "exact_active_binding_settlement_complete: true" in body_lower
    result_ready = bool(
        return_path
        and task_return_body_path
        and (live_model_hydration_proved or live_model_hydration_blocked)
    )
    blocked = bool(
        result_ready
        and (
            live_model_hydration_blocked
            or operator_rejection_active
            or fresh_live_browser_screenshot_uncaptured
            or not exact_active_binding_settlement_complete
        )
    )
    status = (
        "visual_proof_live_hydration_operator_rejection_settled"
        if result_ready and live_model_hydration_proved and operator_rejection_superseded and not blocked
        else "visual_proof_live_hydration_operator_rejection_blocked"
        if blocked
        else "visual_proof_live_hydration_operator_rejection_result_incomplete"
    )
    result = {
        "schema_id": (
            "ion.domain_weaver.visual_proof_live_hydration_operator_rejection_settlement_result."
            "v0_1_candidate"
        ),
        "created_at": _now(),
        "result_ready": result_ready,
        "status": status,
        "request_path": request_rel,
        "request_id": request.get("request_id"),
        "return_path": return_path,
        "run_packet_path": run_packet_path,
        "task_return_body_path": task_return_body_path,
        "machine_receipt_path": str(
            latest_return.get("machine_receipt_path") or request.get("latest_task_return_machine_receipt_path") or ""
        ),
        "recommended_next_packet": (
            {
                "packet_id": recommended_next_packet_id,
                "lane_id": "browser_lane",
                "work_class": "hydration_endpoint_repair",
                "recommended_worker": "role.mason",
                "supporting_roles": ["role.visual_proof_auditor", "role.nemesis", "role.steward"],
                "objective": (
                    "Diagnose and repair the already-running /cockpit/model.json hydration timeout for "
                    "/cockpit#weave, then capture fresh live visual proof before any operator-rejection "
                    "supersession proposal."
                ),
            }
            if recommended_next_packet_id
            else {}
        ),
        "summary": {
            "result_ready": result_ready,
            "accepted": True,
            "attempt_index": attempt_index,
            "live_model_hydration_proved": live_model_hydration_proved,
            "live_model_hydration_blocked": live_model_hydration_blocked,
            "operator_rejection_superseded": operator_rejection_superseded,
            "operator_rejection_active": operator_rejection_active,
            "fresh_live_browser_screenshot_uncaptured": fresh_live_browser_screenshot_uncaptured,
            "endpoint_timeout_observed": endpoint_timeout_observed,
            "exact_active_binding_settlement_complete": exact_active_binding_settlement_complete,
            "blocked": blocked,
            "recommended_next_packet_id": recommended_next_packet_id,
            "candidate_only": True,
        },
        "authority": {
            "candidate_visual_proof_settlement_result_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "source_mutation_authority": False,
            "active_registry_write_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    if materialize:
        path = root / DOMAIN_WEAVER_VISUAL_PROOF_LIVE_HYDRATION_OPERATOR_REJECTION_SETTLEMENT_RESULT_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        result["result_path"] = (
            DOMAIN_WEAVER_VISUAL_PROOF_LIVE_HYDRATION_OPERATOR_REJECTION_SETTLEMENT_RESULT_PATH.as_posix()
        )
        result["materialized_paths"] = [
            DOMAIN_WEAVER_VISUAL_PROOF_LIVE_HYDRATION_OPERATOR_REJECTION_SETTLEMENT_RESULT_PATH.as_posix()
        ]
    else:
        result["result_path"] = (
            DOMAIN_WEAVER_VISUAL_PROOF_LIVE_HYDRATION_OPERATOR_REJECTION_SETTLEMENT_RESULT_PATH.as_posix()
        )
        result["materialized_paths"] = []
    return result


def _domain_weaver_live_return_monitor(
    root: Path,
    *,
    live_carrier_binding: Mapping[str, Any],
    materialize: bool = False,
) -> dict[str, Any]:
    queue_ledger = _read_json_file(root / DOMAIN_WEAVER_LIVE_CARRIER_QUEUE_LEDGER_PATH)
    queued_requests = [
        row for row in queue_ledger.get("queued_requests") or [] if isinstance(row, Mapping)
    ]
    if not queued_requests:
        queued_requests = [
            {
                "request_id": row.get("request_id"),
                "packet_path": row.get("packet_path"),
                "lane_id": row.get("lane_id"),
                "worker_started": False,
            }
            for row in live_carrier_binding.get("work_request_templates") or []
            if isinstance(row, Mapping)
        ]
    observed: list[dict[str, Any]] = []
    for queued in queued_requests:
        request_path = str(queued.get("packet_path") or "").strip()
        request = _read_json_file(root / request_path) if request_path else {}
        return_paths = [
            str(path)
            for path in [
                *[item for item in request.get("return_packet_paths") or [] if str(item)],
                request.get("latest_return_packet_path"),
            ]
            if str(path or "").strip()
        ]
        unique_return_paths = _unique_paths(return_paths)
        latest_return_path = unique_return_paths[-1] if unique_return_paths else ""
        latest_return = _read_json_file(root / latest_return_path) if latest_return_path else {}
        context_result = _as_mapping(latest_return.get("context_proof_result"))
        template_result = _as_mapping(latest_return.get("template_action_proof_result"))
        runs = _domain_weaver_request_run_packets(root, request_path) if request_path else []
        run_statuses = [str(row.get("status") or "") for row in runs]
        accepted = bool(
            request.get("status") == "RETURN_RECORDED_PROOF_ACCEPTED"
            or latest_return.get("accepted_for_carrier_intake")
        )
        blocked = bool(
            str(request.get("status") or "") in {"RETURN_TEMPLATE_INVALID", "RETURN_RECORDED_PROOF_BLOCKED", "CODEX_QUEUE_RUNNER_FAILED"}
            and not accepted
        )
        running = any(status == "CODEX_CLI_RUNNING" for status in run_statuses)
        observed.append(
            {
                "request_id": request.get("request_id") or queued.get("request_id"),
                "request_path": request_path,
                "lane_id": request.get("lane_id") or queued.get("lane_id"),
                "request_status": request.get("status") or "missing",
                "worker_started": bool(queued.get("worker_started")) or bool(runs),
                "run_count": len(runs),
                "latest_run_status": run_statuses[-1] if run_statuses else "",
                "running": running,
                "blocked": blocked,
                "accepted_return": accepted,
                "latest_return_packet_path": latest_return_path,
                "return_packet_count": len(unique_return_paths),
                "context_proof_accepted": bool(context_result.get("accepted")),
                "template_action_proof_accepted": bool(template_result.get("accepted")),
                "workload_diff_accepted": bool(latest_return.get("workload_diff_accepted")),
                "task_return_created_at": latest_return.get("created_at"),
                "run_packets": runs,
            }
        )
    expected_return_count = len(observed)
    accepted_return_count = sum(1 for row in observed if row.get("accepted_return"))
    blocked_return_count = sum(1 for row in observed if row.get("blocked"))
    running_return_count = sum(1 for row in observed if row.get("running"))
    worker_started_count = sum(1 for row in observed if row.get("worker_started"))
    remaining_return_count = max(expected_return_count - accepted_return_count - blocked_return_count, 0)
    monitor = {
        "schema_id": "ion.domain_weaver.live_return_monitor.v0_1_candidate",
        "created_at": _now(),
        "status": (
            "live_return_monitor_complete"
            if expected_return_count and accepted_return_count == expected_return_count
            else "live_return_monitor_partial"
            if accepted_return_count or running_return_count or worker_started_count
            else "live_return_monitor_ready"
        ),
        "live_return_monitor_ready": True,
        "source_queue_ledger_path": DOMAIN_WEAVER_LIVE_CARRIER_QUEUE_LEDGER_PATH.as_posix(),
        "source_binding_plan_path": DOMAIN_WEAVER_LIVE_CARRIER_BINDING_PLAN_PATH.as_posix(),
        "observed_returns": observed,
        "summary": {
            "live_return_monitor_ready": True,
            "expected_return_count": expected_return_count,
            "accepted_return_count": accepted_return_count,
            "blocked_return_count": blocked_return_count,
            "running_return_count": running_return_count,
            "remaining_return_count": remaining_return_count,
            "worker_started_count": worker_started_count,
            "return_complete": bool(expected_return_count and accepted_return_count == expected_return_count),
        },
        "authority": {
            "candidate_return_monitor_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    if materialize:
        path = root / DOMAIN_WEAVER_LIVE_RETURN_MONITOR_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(monitor, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        monitor["monitor_path"] = DOMAIN_WEAVER_LIVE_RETURN_MONITOR_PATH.as_posix()
        monitor["materialized_paths"] = [DOMAIN_WEAVER_LIVE_RETURN_MONITOR_PATH.as_posix()]
    else:
        monitor["monitor_path"] = DOMAIN_WEAVER_LIVE_RETURN_MONITOR_PATH.as_posix()
        monitor["materialized_paths"] = []
    return monitor


def _domain_weaver_live_fanin_settlement(
    root: Path,
    *,
    live_return_monitor: Mapping[str, Any],
    materialize: bool = False,
) -> dict[str, Any]:
    monitor_summary = _as_mapping(live_return_monitor.get("summary"))
    observed_returns = [
        row for row in live_return_monitor.get("observed_returns") or [] if isinstance(row, Mapping)
    ]
    return_records: list[dict[str, Any]] = []
    for row in observed_returns:
        latest_return_path = str(row.get("latest_return_packet_path") or "").strip()
        latest_return = _read_json_file(root / latest_return_path) if latest_return_path else {}
        context_result = _as_mapping(latest_return.get("context_proof_result"))
        template_result = _as_mapping(latest_return.get("template_action_proof_result"))
        accepted = bool(row.get("accepted_return"))
        blocked = bool(row.get("blocked"))
        return_records.append(
            {
                "request_id": row.get("request_id"),
                "request_path": row.get("request_path"),
                "lane_id": row.get("lane_id"),
                "accepted_return": accepted,
                "blocked": blocked,
                "latest_return_packet_path": latest_return_path,
                "context_proof_accepted": bool(
                    row.get("context_proof_accepted") or context_result.get("accepted")
                ),
                "template_action_proof_accepted": bool(
                    row.get("template_action_proof_accepted") or template_result.get("accepted")
                ),
                "workload_diff_accepted": bool(
                    row.get("workload_diff_accepted") or latest_return.get("workload_diff_accepted")
                ),
                "task_return_created_at": row.get("task_return_created_at") or latest_return.get("created_at"),
                "run_count": row.get("run_count", 0),
            }
        )
    expected_count = int(monitor_summary.get("expected_return_count") or len(return_records))
    accepted_count = sum(1 for row in return_records if row.get("accepted_return"))
    blocked_count = sum(1 for row in return_records if row.get("blocked"))
    missing_count = max(expected_count - accepted_count - blocked_count, 0)
    settlement_complete = bool(expected_count and accepted_count == expected_count and blocked_count == 0)
    blockers: list[dict[str, Any]] = []
    if blocked_count:
        blockers.append(
            {
                "code": "LIVE_FANIN_SETTLEMENT_BLOCKED_RETURN",
                "severity": "critical",
                "detail": "One or more live fanout returns are blocked or failed.",
            }
        )
    if missing_count:
        blockers.append(
            {
                "code": "LIVE_FANIN_SETTLEMENT_MISSING_RETURNS",
                "severity": "high",
                "detail": "One or more expected live fanout returns are not yet accepted or blocked.",
            }
        )
    settlement = {
        "schema_id": "ion.domain_weaver.live_fanin_settlement.v0_1_candidate",
        "created_at": _now(),
        "status": (
            "live_fanin_settlement_complete"
            if settlement_complete
            else "live_fanin_settlement_blocked"
            if blockers
            else "live_fanin_settlement_waiting"
        ),
        "live_fanin_settlement_ready": True,
        "settlement_complete": settlement_complete,
        "source_return_monitor_path": DOMAIN_WEAVER_LIVE_RETURN_MONITOR_PATH.as_posix(),
        "return_records": return_records,
        "blockers": blockers,
        "parent_decision": {
            "decision": (
                "advance_to_recursive_live_domain_weaver_cycle"
                if settlement_complete
                else "continue_or_repair_live_fanout_returns"
            ),
            "reason": (
                "All expected Domain Weaver live fanout returns were accepted by the carrier proof gate."
                if settlement_complete
                else "Live fanout returns are not fully settled."
            ),
            "next_packet": (
                {
                    "packet_id": "PCKT-DOMAIN-WEAVER-RECURSIVE-LIVE-FANOUT-CHAIN-MVP-20260601",
                    "lane_id": "settlement_lane",
                    "work_class": "settlement",
                    "recommended_worker": "role.nemesis",
                    "objective": (
                        "Use the completed live fan-in settlement to select the next recursive Domain Weaver cycle, "
                        "enforce token and chain thresholds, and preserve candidate-only authority."
                    ),
                }
                if settlement_complete
                else {
                    "packet_id": "PCKT-DOMAIN-WEAVER-LIVE-FANOUT-CONTINUE-RETURNS-20260601",
                    "lane_id": "settlement_lane",
                    "work_class": "settlement",
                    "recommended_worker": "role.nemesis",
                    "objective": "Continue or repair the live fanout until every expected return is accepted or explicitly blocked.",
                }
            ),
        },
        "summary": {
            "live_fanin_settlement_ready": True,
            "settlement_complete": settlement_complete,
            "expected_return_count": expected_count,
            "accepted_return_count": accepted_count,
            "blocked_return_count": blocked_count,
            "missing_return_count": missing_count,
            "settled_return_count": accepted_count,
            "blocker_count": len(blockers),
        },
        "authority": {
            "candidate_fanin_settlement_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    if materialize:
        path = root / DOMAIN_WEAVER_LIVE_FANIN_SETTLEMENT_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(settlement, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        settlement["settlement_path"] = DOMAIN_WEAVER_LIVE_FANIN_SETTLEMENT_PATH.as_posix()
        settlement["materialized_paths"] = [DOMAIN_WEAVER_LIVE_FANIN_SETTLEMENT_PATH.as_posix()]
    else:
        settlement["settlement_path"] = DOMAIN_WEAVER_LIVE_FANIN_SETTLEMENT_PATH.as_posix()
        settlement["materialized_paths"] = []
    return settlement


def _task_return_body_result(body_text: str) -> str:
    for line in body_text.splitlines():
        stripped = line.strip()
        if stripped.lower().startswith("result:"):
            return stripped.split(":", 1)[1].strip().lower()
    return ""


def _context_hash_drift_rows(root: Path, context_receipt_path: str) -> list[dict[str, Any]]:
    receipt = _read_json_file(root / context_receipt_path) if context_receipt_path else {}
    rows: list[dict[str, Any]] = []
    for item in receipt.get("required_context_reads") or []:
        if not isinstance(item, Mapping):
            continue
        rel_path = str(item.get("path") or "")
        expected = str(item.get("sha256") or item.get("sha256_expected") or "")
        if not rel_path or not expected:
            continue
        path = root / rel_path
        exists = path.is_file()
        observed = _sha256_file(path) if exists else ""
        if observed != expected:
            rows.append(
                {
                    "path": rel_path,
                    "exists": exists,
                    "sha256_expected": expected,
                    "sha256_observed": observed,
                }
            )
    return rows


def _domain_weaver_semantic_dynamic_reference_path(path: str, *, request_path: str = "") -> bool:
    if path in DOMAIN_WEAVER_SEMANTIC_REPIN_DYNAMIC_REFERENCE_PATHS:
        return True
    if request_path and path == request_path and path.startswith(
        "ION/05_context/current/chatgpt_connector/codex_work_requests/"
    ):
        return True
    return False


def _semantic_return_flags(body_text: str, drift_rows: list[Mapping[str, Any]]) -> dict[str, Any]:
    lower = body_text.lower()
    body_result = _task_return_body_result(body_text)
    blocked_phrases = [
        "blocked from authoritative settlement",
        "work is blocked",
        "execution-proof closure is blocked",
    ]
    stale_phrases = [
        "context_receipt_missing_or_stale",
        "hash drift",
        "hash-drifted",
        "stale context",
        "context staleness",
        "sha256_expected",
        "sha256_observed",
    ]
    soft_blocker = "soft governance blocker" in lower
    explicit_blocked = body_result in {"blocked", "failed", "error"} or any(
        phrase in lower for phrase in blocked_phrases
    )
    stale_context = bool(drift_rows) or any(phrase in lower for phrase in stale_phrases)
    return {
        "body_result": body_result,
        "explicit_blocked": explicit_blocked,
        "soft_blocker": soft_blocker,
        "stale_context": stale_context,
    }


def _domain_weaver_20260601b_dynamic_reference_reissue_repairs(root: Path) -> dict[str, dict[str, Any]]:
    repairs: dict[str, dict[str, Any]] = {}
    requests_dir = root / CODEX_WORK_REQUESTS_DIR
    if not requests_dir.is_dir():
        return repairs
    for path in sorted(requests_dir.glob("codex_req_domain_weaver_20260601b_dynamic_reference_reissue_*.json")):
        request = _read_json_file(path)
        if str(request.get("status") or "") != "RETURN_RECORDED_PROOF_ACCEPTED":
            continue
        source_request_id = str(_as_mapping(request.get("domain_weaver_reissue")).get("source_request_id") or "")
        latest_return_path = str(request.get("latest_return_packet_path") or "")
        latest_return = _read_json_file(root / latest_return_path) if latest_return_path else {}
        body_path = _domain_weaver_task_body_from_return_packet(latest_return)
        body_text = (root / body_path).read_text(encoding="utf-8", errors="replace") if body_path and (root / body_path).is_file() else ""
        context_receipt_path = _context_receipt_path_from_return(root, latest_return, body_path, [])
        raw_drift_rows = _context_hash_drift_rows(root, context_receipt_path)
        request_path = _rel(root, path)
        dynamic_drift_rows = [
            row
            for row in raw_drift_rows
            if _domain_weaver_semantic_dynamic_reference_path(str(row.get("path") or ""), request_path=request_path)
        ]
        blocking_drift_rows = [
            row
            for row in raw_drift_rows
            if not _domain_weaver_semantic_dynamic_reference_path(
                str(row.get("path") or ""), request_path=request_path
            )
        ]
        flags = _semantic_return_flags(body_text, blocking_drift_rows)
        declares_dynamic_reference_clean = "semantic_clean_after_dynamic_reference_policy" in body_text.lower()
        carrier_clean = bool(
            latest_return.get("accepted_for_carrier_intake") is True
            and _as_mapping(latest_return.get("context_proof_result")).get("accepted") is True
            and _as_mapping(latest_return.get("template_action_proof_result")).get("accepted") is True
            and latest_return.get("workload_diff_accepted") is True
        )
        semantic_clean = bool(
            carrier_clean
            and body_text
            and declares_dynamic_reference_clean
            and not flags["explicit_blocked"]
            and not flags["soft_blocker"]
        )
        if not source_request_id:
            continue
        repairs[source_request_id] = {
            "source_request_id": source_request_id,
            "repair_request_id": request.get("request_id"),
            "repair_request_path": request_path,
            "repair_return_packet_path": latest_return_path,
            "repair_task_return_body_path": body_path,
            "repair_context_receipt_path": context_receipt_path,
            "repair_body_result": flags["body_result"],
            "repair_declares_dynamic_reference_clean": declares_dynamic_reference_clean,
            "repair_carrier_clean": carrier_clean,
            "repair_semantic_clean": semantic_clean,
            "repair_semantic_blocked": bool(flags["explicit_blocked"]),
            "repair_semantic_soft_blocked": bool(flags["soft_blocker"] and not flags["explicit_blocked"]),
            "repair_stale_context": bool(flags["stale_context"]),
            "repair_context_hash_drift_count": len(blocking_drift_rows),
            "repair_context_hash_drift_paths": [str(row.get("path") or "") for row in blocking_drift_rows],
            "repair_dynamic_context_reference_drift_count": len(dynamic_drift_rows),
            "repair_dynamic_context_reference_drift_paths": [str(row.get("path") or "") for row in dynamic_drift_rows],
        }
    return repairs


def _domain_weaver_live_fanin_semantic_settlement(
    root: Path,
    *,
    live_return_monitor: Mapping[str, Any],
    live_fanin_settlement: Mapping[str, Any],
    materialize: bool = False,
) -> dict[str, Any]:
    settlement_summary = _as_mapping(live_fanin_settlement.get("summary"))
    return_records = [
        row for row in live_fanin_settlement.get("return_records") or [] if isinstance(row, Mapping)
    ]
    observed_by_request = {
        str(row.get("request_id") or ""): row
        for row in live_return_monitor.get("observed_returns") or []
        if isinstance(row, Mapping)
    }
    rebaseline_plan = _read_json_file(root / DOMAIN_WEAVER_LIVE_FANIN_20260601B_CONTEXT_REBASELINE_PLAN_PATH)
    rebaseline_summary = _as_mapping(rebaseline_plan.get("summary"))
    rebaseline_accepted = bool(rebaseline_summary.get("context_rebaseline_ready"))
    rebaseline_classifications = {
        str(row.get("request_id") or ""): row
        for row in rebaseline_plan.get("classification_records") or []
        if isinstance(row, Mapping)
    }
    dynamic_reissue_repairs = _domain_weaver_20260601b_dynamic_reference_reissue_repairs(root)
    semantic_records: list[dict[str, Any]] = []
    blockers: list[dict[str, Any]] = []
    context_repin_candidates: list[dict[str, Any]] = []
    for row in return_records:
        request_id = str(row.get("request_id") or "")
        observed = _as_mapping(observed_by_request.get(request_id))
        latest_return_path = str(row.get("latest_return_packet_path") or "").strip()
        latest_return = _read_json_file(root / latest_return_path) if latest_return_path else {}
        run_packets = [item for item in observed.get("run_packets") or [] if isinstance(item, Mapping)]
        body_path = _task_return_body_path_from_return(root, latest_return, run_packets)
        body_text = (root / body_path).read_text(encoding="utf-8") if body_path and (root / body_path).is_file() else ""
        context_receipt_path = _context_receipt_path_from_return(root, latest_return, body_path, run_packets)
        drift_rows = _context_hash_drift_rows(root, context_receipt_path)
        request_path = str(row.get("request_path") or "")
        dynamic_drift_rows = [
            item
            for item in drift_rows
            if _domain_weaver_semantic_dynamic_reference_path(str(item.get("path") or ""), request_path=request_path)
        ]
        blocking_drift_rows = [
            item
            for item in drift_rows
            if not _domain_weaver_semantic_dynamic_reference_path(
                str(item.get("path") or ""), request_path=request_path
            )
        ]
        flags = _semantic_return_flags(body_text, blocking_drift_rows)
        accepted = bool(row.get("accepted_return"))
        carrier_clean = bool(
            accepted
            and row.get("context_proof_accepted")
            and row.get("template_action_proof_accepted")
            and row.get("workload_diff_accepted")
        )
        missing_semantic_body = bool(accepted and not body_text)
        semantic_blocked = bool(flags["explicit_blocked"] or missing_semantic_body)
        semantic_soft_blocked = bool(flags["soft_blocker"] and not semantic_blocked)
        stale_context = bool(flags["stale_context"])
        semantic_repair_source = ""
        semantic_repair = {}
        semantic_clean = bool(
            carrier_clean
            and body_text
            and not semantic_blocked
            and not semantic_soft_blocked
            and not stale_context
        )
        classification = _as_mapping(rebaseline_classifications.get(request_id))
        if (
            rebaseline_accepted
            and classification.get("classification") == "semantic_clean_after_repin"
            and accepted
        ):
            semantic_repair_source = "20260601b_repin_stabilized_nemesis_reaudit"
            semantic_repair = {
                "classification": classification.get("classification"),
                "proof": classification.get("proof"),
                "source_reaudit_return_packet_path": rebaseline_plan.get("source_reaudit_return_packet_path"),
                "source_reaudit_task_return_body_path": rebaseline_plan.get("source_reaudit_task_return_body_path"),
            }
            semantic_clean = True
            semantic_blocked = False
            semantic_soft_blocked = False
            stale_context = False
            blocking_drift_rows = []
            flags["body_result"] = str(flags["body_result"] or "semantic_clean_after_repin")
        repair = _as_mapping(dynamic_reissue_repairs.get(request_id))
        if repair.get("repair_semantic_clean"):
            semantic_repair_source = "20260601b_dynamic_reference_reissue"
            semantic_repair = dict(repair)
            body_path = str(repair.get("repair_task_return_body_path") or body_path)
            context_receipt_path = str(repair.get("repair_context_receipt_path") or context_receipt_path)
            latest_return_path = str(repair.get("repair_return_packet_path") or latest_return_path)
            dynamic_drift_rows = [
                {"path": path}
                for path in repair.get("repair_dynamic_context_reference_drift_paths") or []
            ]
            blocking_drift_rows = []
            flags["body_result"] = str(repair.get("repair_body_result") or flags["body_result"])
            semantic_clean = True
            semantic_blocked = False
            semantic_soft_blocked = False
            stale_context = False
            missing_semantic_body = False
        if semantic_blocked:
            semantic_status = "semantic_blocked"
        elif semantic_soft_blocked:
            semantic_status = "semantic_soft_blocked"
        elif stale_context:
            semantic_status = "semantic_stale_context"
        elif semantic_repair_source == "20260601b_dynamic_reference_reissue":
            semantic_status = "semantic_clean_after_dynamic_reference_reissue"
        elif semantic_repair_source == "20260601b_repin_stabilized_nemesis_reaudit":
            semantic_status = "semantic_clean_after_repin"
        elif semantic_clean:
            semantic_status = "semantic_clean"
        elif accepted:
            semantic_status = "semantic_unverified"
        else:
            semantic_status = "carrier_return_pending"
        if blocking_drift_rows:
            context_repin_candidates.append(
                {
                    "request_id": request_id,
                    "context_receipt_path": context_receipt_path,
                    "drift_count": len(blocking_drift_rows),
                    "drifted_paths": blocking_drift_rows,
                    "dynamic_context_reference_drift_count": len(dynamic_drift_rows),
                    "dynamic_context_reference_drift_paths": dynamic_drift_rows,
                }
            )
        semantic_records.append(
            {
                "request_id": request_id,
                "request_path": request_path,
                "lane_id": row.get("lane_id"),
                "latest_return_packet_path": latest_return_path,
                "task_return_body_path": body_path,
                "context_receipt_path": context_receipt_path,
                "carrier_accepted": accepted,
                "carrier_clean": carrier_clean,
                "body_result": flags["body_result"],
                "semantic_status": semantic_status,
                "semantic_clean": semantic_clean,
                "semantic_blocked": semantic_blocked,
                "semantic_soft_blocked": semantic_soft_blocked,
                "stale_context": stale_context,
                "missing_semantic_body": missing_semantic_body,
                "context_hash_drift_count": len(blocking_drift_rows),
                "context_hash_drift_paths": [item["path"] for item in blocking_drift_rows],
                "raw_context_hash_drift_count": len(drift_rows),
                "raw_context_hash_drift_paths": [item["path"] for item in drift_rows],
                "dynamic_context_reference_drift_count": len(dynamic_drift_rows),
                "dynamic_context_reference_drift_paths": [item["path"] for item in dynamic_drift_rows],
                "semantic_repair_source": semantic_repair_source,
                "semantic_repair": semantic_repair,
            }
        )
    expected_count = int(settlement_summary.get("expected_return_count") or len(return_records))
    semantic_clean_count = sum(1 for row in semantic_records if row.get("semantic_clean"))
    semantic_blocked_count = sum(1 for row in semantic_records if row.get("semantic_blocked"))
    semantic_soft_blocked_count = sum(1 for row in semantic_records if row.get("semantic_soft_blocked"))
    stale_context_return_count = sum(1 for row in semantic_records if row.get("stale_context"))
    missing_semantic_body_count = sum(1 for row in semantic_records if row.get("missing_semantic_body"))
    context_hash_drift_return_count = sum(1 for row in semantic_records if row.get("context_hash_drift_count"))
    context_hash_drift_path_count = sum(int(row.get("context_hash_drift_count") or 0) for row in semantic_records)
    dynamic_context_reference_drift_return_count = sum(
        1 for row in semantic_records if row.get("dynamic_context_reference_drift_count")
    )
    dynamic_context_reference_drift_path_count = sum(
        int(row.get("dynamic_context_reference_drift_count") or 0) for row in semantic_records
    )
    semantic_settlement_complete = bool(
        expected_count
        and bool(settlement_summary.get("settlement_complete"))
        and semantic_clean_count == expected_count
        and semantic_blocked_count == 0
        and semantic_soft_blocked_count == 0
        and stale_context_return_count == 0
        and missing_semantic_body_count == 0
        and context_hash_drift_path_count == 0
    )
    if semantic_blocked_count:
        blockers.append(
            {
                "code": "LIVE_RETURN_SEMANTIC_BLOCKER",
                "severity": "critical",
                "detail": "At least one carrier-accepted return reports a semantic blocker or lacks a semantic return body.",
            }
        )
    if semantic_soft_blocked_count:
        blockers.append(
            {
                "code": "LIVE_RETURN_SEMANTIC_SOFT_BLOCKER",
                "severity": "high",
                "detail": "At least one carrier-accepted return reports a soft governance blocker.",
            }
        )
    if stale_context_return_count:
        blockers.append(
            {
                "code": "LIVE_RETURN_CONTEXT_STALE",
                "severity": "critical",
                "detail": "At least one carrier-accepted return has stale context or context receipt hash drift.",
            }
        )
    if expected_count and semantic_clean_count < expected_count and not blockers:
        blockers.append(
            {
                "code": "LIVE_RETURN_SEMANTIC_UNVERIFIED",
                "severity": "high",
                "detail": "Carrier returns are present, but Domain Weaver has not proven semantic-clean settlement.",
            }
        )
    semantic_settlement = {
        "schema_id": "ion.domain_weaver.live_fanin_semantic_settlement.v0_1_candidate",
        "created_at": _now(),
        "status": (
            "live_fanin_semantic_settlement_complete"
            if semantic_settlement_complete
            else "live_fanin_semantic_settlement_blocked"
            if blockers
            else "live_fanin_semantic_settlement_waiting"
        ),
        "semantic_settlement_ready": True,
        "semantic_settlement_complete": semantic_settlement_complete,
        "source_return_monitor_path": DOMAIN_WEAVER_LIVE_RETURN_MONITOR_PATH.as_posix(),
        "source_fanin_settlement_path": DOMAIN_WEAVER_LIVE_FANIN_SETTLEMENT_PATH.as_posix(),
        "semantic_return_records": semantic_records,
        "context_repin_candidates": context_repin_candidates,
        "blockers": blockers,
        "parent_decision": {
            "decision": (
                "advance_to_recursive_live_domain_weaver_cycle"
                if semantic_settlement_complete
                else "repin_context_and_resettle_semantic_fanin_before_recursive_cycle"
            ),
            "reason": (
                "All expected live fanout returns are carrier-accepted and semantically clean with current context receipts."
                if semantic_settlement_complete
                else "Carrier fan-in is not enough: at least one return is semantically blocked, stale, or unverified."
            ),
            "next_packet": (
                {
                    "packet_id": "PCKT-DOMAIN-WEAVER-RECURSIVE-LIVE-FANOUT-CHAIN-MVP-20260601",
                    "lane_id": "settlement_lane",
                    "work_class": "settlement",
                    "recommended_worker": "role.nemesis",
                    "objective": (
                        "Use the semantic-clean live fan-in settlement to select the next recursive Domain Weaver cycle, "
                        "enforce token and chain thresholds, and preserve candidate-only authority."
                    ),
                }
                if semantic_settlement_complete
                else {
                    "packet_id": "PCKT-DOMAIN-WEAVER-LIVE-FANIN-SEMANTIC-SETTLEMENT-AND-REPIN-20260601",
                    "lane_id": "settlement_lane",
                    "work_class": "settlement",
                    "recommended_worker": "role.nemesis",
                    "objective": (
                        "Read all accepted Domain Weaver live fanout returns, classify carrier-accepted versus "
                        "semantically clean or blocked, repin stale required context, and only then authorize "
                        "recursive fanout."
                    ),
                }
            ),
        },
        "summary": {
            "semantic_settlement_ready": True,
            "semantic_settlement_complete": semantic_settlement_complete,
            "expected_return_count": expected_count,
            "semantic_return_count": len(semantic_records),
            "semantic_clean_return_count": semantic_clean_count,
            "semantic_blocked_return_count": semantic_blocked_count,
            "semantic_soft_blocked_return_count": semantic_soft_blocked_count,
            "stale_context_return_count": stale_context_return_count,
            "missing_semantic_body_count": missing_semantic_body_count,
            "context_hash_drift_return_count": context_hash_drift_return_count,
            "context_hash_drift_path_count": context_hash_drift_path_count,
            "dynamic_context_reference_drift_return_count": dynamic_context_reference_drift_return_count,
            "dynamic_context_reference_drift_path_count": dynamic_context_reference_drift_path_count,
            "context_repin_required": bool(
                stale_context_return_count
                or missing_semantic_body_count
                or context_hash_drift_path_count
                or semantic_blocked_count
                or semantic_soft_blocked_count
            ),
            "blocker_count": len(blockers),
        },
        "authority": {
            "candidate_semantic_settlement_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    if materialize:
        path = root / DOMAIN_WEAVER_LIVE_FANIN_SEMANTIC_SETTLEMENT_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(semantic_settlement, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        semantic_settlement["semantic_settlement_path"] = (
            DOMAIN_WEAVER_LIVE_FANIN_SEMANTIC_SETTLEMENT_PATH.as_posix()
        )
        semantic_settlement["materialized_paths"] = [
            DOMAIN_WEAVER_LIVE_FANIN_SEMANTIC_SETTLEMENT_PATH.as_posix()
        ]
    else:
        semantic_settlement["semantic_settlement_path"] = (
            DOMAIN_WEAVER_LIVE_FANIN_SEMANTIC_SETTLEMENT_PATH.as_posix()
        )
        semantic_settlement["materialized_paths"] = []
    return semantic_settlement


def _current_context_pin_rows(root: Path, context_receipt_path: str) -> list[dict[str, Any]]:
    receipt = _read_json_file(root / context_receipt_path) if context_receipt_path else {}
    rows: list[dict[str, Any]] = []
    for item in receipt.get("required_context_reads") or []:
        if not isinstance(item, Mapping):
            continue
        rel_path = str(item.get("path") or "")
        if not rel_path:
            continue
        expected = str(item.get("sha256") or item.get("sha256_expected") or "")
        path = root / rel_path
        exists = path.is_file()
        observed = _sha256_file(path) if exists else ""
        drifted = bool(expected and observed != expected)
        rows.append(
            {
                "path": rel_path,
                "exists": exists,
                "sha256_previous": expected,
                "sha256_current": observed,
                "changed_since_context_receipt": drifted,
                "repin_sha256": observed if exists else expected,
                "repin_status": "current_hash_pinned" if exists else "missing_context_path",
            }
        )
    return rows


def _domain_weaver_live_fanin_semantic_repin_plan(
    root: Path,
    *,
    live_fanin_semantic_settlement: Mapping[str, Any],
    materialize: bool = False,
) -> dict[str, Any]:
    semantic_records = [
        row
        for row in live_fanin_semantic_settlement.get("semantic_return_records") or []
        if isinstance(row, Mapping)
    ]
    semantic_by_request = {str(row.get("request_id") or ""): row for row in semantic_records}
    repin_candidates = [
        row
        for row in live_fanin_semantic_settlement.get("context_repin_candidates") or []
        if isinstance(row, Mapping)
    ]
    repin_records: list[dict[str, Any]] = []
    total_pin_count = 0
    total_drifted_pin_count = 0
    total_dynamic_reference_count = 0
    total_dynamic_reference_drift_count = 0
    for candidate in repin_candidates:
        request_id = str(candidate.get("request_id") or "")
        semantic = _as_mapping(semantic_by_request.get(request_id))
        context_receipt_path = str(candidate.get("context_receipt_path") or "")
        all_pin_rows = _current_context_pin_rows(root, context_receipt_path)
        request_path = str(semantic.get("request_path") or "")
        dynamic_context_references = [
            {
                **row,
                "repin_status": "dynamic_context_reference_not_immutable_pin",
                "repin_gate_excluded": True,
                "reason": "Self-updating Domain Weaver operational output is evidence, not an immutable repin gate.",
            }
            for row in all_pin_rows
            if _domain_weaver_semantic_dynamic_reference_path(
                str(row.get("path") or ""), request_path=request_path
            )
        ]
        pin_rows = [
            row
            for row in all_pin_rows
            if not _domain_weaver_semantic_dynamic_reference_path(
                str(row.get("path") or ""), request_path=request_path
            )
        ]
        drifted_pin_count = sum(1 for row in pin_rows if row.get("changed_since_context_receipt"))
        dynamic_drift_count = sum(1 for row in dynamic_context_references if row.get("changed_since_context_receipt"))
        total_pin_count += len(pin_rows)
        total_drifted_pin_count += drifted_pin_count
        total_dynamic_reference_count += len(dynamic_context_references)
        total_dynamic_reference_drift_count += dynamic_drift_count
        semantic_blocked = bool(semantic.get("semantic_blocked"))
        semantic_soft_blocked = bool(semantic.get("semantic_soft_blocked"))
        if semantic_blocked:
            followup_action = "repin_then_nemesis_reaudit_blocked_return"
        elif semantic_soft_blocked:
            followup_action = "repin_then_nemesis_reaudit_soft_blocker"
        else:
            followup_action = "repin_then_nemesis_reaudit_stale_context"
        repin_records.append(
            {
                "request_id": request_id,
                "request_path": semantic.get("request_path"),
                "lane_id": semantic.get("lane_id"),
                "semantic_status": semantic.get("semantic_status"),
                "body_result": semantic.get("body_result"),
                "semantic_blocked": semantic_blocked,
                "semantic_soft_blocked": semantic_soft_blocked,
                "stale_context": bool(semantic.get("stale_context")),
                "latest_return_packet_path": semantic.get("latest_return_packet_path"),
                "task_return_body_path": semantic.get("task_return_body_path"),
                "context_receipt_path": context_receipt_path,
                "source_drift_count": int(candidate.get("drift_count") or drifted_pin_count),
                "current_pin_count": len(pin_rows),
                "current_drifted_pin_count": drifted_pin_count,
                "current_context_pins": pin_rows,
                "dynamic_context_reference_count": len(dynamic_context_references),
                "dynamic_context_reference_drift_count": dynamic_drift_count,
                "dynamic_context_references": dynamic_context_references,
                "followup_action": followup_action,
                "writeback_performed": False,
                "reissued_worker_started": False,
                "accepted_state_authority": False,
            }
        )
    semantic_summary = _as_mapping(live_fanin_semantic_settlement.get("summary"))
    repin_required = bool(semantic_summary.get("context_repin_required"))
    repin_plan_ready = bool(repin_records or not repin_required)
    blocked_return_count = sum(1 for row in repin_records if row.get("semantic_blocked"))
    soft_blocked_return_count = sum(1 for row in repin_records if row.get("semantic_soft_blocked"))
    stale_only_return_count = sum(
        1
        for row in repin_records
        if row.get("stale_context") and not row.get("semantic_blocked") and not row.get("semantic_soft_blocked")
    )
    reauditable_return_count = len(repin_records)
    plan = {
        "schema_id": "ion.domain_weaver.live_fanin_semantic_repin_plan.v0_1_candidate",
        "created_at": _now(),
        "status": (
            "semantic_repin_plan_ready"
            if repin_required and repin_plan_ready
            else "semantic_repin_not_required"
            if not repin_required
            else "semantic_repin_plan_blocked"
        ),
        "semantic_repin_plan_ready": repin_plan_ready,
        "source_semantic_settlement_path": DOMAIN_WEAVER_LIVE_FANIN_SEMANTIC_SETTLEMENT_PATH.as_posix(),
        "dynamic_context_reference_policy": {
            "excluded_from_immutable_repin_gate": sorted(DOMAIN_WEAVER_SEMANTIC_REPIN_DYNAMIC_REFERENCE_PATHS),
            "reason": (
                "Generated Domain Weaver operational artifacts can be rewritten by queue, run, and projection "
                "materialization after a context receipt is assembled. They remain evidence references but do not "
                "block the stable repin gate."
            ),
        },
        "repin_records": repin_records,
        "parent_decision": {
            "decision": (
                "route_repin_plan_to_nemesis_reaudit"
                if repin_required and repin_plan_ready
                else "semantic_settlement_clean_no_repin_required"
                if not repin_required
                else "continue_semantic_repin_plan_repair"
            ),
            "reason": (
                "Current context hashes have been captured as candidate pins; Nemesis must re-audit before recursive fanout."
                if repin_required and repin_plan_ready
                else "No stale semantic fan-in context requires repinning."
                if not repin_required
                else "Domain Weaver could not build a complete candidate repin plan."
            ),
            "next_packet": (
                {
                    "packet_id": "PCKT-DOMAIN-WEAVER-LIVE-FANIN-REPINNED-NEMESIS-REAUDIT-20260601",
                    "lane_id": "settlement_lane",
                    "work_class": "settlement",
                    "recommended_worker": "role.nemesis",
                    "objective": (
                        "Use the Domain Weaver semantic repin plan to re-audit all carrier-accepted live fanout "
                        "returns against current required context hashes, classify blocked versus clean returns, "
                        "and decide reissue/supersede/recursive-fanout readiness without accepted-state authority."
                    ),
                }
                if repin_required and repin_plan_ready
                else {}
            ),
        },
        "summary": {
            "semantic_repin_plan_ready": repin_plan_ready,
            "context_repin_required": repin_required,
            "repin_record_count": len(repin_records),
            "current_context_pin_count": total_pin_count,
            "current_drifted_pin_count": total_drifted_pin_count,
            "dynamic_context_reference_count": total_dynamic_reference_count,
            "dynamic_context_reference_drift_count": total_dynamic_reference_drift_count,
            "blocked_return_reaudit_count": blocked_return_count,
            "soft_blocked_return_reaudit_count": soft_blocked_return_count,
            "stale_only_return_reaudit_count": stale_only_return_count,
            "reauditable_return_count": reauditable_return_count,
            "writeback_performed_count": 0,
            "reissued_worker_started_count": 0,
        },
        "authority": {
            "candidate_repin_plan_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    if materialize:
        path = root / DOMAIN_WEAVER_LIVE_FANIN_SEMANTIC_REPIN_PLAN_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(plan, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        plan["repin_plan_path"] = DOMAIN_WEAVER_LIVE_FANIN_SEMANTIC_REPIN_PLAN_PATH.as_posix()
        plan["materialized_paths"] = [DOMAIN_WEAVER_LIVE_FANIN_SEMANTIC_REPIN_PLAN_PATH.as_posix()]
    else:
        plan["repin_plan_path"] = DOMAIN_WEAVER_LIVE_FANIN_SEMANTIC_REPIN_PLAN_PATH.as_posix()
        plan["materialized_paths"] = []
    return plan


