def _self_hydrate_domain_weaver_inputs(
    root: Path,
    *,
    agents: list[Mapping[str, Any]] | None,
    domains: list[Mapping[str, Any]] | None,
    codex_mounts: Mapping[str, Any] | None,
    roster: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Load the same registry-backed inputs used by the Agent Control Plane.

    Imports stay lazy so Agent Control Plane can continue importing Domain
    Weaver without a module-load cycle. When callers pass any input explicitly,
    that input remains authoritative for the current projection.
    """
    from .ion_agent_control_plane import _agent_rows, _domain_rows
    from .ion_agent_invocation_broker import agent_queue
    from .ion_agent_spawn_templates import build_agent_roster_projection
    from .ion_codex_agent_mount import build_codex_agent_mounts_projection

    queue = agent_queue(root, limit=50)
    domain_rows = list(domains) if domains is not None else _domain_rows(root)
    agent_rows = list(agents) if agents is not None else _agent_rows(root, queue)
    mounts = dict(codex_mounts) if isinstance(codex_mounts, Mapping) else build_codex_agent_mounts_projection(root, agent_rows, domain_rows)
    roster_projection = (
        dict(roster)
        if isinstance(roster, Mapping)
        else build_agent_roster_projection(root, agents=agent_rows, domains=domain_rows)
    )
    return {
        "mode": "self_hydrated",
        "agent_queue_summary": {
            "invocation_count": queue.get("invocation_count", 0),
            "queued_agent_codex_work_request_count": queue.get("queued_agent_codex_work_request_count", 0),
        },
        "agents": agent_rows,
        "domains": domain_rows,
        "codex_mounts": mounts,
        "roster": roster_projection,
    }


def _dogfood_context_capsule_markdown(capsule: Mapping[str, Any]) -> str:
    summary = _as_mapping(capsule.get("summary"))
    next_packet = _as_mapping(capsule.get("next_packet"))
    read_refs = [row for row in capsule.get("read_refs") or [] if isinstance(row, Mapping)]
    recent_receipts = [row for row in capsule.get("recent_receipt_refs") or [] if isinstance(row, Mapping)]
    lines = [
        "# Domain Weaver Dogfood Context Capsule",
        "",
        f"- status: {capsule.get('status')}",
        f"- capsule_id: {capsule.get('capsule_id')}",
        f"- projection: {DOMAIN_WEAVER_PROJECTION_PATH.as_posix()}",
        f"- queue_governance_status: {summary.get('queue_governance_status')}",
        f"- queue_governor_dogfood_status: {summary.get('queue_governor_dogfood_status')}",
        f"- queue_governor_dogfood_passed_scenarios: {summary.get('queue_governor_dogfood_passed_scenario_count')}/{summary.get('queue_governor_dogfood_scenario_count')}",
        f"- waiting_request_count: {summary.get('waiting_request_count')}",
        f"- work_lane_waiting_request_count: {summary.get('work_lane_waiting_request_count')}",
        f"- worker_concurrency_ready: {summary.get('worker_concurrency_ready')}",
        f"- ui_development_status: {summary.get('ui_development_status')}",
        f"- next_packet: {next_packet.get('packet_id')} ({next_packet.get('lane_id')})",
        "",
        "## Authority",
        "",
        "- production_authority: false",
        "- live_execution_authority: false",
        "- accepted_state_authority: false",
        "- secrets_authority: false",
        "",
        "## Required Reads",
        "",
    ]
    for ref in read_refs:
        exists = "yes" if ref.get("exists") else "no"
        sha = str(ref.get("sha256") or "missing")
        lines.append(f"- {ref.get('path')} exists={exists} sha256={sha}")
    lines.extend(["", "## Recent Receipts", ""])
    for ref in recent_receipts[:12]:
        lines.append(f"- {ref.get('path')} sha256={ref.get('sha256')}")
    lines.extend(["", "## Next Packet", "", "```json", json.dumps(next_packet, indent=2, sort_keys=True), "```", ""])
    return "\n".join(lines)


def build_domain_weaver_dogfood_context_capsule(
    root: str | Path | None = None,
    projection: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    shell_root = _resolve_root(root)
    source_projection = dict(projection or {})
    projection_file = _read_json_file(shell_root / DOMAIN_WEAVER_PROJECTION_PATH)
    if not source_projection:
        source_projection = projection_file or build_domain_weaver_projection(shell_root)
    operating_loop = _as_mapping(source_projection.get("operating_loop"))
    queue_governance = _as_mapping(source_projection.get("queue_governance"))
    queue_summary = _as_mapping(queue_governance.get("summary"))
    ui_development = _as_mapping(source_projection.get("ui_development"))
    ui_summary = _as_mapping(ui_development.get("summary"))
    read_refs = [
        _file_ref(shell_root, DOMAIN_WEAVER_PROJECTION_PATH, "Domain Weaver operating projection."),
        _file_ref(shell_root, DOMAIN_WEAVER_PROMOTION_REVIEW_PATH, "Candidate promotion review posture."),
        _file_ref(shell_root, DOMAIN_WEAVER_PROMOTION_GATE_PATH, "Candidate promotion gate posture."),
        _file_ref(shell_root, AGENT_COMMS_DIRECTORY_PATH, "Agent communication directory and comms availability."),
        _file_ref(shell_root, ACTIVE_CARRIER_MESSAGE_QUEUE_PATH, "Carrier message queue posture.", required=False),
        _file_ref(shell_root, CODEX_WORK_QUEUE_PATH, "Codex work queue currentness projection."),
        _file_ref(shell_root, CODEX_WORK_LANE_INDEX_PATH, "Codex work lane projection."),
        _file_ref(shell_root, CODEX_QUEUE_RUNNER_STATE_PATH, "Codex queue runner active/terminal state."),
        _file_ref(shell_root, DOMAIN_WEAVER_COCKPIT_PAGE_PATH, "Domain Weaver top-level cockpit page source."),
        _file_ref(shell_root, DOMAIN_WEAVER_COCKPIT_SHELL_PATH, "JOC cockpit hash route source."),
        _file_ref(shell_root, DOMAIN_WEAVER_COCKPIT_PANEL_PATH, "Legacy agent tab Domain Weaver source."),
        _file_ref(
            shell_root,
            DOMAIN_WEAVER_ROOT / "queue_governance/LATEST_QUEUE_CURRENTNESS_RECONCILIATION.json",
            "Latest Domain Weaver queue-currentness reconciliation digest.",
            required=False,
        ),
    ]
    recent_receipts = (
        _latest_json_refs(shell_root, DOMAIN_WEAVER_RECEIPT_DIR, reason="Recent Domain Weaver materialization receipt.", limit=6)
        + _latest_json_refs(shell_root, CODEX_TASK_RETURNS_DIR, reason="Recent Codex task return receipt.", limit=4)
        + _latest_json_refs(
            shell_root,
            CODEX_TASK_RETURN_MACHINE_RECEIPTS_DIR,
            reason="Recent Codex task return machine receipt.",
            limit=4,
        )
        + _latest_queue_run_refs(shell_root, limit=4)
    )
    next_packet = _select_dogfood_next_packet(source_projection)
    blocker_count = int(_as_mapping(operating_loop.get("summary")).get("blocker_count") or 0)
    queue_status = str(queue_governance.get("status") or "queue_governance_missing")
    status = "DOGFOOD_CONTEXT_READY" if blocker_count == 0 and queue_status == "queue_governance_ready" else "DOGFOOD_CONTEXT_NEEDS_ATTENTION"
    return {
        "schema_id": DOGFOOD_CONTEXT_CAPSULE_SCHEMA_ID,
        "capsule_id": f"domain_weaver_dogfood_context_{_stamp()}",
        "created_at": _now(),
        "status": status,
        "active_root": shell_root.as_posix(),
        "projection_path": DOMAIN_WEAVER_PROJECTION_PATH.as_posix(),
        "projection_sha256": _sha256_file(shell_root / DOMAIN_WEAVER_PROJECTION_PATH)
        if (shell_root / DOMAIN_WEAVER_PROJECTION_PATH).is_file()
        else "",
        "summary": {
            "weave_status": source_projection.get("weave_status"),
            "operating_loop_status": operating_loop.get("status"),
            "queue_governance_status": queue_status,
            "queue_governor_dogfood_status": queue_summary.get("queue_governor_dogfood_status", "missing"),
            "queue_governor_dogfood_scenario_count": queue_summary.get("queue_governor_dogfood_scenario_count", 0),
            "queue_governor_dogfood_passed_scenario_count": queue_summary.get("queue_governor_dogfood_passed_scenario_count", 0),
            "queue_governor_dogfood_covered_behavior_count": queue_summary.get("queue_governor_dogfood_covered_behavior_count", 0),
            "waiting_request_count": queue_summary.get("waiting_request_count", 0),
            "stale_waiting_request_count": queue_summary.get("stale_waiting_request_count", 0),
            "terminal_repair_request_count": queue_summary.get("terminal_repair_request_count", 0),
            "active_run_count": queue_summary.get("active_run_count", 0),
            "work_lane_projection_ready": queue_summary.get("work_lane_projection_ready", False),
            "worker_concurrency_ready": queue_summary.get("worker_concurrency_ready", False),
            "ui_development_status": ui_development.get("status", "missing"),
            "ui_development_ready": ui_development.get("status") == "ui_development_ready",
            "ui_development_dist_bundle_current": ui_summary.get("dist_bundle_mentions_domain_weaver", False),
            "ui_native_domain_route_ready": ui_summary.get("native_ui_domain_route_ready", False),
            "ui_work_surface_architecture_ready": ui_summary.get("work_surface_architecture_ready", False),
            "ui_operator_usable": ui_summary.get("operator_usable", False),
            "work_lane_waiting_request_count": queue_summary.get("work_lane_waiting_request_count", 0),
            "work_lane_needs_triage_count": queue_summary.get("work_lane_needs_triage_count", 0),
            "operating_loop_next_packet_count": _as_mapping(operating_loop.get("summary")).get("next_packet_count", 0),
        },
        "read_refs": read_refs,
        "recent_receipt_refs": recent_receipts,
        "operating_loop": operating_loop.get("loop") or [],
        "queue_currentness": {
            "status": queue_status,
            "summary": queue_summary,
            "work_lane_counts": queue_governance.get("work_lane_counts") or {},
            "findings": queue_governance.get("findings") or [],
        },
        "next_packet": next_packet,
        "write_scope": {
            "allowed": [DOMAIN_WEAVER_DOGFOOD_CONTEXT_DIR.as_posix()],
            "forbidden": [
                "ION/03_registry/domains/",
                "production",
                "Supabase",
                "secrets",
                "accepted_state",
            ],
        },
        "authority": {
            "candidate_projection_only": True,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "non_claims": {
            "accepted_state_claim": False,
            "registry_promotion_claim": False,
            "production_claim": False,
            "live_execution_claim": False,
            "secrets_claim": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }


def _authority_boundary_clean(*payloads: Mapping[str, Any]) -> bool:
    for payload in payloads:
        authority = _as_mapping(payload.get("authority"))
        for key in ("production_authority", "live_execution_authority", "accepted_state_authority", "secrets_authority"):
            if payload.get(key) is True or authority.get(key) is True:
                return False
    return True


def _steward_ready_review_markdown(review: Mapping[str, Any]) -> str:
    summary = _as_mapping(review.get("summary"))
    criteria = [row for row in review.get("criteria") or [] if isinstance(row, Mapping)]
    blockers = [row for row in review.get("blockers") or [] if isinstance(row, Mapping)]
    candidates = [row for row in review.get("next_evolution_candidates") or [] if isinstance(row, Mapping)]
    lines = [
        "# Domain Weaver Steward Ready Review",
        "",
        f"- decision: {review.get('decision')}",
        f"- review_status: {review.get('review_status')}",
        f"- queue_governance_status: {summary.get('queue_governance_status')}",
        f"- waiting_request_count: {summary.get('waiting_request_count')}",
        f"- worker_concurrency_ready: {summary.get('worker_concurrency_ready')}",
        f"- ui_development_status: {summary.get('ui_development_status')}",
        f"- current_capability_class: {summary.get('current_capability_class')}",
        f"- full_domain_weaver_ready: {summary.get('full_domain_weaver_ready')}",
        f"- original_plan_blocker_count: {summary.get('original_plan_blocker_count')}",
        f"- operating_loop_next_packet_count: {summary.get('operating_loop_next_packet_count')}",
        "",
        "This is a candidate settlement review. It does not claim accepted state, production authority, live execution authority, or registry promotion.",
        "",
        "## Criteria",
        "",
    ]
    for criterion in criteria:
        verdict = "PASS" if criterion.get("passed") else "BLOCK"
        lines.append(f"- {verdict}: {criterion.get('code')} - {criterion.get('detail')}")
    lines.extend(["", "## Blockers", ""])
    if blockers:
        for blocker in blockers:
            lines.append(f"- {blocker.get('code')}: {blocker.get('detail')}")
    else:
        lines.append("- none")
    lines.extend(["", "## Next Evolution Candidates", ""])
    for candidate in candidates:
        lines.append(f"- {candidate.get('packet_id')} ({candidate.get('lane_id')}): {candidate.get('objective')}")
    if not candidates:
        lines.append("- none")
    lines.extend(["", "## Evidence", ""])
    for ref in review.get("evidence_refs") or []:
        if isinstance(ref, Mapping):
            lines.append(f"- {ref.get('path')} sha256={ref.get('sha256', '')}")
    lines.append("")
    return "\n".join(lines)


