def _file_ref_from_runtime_path(root: Path, value: Any, reason: str, *, required: bool = True) -> dict[str, Any]:
    text = str(value or "").strip()
    if not text:
        return {
            "path": "",
            "exists": False,
            "required": required,
            "reason": reason,
        }
    path = Path(text)
    absolute_path = path if path.is_absolute() else root / path
    ref: dict[str, Any] = {
        "path": _rel(root, absolute_path),
        "exists": absolute_path.is_file(),
        "required": required,
        "reason": reason,
    }
    if absolute_path.is_file():
        ref["sha256"] = _sha256_file(absolute_path)
    return ref


def _runtime_path_exists(root: Path, value: Any) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    path = Path(text)
    return (path if path.is_absolute() else root / path).is_file()


def _phase_closure_review_markdown(review: Mapping[str, Any]) -> str:
    summary = _as_mapping(review.get("summary"))
    criteria = [row for row in review.get("criteria") or [] if isinstance(row, Mapping)]
    blockers = [row for row in review.get("blockers") or [] if isinstance(row, Mapping)]
    packet = _as_mapping(review.get("reviewed_packet"))
    lines = [
        "# Domain Weaver Steward Phase Closure Review",
        "",
        f"- decision: {review.get('decision')}",
        f"- review_status: {review.get('review_status')}",
        f"- reviewed_packet_id: {packet.get('packet_id')}",
        f"- steward_ready_decision: {summary.get('steward_ready_decision')}",
        f"- action_history_record_count: {summary.get('action_history_record_count')}",
        f"- visual_smoke_ok: {summary.get('visual_smoke_ok')}",
        "",
        "This is candidate review only. It does not close accepted state, mutate active registries, run live workers, or grant production authority.",
        "",
        "## Criteria",
        "",
    ]
    for criterion in criteria:
        verdict = "PASS" if criterion.get("passed") else "BLOCK"
        lines.append(f"- {verdict}: {criterion.get('code')} - {criterion.get('detail')}")
    lines.extend(["", "## Blockers", ""])
    if blockers:
        for blocker in blockers:
            lines.append(f"- {blocker.get('code')}: {blocker.get('detail')}")
    else:
        lines.append("- none")
    lines.extend(["", "## Evidence", ""])
    for ref in review.get("evidence_refs") or []:
        if isinstance(ref, Mapping):
            lines.append(f"- {ref.get('path')} sha256={ref.get('sha256', '')}")
    lines.append("")
    return "\n".join(lines)


def build_domain_weaver_phase_closure_review(
    root: str | Path | None = None,
    steward_ready_review: Mapping[str, Any] | None = None,
    visual_smoke: Mapping[str, Any] | None = None,
    action_history: Mapping[str, Any] | None = None,
    next_packet: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    shell_root = _resolve_root(root)
    source_review = dict(steward_ready_review or _read_json_file(shell_root / DOMAIN_WEAVER_STEWARD_READY_REVIEW_PATH))
    source_visual = dict(visual_smoke or _read_json_file(shell_root / DOMAIN_WEAVER_ACTION_HISTORY_VISUAL_SMOKE_RECEIPT_PATH))
    source_history = dict(action_history or _load_domain_weaver_operator_action_history(shell_root))
    source_packet = dict(next_packet or _read_json_file(shell_root / DOMAIN_WEAVER_DOGFOOD_NEXT_PACKET_PATH))
    review_summary = _as_mapping(source_review.get("summary"))
    phase_candidate = _as_mapping(source_review.get("phase_closure_candidate"))
    history_summary = _as_mapping(source_history.get("summary"))
    records = [row for row in source_history.get("records") or [] if isinstance(row, Mapping)]
    record_count = int(history_summary.get("record_count") or source_history.get("record_count") or len(records) or 0)
    latest_ok = history_summary.get("latest_ok") is True
    visual_receipt_path = str(source_visual.get("receipt_path") or DOMAIN_WEAVER_ACTION_HISTORY_VISUAL_SMOKE_RECEIPT_PATH.as_posix())
    visual_screenshot_path = str(source_visual.get("screenshot_path") or source_visual.get("screenshot") or "")
    visual_receipt_exists = _runtime_path_exists(shell_root, visual_receipt_path)
    visual_screenshot_exists = _runtime_path_exists(shell_root, visual_screenshot_path)
    visual_hash_route = str(source_visual.get("hash_route") or source_visual.get("route_hash") or "")
    visual_ok = source_visual.get("ok") is True
    packet_id = str(source_packet.get("packet_id") or review_summary.get("capsule_next_packet_id") or "")
    worker = str(source_packet.get("recommended_worker") or "")
    criteria = [
        {
            "code": "STEWARD_READY_REVIEW_READY",
            "passed": source_review.get("review_status") == "ready_for_phase_closure_candidate",
            "detail": str(source_review.get("review_status") or "missing"),
        },
        {
            "code": "STEWARD_DECISION_IS_CANDIDATE_CLOSURE",
            "passed": source_review.get("decision") == "candidate_close_domain_weaver_queue_hygiene_phase",
            "detail": str(source_review.get("decision") or "missing"),
        },
        {
            "code": "STEWARD_PACKET_SELECTED",
            "passed": packet_id == "PCKT-DOMAIN-WEAVE-STEWARD-READY-REVIEW-20260531"
            and str(source_packet.get("lane_id") or "") == "settlement_lane"
            and worker == "role.steward",
            "detail": f"packet={packet_id or 'missing'} lane={source_packet.get('lane_id', 'missing')} worker={worker or 'missing'}",
        },
        {
            "code": "ACTION_HISTORY_PRESENT",
            "passed": record_count > 0,
            "detail": f"record_count={record_count}",
        },
        {
            "code": "ACTION_HISTORY_LATEST_OK",
            "passed": latest_ok,
            "detail": f"latest_action={history_summary.get('latest_action', 'missing')} latest_ok={history_summary.get('latest_ok', False)}",
        },
        {
            "code": "VISUAL_SMOKE_RECEIPT_PRESENT",
            "passed": visual_receipt_exists,
            "detail": visual_receipt_path,
        },
        {
            "code": "VISUAL_SMOKE_PASSED_ON_WEAVE_ROUTE",
            "passed": visual_ok and visual_hash_route == "#weave",
            "detail": f"ok={source_visual.get('ok', False)} hash_route={visual_hash_route or 'missing'}",
        },
        {
            "code": "VISUAL_SMOKE_SCREENSHOT_PRESENT",
            "passed": visual_screenshot_exists,
            "detail": visual_screenshot_path or "missing",
        },
        {
            "code": "NO_ACCEPTED_STATE_CLAIM",
            "passed": phase_candidate.get("accepted_state_claim") is not True,
            "detail": f"accepted_state_claim={phase_candidate.get('accepted_state_claim', False)}",
        },
        {
            "code": "AUTHORITY_BOUNDARY_CLEAN",
            "passed": _authority_boundary_clean(source_review, source_packet, source_visual, source_history),
            "detail": "production/live/accepted-state/secrets authority remain false",
        },
    ]
    blockers = [
        {"code": str(row.get("code") or "UNKNOWN"), "detail": str(row.get("detail") or "")}
        for row in criteria
        if not row.get("passed")
    ]
    ready = not blockers
    evidence_refs = [
        _file_ref(shell_root, DOMAIN_WEAVER_STEWARD_READY_REVIEW_PATH, "Steward ready review candidate."),
        _file_ref(shell_root, DOMAIN_WEAVER_DOGFOOD_NEXT_PACKET_PATH, "Selected Steward settlement packet."),
        _file_ref(shell_root, DOMAIN_WEAVER_OPERATOR_ACTION_HISTORY_PATH, "Durable operator action history."),
        _file_ref_from_runtime_path(shell_root, visual_receipt_path, "Browser visual smoke receipt."),
        _file_ref_from_runtime_path(shell_root, visual_screenshot_path, "Browser visual smoke screenshot.", required=False),
    ]
    return {
        "schema_id": PHASE_CLOSURE_REVIEW_SCHEMA_ID,
        "created_at": _now(),
        "review_status": "phase_closure_candidate_ready" if ready else "phase_closure_review_blocked",
        "decision": "candidate_route_steward_phase_closure_review" if ready else "continue_phase_closure_blocker_burn_down",
        "summary": {
            "steward_ready_decision": source_review.get("decision"),
            "steward_ready_status": source_review.get("review_status"),
            "reviewed_packet_id": packet_id,
            "reviewed_packet_worker": worker,
            "action_history_record_count": record_count,
            "action_history_latest_action": history_summary.get("latest_action", ""),
            "action_history_latest_ok": latest_ok,
            "visual_smoke_ok": visual_ok,
            "visual_smoke_hash_route": visual_hash_route,
            "visual_smoke_receipt_path": visual_receipt_path,
            "visual_smoke_screenshot_path": visual_screenshot_path,
            "blocker_count": len(blockers),
        },
        "reviewed_packet": {
            "packet_id": packet_id,
            "lane_id": source_packet.get("lane_id"),
            "recommended_worker": worker,
            "work_class": source_packet.get("work_class"),
            "objective": source_packet.get("objective"),
        },
        "criteria": criteria,
        "blockers": blockers,
        "phase_closure_candidate": {
            "mission": phase_candidate.get("mission", "domain_weaver_queue_hygiene_and_multi_lane_mvp"),
            "phase": phase_candidate.get("phase", "codex_solo_work"),
            "recommended_status": "candidate_complete" if ready else "blocked_by_review",
            "accepted_state_claim": False,
            "reason": "Steward ready review, selected packet, action history, and browser visual smoke are current."
            if ready
            else "One or more phase-closure review criteria did not pass.",
        },
        "recommended_next_packet": dict(source_packet) if ready else {},
        "next_evolution_candidates": source_review.get("next_evolution_candidates") if ready else [],
        "evidence_refs": evidence_refs,
        "policy": "Phase closure review is candidate settlement only; it routes no live worker and writes no accepted state.",
        "authority": {
            "candidate_review_only": True,
            "phase_closure_authority": "candidate_only",
            "queue_mutation_authority": False,
            "active_registry_write_authority": False,
            "production_authority": False,
            "live_execution_authority": False,
            "accepted_state_authority": False,
            "secrets_authority": False,
        },
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }


def materialize_domain_weaver_phase_closure_review(
    root: str | Path | None = None,
    steward_ready_review: Mapping[str, Any] | None = None,
    visual_smoke: Mapping[str, Any] | None = None,
    action_history: Mapping[str, Any] | None = None,
    next_packet: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    shell_root = _resolve_root(root)
    review = build_domain_weaver_phase_closure_review(shell_root, steward_ready_review, visual_smoke, action_history, next_packet)
    review_path = shell_root / DOMAIN_WEAVER_PHASE_CLOSURE_REVIEW_PATH
    review_md_path = shell_root / DOMAIN_WEAVER_PHASE_CLOSURE_REVIEW_MD_PATH
    review_path.parent.mkdir(parents=True, exist_ok=True)
    review_path.write_text(json.dumps(review, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    review_md_path.write_text(_phase_closure_review_markdown(review), encoding="utf-8")
    receipt_dir = shell_root / DOMAIN_WEAVER_RECEIPT_DIR
    receipt_dir.mkdir(parents=True, exist_ok=True)
    receipt_path = receipt_dir / f"{_stamp()}_domain_weaver_phase_closure_review.json"
    summary = _as_mapping(review.get("summary"))
    result = {
        "schema_id": PHASE_CLOSURE_REVIEW_MATERIALIZATION_SCHEMA_ID,
        "ok": True,
        "created_at": _now(),
        "review_path": _rel(shell_root, review_path),
        "review_markdown_path": _rel(shell_root, review_md_path),
        "receipt_path": _rel(shell_root, receipt_path),
        "review_sha256": _sha256_file(review_path),
        "review_markdown_sha256": _sha256_file(review_md_path),
        "review_status": review.get("review_status"),
        "decision": review.get("decision"),
        "blocker_count": len([row for row in review.get("blockers") or [] if isinstance(row, Mapping)]),
        "reviewed_packet_id": summary.get("reviewed_packet_id"),
        "visual_smoke_receipt_path": summary.get("visual_smoke_receipt_path"),
        "visual_smoke_screenshot_path": summary.get("visual_smoke_screenshot_path"),
        "phase_closure_candidate": review.get("phase_closure_candidate") or {},
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    receipt_path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return result


def materialize_domain_weaver_promotion_review(
    root: str | Path | None = None,
    projection: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    shell_root = _resolve_root(root)
    source_projection = dict(projection or build_domain_weaver_projection(shell_root))
    review = build_domain_weaver_promotion_review(shell_root, source_projection)
    review_path = shell_root / DOMAIN_WEAVER_PROMOTION_REVIEW_PATH
    review_md_path = shell_root / DOMAIN_WEAVER_PROMOTION_REVIEW_MD_PATH
    draft_dir = shell_root / DOMAIN_WEAVER_PROMOTION_DRAFT_DIR
    review_path.parent.mkdir(parents=True, exist_ok=True)
    draft_dir.mkdir(parents=True, exist_ok=True)
    review_path.write_text(json.dumps(review, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    review_md_path.write_text(_promotion_review_markdown(review), encoding="utf-8")
    draft_paths: list[str] = []
    for decision in review.get("decisions") or []:
        if not isinstance(decision, Mapping) or not decision.get("ready_for_registry_draft"):
            continue
        path = shell_root / str(decision.get("candidate_draft_path") or "")
        if not path.is_relative_to(shell_root):
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(_candidate_domain_yaml(decision), encoding="utf-8")
        draft_paths.append(_rel(shell_root, path))
    receipt_dir = shell_root / DOMAIN_WEAVER_RECEIPT_DIR
    receipt_dir.mkdir(parents=True, exist_ok=True)
    receipt_path = receipt_dir / f"{_stamp()}_domain_weaver_promotion_review.json"
    result = {
        "schema_id": PROMOTION_MATERIALIZATION_SCHEMA_ID,
        "ok": True,
        "created_at": _now(),
        "review_path": _rel(shell_root, review_path),
        "review_markdown_path": _rel(shell_root, review_md_path),
        "receipt_path": _rel(shell_root, receipt_path),
        "review_sha256": _sha256_file(review_path),
        "review_markdown_sha256": _sha256_file(review_md_path),
        "candidate_draft_count": len(draft_paths),
        "candidate_draft_paths": draft_paths,
        "summary": review.get("summary") or {},
        "promotion_status": review.get("promotion_status"),
        "policy": review.get("policy"),
        "active_registry_write_count": 0,
        "accepted_state_count": 0,
        "production_authority": False,
        "live_execution_authority": False,
        "accepted_state_authority": False,
        "secrets_authority": False,
    }
    receipt_path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return result


